/**
 * 편집기·터미널·슬랙 단축키 161개의 한 줄 설명 — 열 언어.
 *
 * 키 이름은 어느 언어 안에서도 라틴 글자 그대로 둔다. Ctrl은 어디서나 Ctrl이고
 * Cmd는 Cmd다. 일본어가 「Ctrl+S を押すと…」라고 쓰는 것은 되지만 키 이름을
 * 옮기지는 않는다. 옮기는 것은 "무엇을 하는가"와 "무엇을 하나 틀리기 쉬운가"
 * 한 문장뿐이다 — /cmd와 /http가 명령과 상태 코드를 그렇게 다룬다.
 *
 * 열 칸을 배열로 적는다 — 순서는 ko·en·es·pt·ja·de·fr·hi·zh·tw.
 */
import type { Ten } from './types.ts';

export const SC_DESC_EDITOR: Record<string, Ten> = {
  /* ═════════ vscode ═════════ */

  /* ───────── Navigation ───────── */
  'vscode-command-palette': ["이름만 알면 vscode의 모든 명령을 여기서 실행합니다 — F1도 같은 창을 열고, 기본 단축키가 없는 명령은 이 창으로만 부를 수 있습니다.", "Runs any VS Code command by name — F1 opens the same box, and commands with no keybinding can be reached only this way.", "Ejecuta cualquier comando de VS Code por su nombre: F1 abre la misma ventana y los comandos sin atajo solo se alcanzan desde aquí.", "Executa qualquer comando do VS Code pelo nome: F1 abre a mesma caixa, e comandos sem atalho só chegam por aqui.", "名前を打つだけで VS Code のあらゆるコマンドを実行できます。F1 でも同じ窓が開き、キー割り当ての無いコマンドはここからしか呼べません。", "Führt jeden VS Code-Befehl über seinen Namen aus; F1 öffnet dasselbe Feld, und Befehle ohne Tastenkürzel erreicht man nur so.", "Exécute n'importe quelle commande de VS Code par son nom ; F1 ouvre la même boîte, et les commandes sans raccourci ne s'atteignent que par là.", "नाम टाइप करके VS Code का कोई भी command चलाता है; F1 वही खिड़की खोलता है, और जिन commands के लिए कोई key नहीं है वे यहीं से मिलते हैं।", "输入名字就能运行 VS Code 的任何命令；F1 打开的是同一个框，没有按键绑定的命令只能从这里调用。", "輸入名字就能執行 VS Code 的任何命令；F1 開的是同一個框，沒有按鍵繫結的命令只能從這裡呼叫。"],
  'vscode-quick-open': ["파일 이름 몇 글자로 파일을 엽니다. 뒤에 :120을 붙이면 그 파일의 120번째 줄로, @를 붙이면 그 파일의 심볼로 곧장 갑니다.", "Opens a file from a few letters of its name; append :120 to land on line 120 of it, or @ to jump straight to a symbol inside it.", "Abre un archivo con unas pocas letras de su nombre; añade :120 para caer en la línea 120 o @ para saltar a un símbolo dentro.", "Abre um arquivo com poucas letras do nome; acrescente :120 para cair na linha 120 ou @ para ir direto a um símbolo dele.", "ファイル名の数文字でファイルを開きます。後ろに :120 を付ければその 120 行目へ、@ を付ければ中の記号へ直接飛べます。", "Öffnet eine Datei anhand weniger Buchstaben ihres Namens; mit angehängtem :120 landet man in Zeile 120, mit @ direkt bei einem Symbol darin.", "Ouvre un fichier à partir de quelques lettres de son nom ; ajoutez :120 pour arriver à la ligne 120, ou @ pour sauter à un symbole à l'intérieur.", "नाम के कुछ अक्षरों से फ़ाइल खोलता है; आगे :120 लगाएँ तो उसी फ़ाइल की 120वीं पंक्ति पर, और @ लगाएँ तो उसके किसी symbol पर सीधे पहुँचते हैं।", "输入文件名的几个字母就能打开文件；后面加 :120 直接落到第 120 行，加 @ 则跳到文件里的符号。", "輸入檔名的幾個字母就能開啟檔案；後面加 :120 直接落到第 120 行，加 @ 則跳到檔案裡的符號。"],
  'vscode-go-to-line': ["줄 번호를 넣어 그 줄로 갑니다. 맥에서도 Cmd가 아니라 Ctrl+G인 드문 단축키입니다.", "Jumps to a line by number; unusually, it stays Ctrl+G on mac instead of moving to Cmd.", "Salta a una línea por su número; es uno de los pocos atajos que en mac sigue siendo Ctrl+G y no Cmd.", "Salta para uma linha pelo número; é um dos raros atalhos que no mac continua Ctrl+G em vez de Cmd.", "行番号を入れてその行へ飛びます。Mac でも Cmd ではなく Ctrl+G のままという珍しい割り当てです。", "Springt über die Zeilennummer zur Zeile; ungewöhnlich bleibt es auf dem Mac Ctrl+G statt Cmd.", "Saute à une ligne par son numéro ; fait rare, il reste Ctrl+G sur mac au lieu de passer à Cmd.", "पंक्ति संख्या डालकर उस पंक्ति पर पहुँचाता है; यह उन गिने-चुने shortcuts में है जो mac पर भी Cmd नहीं, Ctrl+G ही रहता है।", "输入行号跳到那一行；少见地，它在 mac 上仍是 Ctrl+G，而不是换成 Cmd。", "輸入行號跳到那一行；少見地，它在 mac 上仍是 Ctrl+G，而不是換成 Cmd。"],
  'vscode-go-to-symbol-in-file': ["지금 파일의 함수와 클래스 목록을 열어 골라 갑니다. 이름 앞에 :를 하나 더 치면 종류별로 묶어 보여 줍니다.", "Lists the functions and classes of the current file so you can pick one; type one more : to group them by kind.", "Lista las funciones y clases del archivo actual para elegir una; escribe otro : para agruparlas por tipo.", "Lista as funções e classes do arquivo atual para você escolher; digite outro : para agrupá-las por tipo.", "今のファイルの関数やクラスを一覧して選んで飛べます。もう一つ : を打つと種類ごとにまとめて表示されます。", "Listet Funktionen und Klassen der aktuellen Datei zur Auswahl; ein weiteres : gruppiert sie nach Art.", "Liste les fonctions et classes du fichier courant pour en choisir une ; tapez un : de plus pour les regrouper par type.", "मौजूदा फ़ाइल के functions और classes की सूची खोलकर चुनने देता है; एक और : टाइप करें तो वे प्रकार के हिसाब से समूह में दिखते हैं।", "列出当前文件的函数和类供你挑选；再输入一个 : 就会按种类分组显示。", "列出目前檔案的函式和類別供你挑選；再輸入一個 : 就會按種類分組顯示。"],
  'vscode-go-to-symbol-in-workspace': ["파일을 몰라도 프로젝트 전체에서 심볼 이름으로 찾아갑니다. 언어 확장이 색인을 만들기 전에는 결과가 비어 보입니다.", "Finds a symbol by name across the whole project even when you do not know the file; the list looks empty until the language extension has indexed it.", "Encuentra un símbolo por nombre en todo el proyecto aunque no sepas el archivo; la lista parece vacía hasta que la extensión del lenguaje termina de indexar.", "Encontra um símbolo pelo nome em todo o projeto mesmo sem saber o arquivo; a lista parece vazia até a extensão da linguagem indexar.", "ファイルが分からなくても、記号の名前でプロジェクト全体から探せます。言語拡張が索引を作り終えるまでは結果が空に見えます。", "Findet ein Symbol im ganzen Projekt allein über den Namen, auch ohne die Datei zu kennen; bis die Spracherweiterung indexiert hat, bleibt die Liste leer.", "Trouve un symbole par son nom dans tout le projet même sans connaître le fichier ; la liste paraît vide jusqu'à ce que l'extension du langage ait indexé.", "फ़ाइल न जानने पर भी पूरे project में symbol के नाम से खोज लेता है; जब तक language extension index नहीं बना लेता, सूची ख़ाली दिखती है।", "即使不知道在哪个文件，也能按符号名在整个项目里查找；语言扩展建好索引之前，结果看起来是空的。", "即使不知道在哪個檔案，也能按符號名在整個專案裡尋找；語言擴充建好索引之前，結果看起來是空的。"],
  'vscode-go-to-definition': ["이름이 실제로 정의된 자리로 건너갑니다. Ctrl+Click(맥은 Cmd+Click)도 똑같이 움직이고, 돌아올 때는 뒤로 가기를 씁니다.", "Jumps to where a name is actually defined; Ctrl+Click, or Cmd+Click on mac, does the same, and Go back brings you home.", "Salta a donde el nombre está definido de verdad; Ctrl+Click, o Cmd+Click en mac, hace lo mismo, y para volver se usa Ir atrás.", "Salta para onde o nome é realmente definido; Ctrl+Click, ou Cmd+Click no mac, faz o mesmo, e voltar é com Ir para trás.", "名前が実際に定義されている場所へ移ります。Ctrl+Click(Mac は Cmd+Click)も同じで、戻るときは戻る操作を使います。", "Springt dorthin, wo ein Name wirklich definiert ist; Ctrl+Click bzw. Cmd+Click auf dem Mac tut dasselbe, zurück geht es mit Zurück.", "Va là où le nom est réellement défini ; Ctrl+Click, ou Cmd+Click sur mac, fait la même chose, et on revient avec Reculer.", "जहाँ नाम असल में परिभाषित है वहाँ पहुँचाता है; Ctrl+Click (mac पर Cmd+Click) भी वही करता है, और लौटने के लिए पीछे जाना है।", "跳到这个名字真正定义的地方；Ctrl+单击（mac 上是 Cmd+单击）效果一样，回来则用后退。", "跳到這個名字真正定義的地方；Ctrl+點按（mac 上是 Cmd+點按）效果一樣，回來則用上一步。"],
  'vscode-peek-definition': ["정의를 작은 창으로 그 자리에 펼쳐 보여 줍니다. Esc로 닫히고, 그 창 안에서 고친 내용은 원래 파일에 그대로 저장됩니다.", "Shows the definition inline in a small window; Esc closes it, and edits you make inside it go into the real file.", "Muestra la definición en una ventanita ahí mismo; Esc la cierra, y lo que edites dentro va al archivo real.", "Mostra a definição em uma janelinha ali mesmo; Esc fecha, e o que você editar dentro vai para o arquivo de verdade.", "定義をその場に小さな窓で開いて見せます。Esc で閉じ、その中で直した内容は本体のファイルに入ります。", "Zeigt die Definition direkt an der Stelle in einem kleinen Fenster; Esc schließt es, und Änderungen darin landen in der echten Datei.", "Affiche la définition sur place dans une petite fenêtre ; Esc la ferme, et ce que vous y modifiez va dans le vrai fichier.", "परिभाषा को वहीं एक छोटी खिड़की में खोल देता है; Esc से बंद होती है, और उसके भीतर किए बदलाव असली फ़ाइल में जाते हैं।", "在原地用一个小窗口展开定义；Esc 关闭，在里面所做的修改会写进真正的文件。", "在原地用一個小視窗展開定義；Esc 關閉，在裡面所做的修改會寫進真正的檔案。"],
  'vscode-go-back': ["방금 있던 자리로 돌아갑니다. 윈도우는 Alt+Left인데 맥은 Cmd+[가 이미 내어쓰기라서 Ctrl+-를 씁니다.", "Returns to where the cursor just was; Windows uses Alt+Left, but on mac Cmd+[ is already outdent, so it is Ctrl+- there.", "Vuelve a donde estaba el cursor; en Windows es Alt+Left, pero en mac Cmd+[ ya es reducir sangría, así que allí es Ctrl+-.", "Volta para onde o cursor estava; no Windows é Alt+Left, mas no mac Cmd+[ já é diminuir recuo, então lá é Ctrl+-.", "直前にいた場所へ戻ります。Windows は Alt+Left ですが、Mac の Cmd+[ は既に字下げ解除なので Ctrl+- になります。", "Führt dorthin zurück, wo der Cursor eben war; Windows nutzt Alt+Left, auf dem Mac ist Cmd+[ schon Ausrücken, deshalb Ctrl+-.", "Ramène là où le curseur était juste avant ; Windows utilise Alt+Left, mais sur mac Cmd+[ sert déjà à désindenter, d'où Ctrl+-.", "जहाँ cursor अभी था वहीं लौटाता है; Windows पर Alt+Left है, पर mac पर Cmd+[ पहले से outdent है, इसलिए वहाँ Ctrl+- है।", "回到光标刚才所在的位置；Windows 是 Alt+Left，但 mac 上 Cmd+[ 已经是减少缩进，所以改成 Ctrl+-。", "回到游標剛才所在的位置；Windows 是 Alt+Left，但 mac 上 Cmd+[ 已經是減少縮排，所以改成 Ctrl+-。"],
  'vscode-go-forward': ["뒤로 간 만큼 다시 앞으로 갑니다. 이것도 맥에서는 Cmd가 아니라 Ctrl+Shift+-입니다.", "Moves forward again through the places you came back from; on mac this too is Ctrl+Shift+-, not a Cmd combination.", "Avanza de nuevo por los lugares de los que volviste; en mac también es Ctrl+Shift+-, no una combinación con Cmd.", "Avança de novo pelos lugares de onde você voltou; no mac também é Ctrl+Shift+-, e não uma combinação com Cmd.", "戻った分をもう一度先へ進みます。これも Mac では Cmd ではなく Ctrl+Shift+- です。", "Geht die zurückgelegten Sprünge wieder vorwärts; auch dies ist auf dem Mac Ctrl+Shift+- und keine Cmd-Kombination.", "Avance de nouveau dans les positions que vous avez quittées ; sur mac c'est aussi Ctrl+Shift+- et non une combinaison avec Cmd.", "जिन जगहों से आप लौटे थे, उनमें फिर आगे बढ़ता है; mac पर यह भी Cmd नहीं, Ctrl+Shift+- है।", "沿着你后退过的位置再往前走；这个在 mac 上也是 Ctrl+Shift+-，不是 Cmd 组合。", "沿著你上一步走過的位置再往前走；這個在 mac 上也是 Ctrl+Shift+-，不是 Cmd 組合。"],
  'vscode-jump-to-matching-bracket': ["짝이 되는 괄호로 커서를 보냅니다. 커서가 괄호 바로 옆에 있어야 움직이고, 한 번 더 누르면 원래 자리로 돌아옵니다.", "Sends the cursor to the matching bracket; the cursor has to sit next to a bracket for it to move, and pressing it again comes back.", "Lleva el cursor al paréntesis pareja; el cursor debe estar junto a uno para que funcione, y pulsarlo otra vez regresa.", "Leva o cursor ao par do parêntese; o cursor precisa estar ao lado de um para funcionar, e apertar de novo volta.", "対応する括弧へカーソルを送ります。カーソルが括弧のすぐ隣にないと動かず、もう一度押すと元の位置に戻ります。", "Setzt den Cursor auf die passende Klammer; er muss direkt neben einer Klammer stehen, und ein zweiter Druck führt zurück.", "Envoie le curseur sur la parenthèse correspondante ; il doit être juste à côté d'une parenthèse, et une seconde pression revient au départ.", "cursor को उसके जोड़े वाले bracket पर भेजता है; cursor किसी bracket के ठीक बग़ल में होना चाहिए, और दोबारा दबाने पर वापस आ जाता है।", "把光标送到配对的括号上；光标必须紧挨着括号才会动，再按一次又回到原处。", "把游標送到配對的括號上；游標必須緊挨著括號才會動，再按一次又回到原處。"],
  'vscode-next-problem': ["파일 안의 다음 문제로 커서를 옮기며 그 설명을 띄웁니다. 오류만이 아니라 경고와 정보까지 함께 돌기 때문에 셈이 예상보다 많습니다.", "Moves to the next problem in the file and pops up its message; it walks warnings and hints too, not just errors, so there are more stops than you expect.", "Va al siguiente problema del archivo y muestra su mensaje; recorre también avisos y sugerencias, no solo errores, así que hay más paradas de las que esperas.", "Vai ao próximo problema do arquivo e mostra a mensagem; ele passa também por avisos e dicas, não só erros, então há mais paradas do que se espera.", "ファイル内の次の問題へ移り、その説明を出します。エラーだけでなく警告やヒントも回るので、思ったより止まる回数が多くなります。", "Springt zum nächsten Problem in der Datei und zeigt dessen Meldung; es läuft auch Warnungen und Hinweise ab, nicht nur Fehler.", "Passe au problème suivant du fichier et affiche son message ; il parcourt aussi les avertissements et les conseils, pas seulement les erreurs.", "फ़ाइल की अगली समस्या पर ले जाकर उसका संदेश दिखाता है; यह केवल errors नहीं, warnings और सुझावों पर भी रुकता है, इसलिए पड़ाव ज़्यादा लगते हैं।", "跳到文件里的下一个问题并弹出说明；它不只走错误，还会走警告和提示，所以停的次数比你想的多。", "跳到檔案裡的下一個問題並彈出說明；它不只走錯誤，還會走警告和提示，所以停的次數比你想的多。"],
  'vscode-previous-problem': ["문제 목록을 거꾸로 한 칸 올라갑니다. 파일 끝에서 다시 처음으로 돌아 도니 같은 자리를 두 번 볼 수 있습니다.", "Steps one problem backwards; the walk wraps around at the top of the file, so you can meet the same spot twice.", "Retrocede un problema; el recorrido da la vuelta al llegar al principio del archivo, así que puedes ver el mismo punto dos veces.", "Volta um problema; a caminhada dá a volta no início do arquivo, então você pode ver o mesmo ponto duas vezes.", "問題を一つ前へ戻ります。ファイルの先頭で先頭から末尾へ回り込むので、同じ箇所を二度見ることがあります。", "Geht ein Problem zurück; der Rundlauf springt am Dateianfang wieder ans Ende, sodass dieselbe Stelle zweimal auftaucht.", "Recule d'un problème ; le parcours boucle en haut du fichier, si bien qu'on peut revoir le même endroit deux fois.", "एक समस्या पीछे ले जाता है; फ़ाइल के शुरू पर पहुँचकर चक्र घूम जाता है, इसलिए वही जगह दो बार मिल सकती है।", "往回退一个问题；走到文件开头会绕回末尾，所以同一处可能会看到两次。", "往回退一個問題；走到檔案開頭會繞回結尾，所以同一處可能會看到兩次。"],

  /* ───────── Search ───────── */
  'vscode-find': ["지금 파일에서 글자를 찾습니다. 찾기 창 안에서 Enter는 다음 것으로 넘어가는 뜻이고, Alt+Enter(맥은 Option+Enter)는 걸린 것을 모두 한꺼번에 선택합니다.", "Searches inside the current file; in the find box Enter means next match, and Alt+Enter, or Option+Enter on mac, selects every match at once.", "Busca dentro del archivo actual; en el cuadro de búsqueda Enter significa siguiente coincidencia, y Alt+Enter, o Option+Enter en mac, selecciona todas de golpe.", "Busca dentro do arquivo atual; na caixa de busca Enter significa próxima ocorrência, e Alt+Enter, ou Option+Enter no mac, seleciona todas de uma vez.", "今のファイルの中から文字を探します。検索欄の Enter は次の一致へ進む意味で、Alt+Enter(Mac は Option+Enter)は一致したものを一度に全部選びます。", "Sucht in der aktuellen Datei; im Suchfeld bedeutet Enter nächster Treffer, und Alt+Enter bzw. Option+Enter auf dem Mac markiert alle Treffer gleichzeitig.", "Cherche dans le fichier courant ; dans la zone de recherche, Enter signifie occurrence suivante, et Alt+Enter, ou Option+Enter sur mac, sélectionne toutes les occurrences d'un coup.", "मौजूदा फ़ाइल के भीतर खोजता है; खोज-बक्से में Enter का अर्थ अगला मेल है, और Alt+Enter (mac पर Option+Enter) सभी मेल एक साथ चुन लेता है।", "在当前文件里查找；查找框里的 Enter 是跳到下一个匹配，而 Alt+Enter（mac 上是 Option+Enter）会一次选中所有匹配。", "在目前檔案裡尋找；尋找框裡的 Enter 是跳到下一個符合處，而 Alt+Enter（mac 上是 Option+Enter）會一次選取所有符合處。"],
  'vscode-find-next': ["찾은 것 가운데 다음으로 넘어갑니다. 윈도우는 F3인데 맥은 Cmd+G라 두 기계를 함께 쓰면 가장 자주 헷갈리는 자리입니다.", "Moves to the next match; Windows uses F3 while mac uses Cmd+G, which is the pair people most often mix up when they work on both.", "Va a la siguiente coincidencia; en Windows es F3 y en mac Cmd+G, la pareja que más se confunde al trabajar en ambos.", "Vai para a próxima ocorrência; no Windows é F3 e no mac Cmd+G, o par que mais se confunde quando você usa as duas máquinas.", "見つかったもののうち次へ進みます。Windows は F3、Mac は Cmd+G で、両方を使う人が最も取り違える組み合わせです。", "Geht zum nächsten Treffer; Windows nutzt F3, der Mac Cmd+G — das Paar, das man beim Wechsel zwischen beiden am häufigsten verwechselt.", "Passe à l'occurrence suivante ; Windows utilise F3 et mac Cmd+G, la paire que l'on confond le plus en passant de l'un à l'autre.", "अगले मेल पर जाता है; Windows पर F3 और mac पर Cmd+G — दोनों मशीनें चलाने वालों की सबसे बड़ी गड़बड़ यहीं होती है।", "跳到下一个匹配；Windows 是 F3，mac 是 Cmd+G，两台机器换着用时最容易记错的就是这一对。", "跳到下一個符合處；Windows 是 F3，mac 是 Cmd+G，兩台機器換著用時最容易記錯的就是這一對。"],
  'vscode-find-previous': ["찾은 것 가운데 앞으로 되돌아갑니다. 찾기 창이 열려 있을 때는 Shift+Enter로도 같은 일을 합니다.", "Steps back to the previous match; with the find box open, Shift+Enter does the same thing.", "Retrocede a la coincidencia anterior; con el cuadro de búsqueda abierto, Shift+Enter hace lo mismo.", "Volta para a ocorrência anterior; com a caixa de busca aberta, Shift+Enter faz o mesmo.", "見つかったもののうち前へ戻ります。検索欄が開いているときは Shift+Enter でも同じことができます。", "Geht zum vorherigen Treffer zurück; bei offenem Suchfeld tut Shift+Enter dasselbe.", "Revient à l'occurrence précédente ; quand la zone de recherche est ouverte, Shift+Enter fait la même chose.", "पिछले मेल पर लौटता है; खोज-बक्सा खुला हो तो Shift+Enter भी यही करता है।", "退回上一个匹配；查找框打开时，Shift+Enter 也能做同样的事。", "退回上一個符合處；尋找框開著時，Shift+Enter 也能做同樣的事。"],
  'vscode-replace': ["찾기 창에 바꿀 칸을 함께 엽니다. 맥은 Cmd+H가 아닙니다 — 그것은 운영체제가 앱 감추기로 이미 가져갔고, vscode는 Cmd+Option+F를 씁니다.", "Opens find with a replace row; on mac it is not Cmd+H, because macOS already took that to hide the app, so VS Code uses Cmd+Option+F.", "Abre la búsqueda con la fila de reemplazo; en mac no es Cmd+H, porque el sistema ya lo usa para ocultar la app, así que VS Code usa Cmd+Option+F.", "Abre a busca com a linha de substituição; no mac não é Cmd+H, porque o sistema já usa isso para esconder o app, então o VS Code usa Cmd+Option+F.", "検索欄に置換の行を足して開きます。Mac は Cmd+H ではありません — それは OS がアプリを隠す操作に取っており、VS Code は Cmd+Option+F を使います。", "Öffnet die Suche mit einer Ersetzen-Zeile; auf dem Mac ist es nicht Cmd+H, denn das blendet dort die App aus, daher nutzt VS Code Cmd+Option+F.", "Ouvre la recherche avec la ligne de remplacement ; sur mac ce n'est pas Cmd+H, que le système réserve pour masquer l'application, donc VS Code utilise Cmd+Option+F.", "खोज के साथ बदलने की पंक्ति भी खोलता है; mac पर यह Cmd+H नहीं है, क्योंकि वह app छिपाने के लिए सिस्टम ने ले रखा है, इसलिए VS Code Cmd+Option+F रखता है।", "在查找框上加一行替换；mac 上不是 Cmd+H，因为系统已经用它隐藏应用，所以 VS Code 用 Cmd+Option+F。", "在尋找框上加一列取代；mac 上不是 Cmd+H，因為系統已經用它隱藏應用程式，所以 VS Code 用 Cmd+Option+F。"],
  'vscode-find-in-files': ["열지 않은 파일까지 프로젝트 전체를 훑습니다. .gitignore와 files.exclude에 걸린 것은 처음부터 빠지니, 안 나오면 설정 아이콘으로 제외 목록을 켜고 끕니다.", "Searches the whole project, including files you never opened; anything matched by .gitignore or files.exclude is skipped, so toggle those in the search options when a hit is missing.", "Busca en todo el proyecto, incluidos archivos que nunca abriste; lo que casa con .gitignore o files.exclude queda fuera, así que activa o desactiva esas exclusiones si falta un resultado.", "Busca em todo o projeto, inclusive arquivos que você nunca abriu; o que cai em .gitignore ou files.exclude é ignorado, então ajuste essas exclusões quando faltar um resultado.", "開いていないファイルまで含めてプロジェクト全体を探します。.gitignore や files.exclude に当たるものは初めから外れるので、出ないときは除外の設定を切り替えます。", "Durchsucht das ganze Projekt, auch nie geöffnete Dateien; was auf .gitignore oder files.exclude passt, bleibt außen vor — schalten Sie die Ausschlüsse um, wenn ein Treffer fehlt.", "Cherche dans tout le projet, y compris les fichiers jamais ouverts ; ce que visent .gitignore ou files.exclude est écarté, alors basculez ces exclusions si un résultat manque.", "पूरे project में खोजता है, उन फ़ाइलों में भी जो आपने कभी नहीं खोलीं; .gitignore या files.exclude में आने वाली चीज़ें छूट जाती हैं, इसलिए कोई परिणाम न मिले तो वे बहिष्करण बदलें।", "搜索整个项目，包括你从没打开过的文件；被 .gitignore 和 files.exclude 命中的会直接跳过，少结果时就去开关这些排除项。", "搜尋整個專案，包括你從沒開啟過的檔案；被 .gitignore 和 files.exclude 命中的會直接跳過，少結果時就去開關這些排除項。"],
  'vscode-replace-in-files': ["프로젝트 전체에서 한꺼번에 바꿉니다. 모두 바꾸기를 누르기 전에 파일별 미리보기를 펼쳐 볼 수 있고, 되돌리기는 파일마다 따로여서 되돌리기가 어렵습니다.", "Replaces across the whole project at once; you can expand the per-file preview before Replace All, and undo afterwards is file by file, so it is hard to take back.", "Reemplaza en todo el proyecto de una vez; puedes desplegar la vista previa por archivo antes de Reemplazar todo, y deshacer luego es archivo por archivo, así que cuesta revertirlo.", "Substitui em todo o projeto de uma vez; você pode abrir a prévia por arquivo antes de Substituir tudo, e desfazer depois é arquivo por arquivo, então é difícil voltar atrás.", "プロジェクト全体を一度に置換します。すべて置換の前にファイルごとの下見を開けますが、後からの取り消しはファイル単位なので元に戻すのは大変です。", "Ersetzt im gesamten Projekt auf einmal; vor Alle ersetzen lässt sich die Vorschau je Datei aufklappen, und das Rückgängig danach geht nur Datei für Datei.", "Remplace dans tout le projet d'un coup ; on peut déplier l'aperçu fichier par fichier avant Tout remplacer, et l'annulation ensuite se fait fichier par fichier.", "पूरे project में एक बार में बदल देता है; सब बदलने से पहले हर फ़ाइल की झलक खोल सकते हैं, और बाद में undo फ़ाइल-दर-फ़ाइल होता है, इसलिए वापस लाना कठिन है।", "一次替换整个项目；点全部替换前可以展开逐文件预览，而事后撤销是一个文件一个文件来的，很难收回。", "一次取代整個專案；按全部取代前可以展開逐檔預覽，而事後復原是一個檔案一個檔案來的，很難收回。"],
  /* ───────── Selection ───────── */
  'vscode-add-cursor-with-click': ["누른 자리마다 커서를 하나 더 놓습니다. 윈도우와 리눅스는 Alt+Click, 맥은 Option+Click이고, Esc를 누르면 커서가 다시 하나로 줄어듭니다.", "Drops an extra cursor wherever you click — Alt+Click on Windows and Linux, Option+Click on mac — and Esc collapses them back to one.", "Coloca un cursor más donde hagas clic: Alt+Click en Windows y Linux, Option+Click en mac, y Esc los vuelve a reducir a uno.", "Coloca um cursor a mais onde você clicar: Alt+Click no Windows e Linux, Option+Click no mac, e Esc reduz tudo a um cursor.", "クリックした場所ごとにカーソルを増やします。Windows と Linux は Alt+Click、Mac は Option+Click で、Esc を押すとカーソルは一つに戻ります。", "Setzt bei jedem Klick einen weiteren Cursor — Alt+Click unter Windows und Linux, Option+Click auf dem Mac — und Esc führt sie wieder zu einem zusammen.", "Ajoute un curseur à chaque clic : Alt+Click sous Windows et Linux, Option+Click sur mac, et Esc les ramène à un seul.", "जहाँ आप click करें वहाँ एक और cursor रख देता है — Windows और Linux पर Alt+Click, mac पर Option+Click — और Esc दबाने पर सब मिलकर एक cursor रह जाता है।", "在你点击的每个位置多放一个光标：Windows 和 Linux 上是 Alt+单击，mac 上是 Option+单击，按 Esc 又收回成一个。", "在你點按的每個位置多放一個游標：Windows 和 Linux 上是 Alt+點按，mac 上是 Option+點按，按 Esc 又收回成一個。"],
  'vscode-add-cursor-above': ["윗줄 같은 칸에 커서를 하나 더 얹습니다. 여러 줄 앞머리를 한꺼번에 고칠 때 쓰고, 줄이 짧으면 그 줄 끝에 붙습니다.", "Stacks another cursor on the line above at the same column; short lines put the cursor at their end instead.", "Añade otro cursor en la línea de arriba, en la misma columna; en las líneas cortas el cursor se pone al final.", "Adiciona outro cursor na linha de cima, na mesma coluna; em linhas curtas o cursor fica no fim delas.", "上の行の同じ桁にカーソルを一つ足します。行が短い場合はその行の末尾に付きます。", "Setzt einen weiteren Cursor in der Zeile darüber an dieselbe Spalte; bei kurzen Zeilen landet er an deren Ende.", "Ajoute un curseur sur la ligne du dessus, à la même colonne ; sur les lignes courtes il se place à la fin.", "ऊपर की पंक्ति में उसी column पर एक और cursor जोड़ता है; छोटी पंक्तियों में cursor उनके अंत पर बैठ जाता है।", "在上一行的同一列再加一个光标；行太短时光标就落在该行末尾。", "在上一行的同一欄再加一個游標；行太短時游標就落在該行結尾。"],
  'vscode-add-cursor-below': ["아랫줄 같은 칸에 커서를 하나 더 얹습니다. 맥에서는 Cmd+Option+Down이라 시스템 단축키와 겹치는 일이 적습니다.", "Stacks another cursor on the line below at the same column; on mac it is Cmd+Option+Down, which rarely collides with system shortcuts.", "Añade otro cursor en la línea de abajo, en la misma columna; en mac es Cmd+Option+Down, que casi nunca choca con atajos del sistema.", "Adiciona outro cursor na linha de baixo, na mesma coluna; no mac é Cmd+Option+Down, que raramente conflita com atalhos do sistema.", "下の行の同じ桁にカーソルを一つ足します。Mac では Cmd+Option+Down なので、OS の割り当てとぶつかることはほとんどありません。", "Setzt einen weiteren Cursor in der Zeile darunter an dieselbe Spalte; auf dem Mac ist es Cmd+Option+Down und kollidiert selten mit Systemkürzeln.", "Ajoute un curseur sur la ligne du dessous, à la même colonne ; sur mac c'est Cmd+Option+Down, qui entre rarement en conflit avec le système.", "नीचे की पंक्ति में उसी column पर एक और cursor जोड़ता है; mac पर यह Cmd+Option+Down है, जो सिस्टम shortcuts से कम टकराता है।", "在下一行的同一列再加一个光标；mac 上是 Cmd+Option+Down，很少和系统快捷键冲突。", "在下一行的同一欄再加一個游標；mac 上是 Cmd+Option+Down，很少和系統快速鍵衝突。"],
  'vscode-add-cursor-next-match': ["고른 낱말과 같은 다음 자리에 커서를 붙여 갑니다. 아무것도 고르지 않고 누르면 먼저 커서 밑의 낱말이 잡히고, 하나 더 붙었다가 잘못됐으면 Ctrl+U(맥은 Cmd+U)로 그 커서만 뗍니다.", "Adds a cursor at the next place the selection appears; with nothing selected the first press grabs the word under the cursor, and Ctrl+U, or Cmd+U on mac, removes the cursor you just added.", "Añade un cursor en la siguiente aparición de la selección; sin nada seleccionado, la primera pulsación toma la palabra bajo el cursor, y Ctrl+U, o Cmd+U en mac, quita el último cursor añadido.", "Adiciona um cursor na próxima ocorrência da seleção; sem nada selecionado, o primeiro toque pega a palavra sob o cursor, e Ctrl+U, ou Cmd+U no mac, remove o último cursor.", "選んだ語と同じ次の場所にカーソルを足していきます。何も選ばずに押すとまずカーソル下の語がつかまれ、足しすぎたときは Ctrl+U(Mac は Cmd+U)で今足したカーソルだけ外せます。", "Fügt einen Cursor an der nächsten Stelle der Auswahl hinzu; ohne Auswahl greift der erste Druck das Wort unter dem Cursor, und Ctrl+U bzw. Cmd+U nimmt den zuletzt gesetzten Cursor wieder weg.", "Ajoute un curseur à l'occurrence suivante de la sélection ; sans sélection, la première pression prend le mot sous le curseur, et Ctrl+U, ou Cmd+U sur mac, retire le dernier curseur ajouté.", "चयन जहाँ अगली बार आता है वहाँ एक cursor जोड़ता है; कुछ चुना न हो तो पहली दबाने पर cursor के नीचे का शब्द पकड़ लेता है, और Ctrl+U (mac पर Cmd+U) अभी जोड़ा गया cursor हटा देता है।", "在选中内容下一次出现的位置再加一个光标；什么都没选时第一下会先选中光标下的词，多加错了就用 Ctrl+U（mac 上 Cmd+U）只撤掉刚加的那个光标。", "在選取內容下一次出現的位置再加一個游標；什麼都沒選時第一下會先選取游標下的字，多加錯了就用 Ctrl+U（mac 上 Cmd+U）只撤掉剛加的那個游標。"],
  'vscode-select-all-matches': ["고른 글자와 같은 자리를 파일 안에서 모두 한꺼번에 고릅니다. 큰 파일에서는 커서가 수백 개 생겨 느려지니, 이름을 바꿀 것이라면 F2 쪽이 안전합니다.", "Selects every occurrence of the selection in the file at once; in a big file that can mean hundreds of cursors and a slow editor, so renaming is safer with F2.", "Selecciona de golpe todas las apariciones de la selección en el archivo; en archivos grandes eso son cientos de cursores y lentitud, así que para renombrar es más seguro F2.", "Seleciona de uma vez todas as ocorrências da seleção no arquivo; em arquivo grande isso vira centenas de cursores e lentidão, então para renomear F2 é mais seguro.", "選んだ文字と同じ場所をファイル内で一度に全部選びます。大きなファイルではカーソルが数百になって重くなるので、名前を変えるだけなら F2 の方が安全です。", "Markiert alle Vorkommen der Auswahl in der Datei gleichzeitig; in großen Dateien werden daraus Hunderte Cursor und ein träger Editor — zum Umbenennen ist F2 sicherer.", "Sélectionne d'un coup toutes les occurrences de la sélection dans le fichier ; dans un gros fichier cela fait des centaines de curseurs et ralentit tout, alors pour renommer F2 est plus sûr.", "फ़ाइल में चयन के सभी स्थान एक साथ चुन लेता है; बड़ी फ़ाइल में यह सैकड़ों cursor और सुस्ती बन जाता है, इसलिए नाम बदलना हो तो F2 सुरक्षित है।", "一次选中文件里所有相同的内容；大文件里这可能是几百个光标，编辑器会变卡，只是要改名的话用 F2 更稳。", "一次選取檔案裡所有相同的內容；大檔案裡這可能是幾百個游標，編輯器會變慢，只是要改名的話用 F2 更穩。"],
  'vscode-select-all-of-word': ["커서가 놓인 낱말을 파일 안에서 모두 골라 함께 고칩니다. 미리 고르지 않아도 되고, 낱말 경계까지 맞아야 잡히므로 부분만 같은 것은 빠집니다.", "Selects every occurrence of the word under the cursor so you can edit them together; you do not need a selection first, and it matches whole words only.", "Selecciona todas las apariciones de la palabra bajo el cursor para editarlas juntas; no hace falta seleccionar antes y solo casa palabras completas.", "Seleciona todas as ocorrências da palavra sob o cursor para editar juntas; não precisa selecionar antes e só casa palavras inteiras.", "カーソルの下にある語をファイル内で全部選んで一緒に直します。あらかじめ選ぶ必要はなく、語の境目まで一致したものだけがつかまれます。", "Markiert alle Vorkommen des Wortes unter dem Cursor zum gemeinsamen Bearbeiten; eine Auswahl ist nicht nötig, und es trifft nur ganze Wörter.", "Sélectionne toutes les occurrences du mot sous le curseur pour les modifier ensemble ; aucune sélection préalable n'est requise et seuls les mots entiers correspondent.", "cursor के नीचे वाले शब्द के सभी स्थान चुन लेता है ताकि सब एक साथ बदलें; पहले चुनना ज़रूरी नहीं, और यह केवल पूरे शब्द पकड़ता है।", "选中光标所在词在文件里的全部出现处，一起改；不必先选，而且只匹配完整的词。", "選取游標所在字詞在檔案裡的全部出現處，一起改；不必先選，而且只比對完整的字詞。"],
  'vscode-cursor-at-line-ends': ["고른 줄마다 끝에 커서를 하나씩 놓습니다. 여러 줄 끝에 쉼표나 세미콜론을 붙일 때 쓰는 것으로, 먼저 줄을 골라 두어야 합니다.", "Puts one cursor at the end of each selected line — the way to append a comma or semicolon to many lines — so select the lines first.", "Pone un cursor al final de cada línea seleccionada, la forma de añadir una coma o un punto y coma a muchas líneas, así que selecciona antes.", "Coloca um cursor no fim de cada linha selecionada, o jeito de acrescentar vírgula ou ponto e vírgula em muitas linhas, então selecione antes.", "選んだ行それぞれの末尾にカーソルを一つずつ置きます。複数行の末尾にカンマやセミコロンを足すための操作なので、先に行を選んでおきます。", "Setzt je einen Cursor an das Ende jeder markierten Zeile — so hängt man Kommas oder Semikolons an viele Zeilen; also vorher markieren.", "Place un curseur à la fin de chaque ligne sélectionnée : c'est ainsi qu'on ajoute une virgule ou un point-virgule à plusieurs lignes, il faut donc sélectionner d'abord.", "हर चुनी हुई पंक्ति के अंत में एक cursor रखता है — कई पंक्तियों के अंत में comma या semicolon जोड़ने का तरीका — इसलिए पहले पंक्तियाँ चुनें।", "在每一行被选中的行尾各放一个光标，这就是给多行末尾统一补逗号或分号的办法，所以要先选好行。", "在每一行被選取的行尾各放一個游標，這就是給多行結尾統一補逗號或分號的辦法，所以要先選好行。"],
  'vscode-column-selection': ["줄을 가로지르는 네모난 덩어리로 고릅니다. 마우스로는 Shift+Alt를 누르고 끌면 되고(맥은 Shift+Option), 그 칸까지 닿지 않는 짧은 줄에서는 아무것도 잡히지 않습니다.", "Selects a rectangular block across lines; with the mouse it is Shift+Alt+drag, or Shift+Option+drag on mac, and lines too short to reach the column contribute nothing.", "Selecciona un bloque rectangular a través de las líneas; con el ratón es Shift+Alt y arrastrar, o Shift+Option en mac, y las líneas demasiado cortas no aportan nada.", "Seleciona um bloco retangular através das linhas; com o mouse é Shift+Alt e arrastar, ou Shift+Option no mac, e linhas curtas demais não entram.", "行をまたぐ四角い塊として選びます。マウスなら Shift+Alt を押しながらドラッグ(Mac は Shift+Option)で、その桁に届かない短い行からは何も選ばれません。", "Markiert einen rechteckigen Block über mehrere Zeilen; mit der Maus Shift+Alt gedrückt ziehen, auf dem Mac Shift+Option, und zu kurze Zeilen liefern nichts.", "Sélectionne un bloc rectangulaire à travers les lignes ; à la souris, Shift+Alt et glisser, ou Shift+Option sur mac, et les lignes trop courtes n'apportent rien.", "पंक्तियों के आर-पार एक चौकोर खंड चुनता है; माउस से Shift+Alt दबाकर खींचें (mac पर Shift+Option), और जो पंक्तियाँ उस column तक नहीं पहुँचतीं उनसे कुछ नहीं चुना जाता।", "跨行选出一个矩形块；用鼠标是按住 Shift+Alt 拖动（mac 上 Shift+Option），够不到那一列的短行什么都选不到。", "跨行選出一個矩形區塊；用滑鼠是按住 Shift+Alt 拖曳（mac 上 Shift+Option），夠不到那一欄的短行什麼都選不到。"],
  'vscode-select-line': ["커서가 놓인 줄을 줄바꿈까지 통째로 고릅니다. 한 번 더 누르면 아랫줄까지 넓어지므로 여러 줄을 셋 넷 세듯 고를 수 있습니다.", "Selects the whole line the cursor is on, newline included; press it again and the selection grows one line at a time.", "Selecciona la línea completa donde está el cursor, salto de línea incluido; al pulsarlo otra vez la selección crece una línea más.", "Seleciona a linha inteira onde está o cursor, com a quebra de linha; apertando de novo a seleção cresce mais uma linha.", "カーソルのある行を改行まで丸ごと選びます。もう一度押すと下の行へ一行ずつ広がります。", "Markiert die ganze Zeile mit dem Cursor samt Zeilenumbruch; ein weiterer Druck erweitert die Auswahl um je eine Zeile.", "Sélectionne toute la ligne du curseur, saut de ligne compris ; une nouvelle pression étend la sélection d'une ligne.", "cursor वाली पूरी पंक्ति को newline सहित चुनता है; दोबारा दबाने पर चयन एक-एक पंक्ति बढ़ता जाता है।", "连换行符一起选中光标所在的整行；再按一次，选区就往下多扩一行。", "連換行字元一起選取游標所在的整行；再按一次，選取範圍就往下多擴一行。"],
  'vscode-expand-selection': ["문법 단위로 한 겹씩 넓혀 갑니다 — 낱말에서 문자열, 인수, 호출 전체로 자라고, 낱말 단위로 늘어나는 것이 아닙니다.", "Grows the selection one syntax layer at a time — word, then string, then argument, then the whole call — rather than word by word.", "Amplía la selección una capa de sintaxis a la vez: palabra, cadena, argumento y la llamada completa, no palabra a palabra.", "Amplia a seleção uma camada de sintaxe por vez: palavra, string, argumento e a chamada inteira, não palavra por palavra.", "文法の単位で一枚ずつ広げます — 語から文字列、引数、呼び出し全体へと育ち、語単位で伸びるのではありません。", "Erweitert die Auswahl um jeweils eine Syntaxschicht — Wort, String, Argument, ganzer Aufruf — und nicht Wort für Wort.", "Élargit la sélection d'une couche syntaxique à la fois — mot, chaîne, argument, puis l'appel entier — et non mot par mot.", "चयन को एक-एक वाक्य-रचना परत बढ़ाता है — शब्द, फिर string, फिर argument, फिर पूरा call — शब्द-दर-शब्द नहीं।", "按语法层级一层层扩大选区：词、字符串、参数、整个调用，而不是一个词一个词地扩。", "按語法層級一層層擴大選取範圍：字詞、字串、引數、整個呼叫，而不是一個字一個字地擴。"],
  'vscode-shrink-selection': ["넓혔던 문법 단위를 한 겹씩 되돌립니다. 넓히기와 짝이라, 한 겹 지나쳤을 때 처음부터 다시 고르지 않아도 됩니다.", "Peels the syntax layers back off one at a time; it is the twin of expand, so overshooting by one layer costs nothing.", "Quita las capas de sintaxis una por una; es el gemelo de ampliar, así que pasarse una capa no cuesta nada.", "Remove as camadas de sintaxe uma a uma; é o gêmeo de ampliar, então passar uma camada não custa nada.", "広げた文法の単位を一枚ずつ戻します。広げる操作の対なので、一枚行き過ぎても選び直す必要はありません。", "Schält die Syntaxschichten einzeln wieder ab; als Gegenstück zum Erweitern kostet ein Schritt zu weit nichts.", "Retire les couches syntaxiques une à une ; jumeau de l'élargissement, dépasser d'un cran ne coûte rien.", "बढ़ाई गई वाक्य-रचना परतें एक-एक वापस हटाता है; यह बढ़ाने का जोड़ीदार है, इसलिए एक परत आगे निकल जाना कोई नुक़सान नहीं।", "把扩大的语法层级一层层收回；它和扩大是一对，多扩了一层也不必重新选。", "把擴大的語法層級一層層收回；它和擴大是一對，多擴了一層也不必重新選。"],

  /* ───────── Editing ───────── */
  'vscode-move-line-up': ["줄을 통째로 위로 옮기고 들여쓰기를 새 자리에 맞춥니다. 미리 고를 필요가 없고, 여러 줄을 골라 두면 그 덩어리가 함께 올라갑니다.", "Lifts the whole line up one row and re-indents it for its new place; no selection is needed, and a selected block moves together.", "Sube la línea entera una fila y reajusta la sangría a su nuevo sitio; no hace falta seleccionar, y un bloque seleccionado sube junto.", "Sobe a linha inteira uma fileira e reajusta o recuo ao novo lugar; não precisa selecionar, e um bloco selecionado sobe junto.", "行を丸ごと一つ上へ移し、新しい位置に合わせて字下げを直します。選ばなくてもよく、複数行を選んでおけばその塊ごと上がります。", "Hebt die ganze Zeile eine Position nach oben und rückt sie am neuen Platz passend ein; eine Auswahl ist unnötig, ein markierter Block wandert gemeinsam.", "Fait monter la ligne entière d'un cran et réajuste son indentation ; aucune sélection n'est nécessaire, et un bloc sélectionné monte d'un bloc.", "पूरी पंक्ति को एक पायदान ऊपर ले जाता है और नई जगह के हिसाब से indent ठीक कर देता है; चुनना ज़रूरी नहीं, और चुना हुआ खंड एक साथ ऊपर जाता है।", "把整行往上挪一行，并按新位置重排缩进；不必先选，选了一段就整段一起上移。", "把整行往上挪一行，並按新位置重排縮排；不必先選，選了一段就整段一起上移。"],
  'vscode-move-line-down': ["줄을 통째로 아래로 옮깁니다. 잘라 붙이기와 달리 클립보드를 건드리지 않아, 복사해 둔 것이 그대로 남습니다.", "Drops the whole line down one row; unlike cut and paste it never touches the clipboard, so whatever you copied is still there.", "Baja la línea entera una fila; a diferencia de cortar y pegar no toca el portapapeles, así que lo copiado sigue intacto.", "Desce a linha inteira uma fileira; diferente de cortar e colar, não mexe na área de transferência, então o que você copiou continua lá.", "行を丸ごと一つ下へ移します。切り取り貼り付けと違ってクリップボードを触らないので、コピーしておいたものはそのまま残ります。", "Schiebt die ganze Zeile eine Position nach unten; anders als Ausschneiden und Einfügen bleibt die Zwischenablage unberührt.", "Fait descendre la ligne entière d'un cran ; contrairement au couper-coller, le presse-papiers reste intact.", "पूरी पंक्ति को एक पायदान नीचे ले जाता है; cut-paste की तरह नहीं, यह clipboard को छूता ही नहीं, इसलिए copy किया हुआ बचा रहता है।", "把整行往下挪一行；和剪切粘贴不同，它完全不动剪贴板，你复制的东西还在。", "把整行往下挪一行；和剪下貼上不同，它完全不動剪貼簿，你複製的東西還在。"],
  'vscode-copy-line-up': ["줄을 하나 복사해 위에 놓습니다. vscode에는 줄 복제에 기본 단축키가 따로 없어서, 사람들이 찾는 그 기능이 바로 이것입니다.", "Duplicates the line and puts the copy above; VS Code ships no separate duplicate-line keybinding, so this is the one people are looking for.", "Duplica la línea y pone la copia arriba; VS Code no trae un atajo aparte para duplicar líneas, así que este es el que se busca.", "Duplica a linha e põe a cópia acima; o VS Code não traz um atalho separado para duplicar linha, então este é o que as pessoas procuram.", "行を一つ複写して上に置きます。VS Code には行の複製に既定のキーが別にないので、探しているのはこの操作です。", "Verdoppelt die Zeile und setzt die Kopie darüber; VS Code hat kein eigenes Kürzel für Zeile duplizieren — gesucht ist genau dieses.", "Duplique la ligne et place la copie au-dessus ; VS Code n'a pas de raccourci distinct pour dupliquer une ligne, c'est donc celui-ci qu'on cherche.", "पंक्ति की नक़ल बनाकर ऊपर रख देता है; VS Code में पंक्ति duplicate करने का अलग key नहीं है, इसलिए लोग जिसे खोजते हैं वह यही है।", "复制一行并把副本放到上面；VS Code 没有单独的复制行快捷键，大家找的其实就是它。", "複製一行並把副本放到上面；VS Code 沒有單獨的複製行快速鍵，大家找的其實就是它。"],
  'vscode-copy-line-down': ["줄을 하나 복사해 아래에 놓고 커서를 복사본으로 옮깁니다. 그래서 붙여 놓고 곧바로 고쳐 쓸 수 있습니다.", "Duplicates the line below and leaves the cursor in the copy, so you can start editing the new line right away.", "Duplica la línea abajo y deja el cursor en la copia, así puedes editar la nueva línea de inmediato.", "Duplica a linha abaixo e deixa o cursor na cópia, então você já edita a linha nova.", "行を一つ下に複写し、カーソルを複写した側へ移します。だから貼った直後にそのまま直せます。", "Verdoppelt die Zeile nach unten und lässt den Cursor in der Kopie, sodass man sofort weiterschreiben kann.", "Duplique la ligne en dessous et laisse le curseur dans la copie, ce qui permet de la modifier tout de suite.", "पंक्ति की नक़ल नीचे रखकर cursor को नक़ल पर छोड़ देता है, इसलिए नई पंक्ति तुरंत बदल सकते हैं।", "在下面复制一行，并把光标留在副本里，所以可以马上接着改。", "在下面複製一行，並把游標留在副本裡，所以可以馬上接著改。"],
  'vscode-delete-line': ["고른 것이 없어도 커서가 놓인 줄을 지웁니다. 지운 줄은 클립보드에 남지 않으니, 되붙일 셈이라면 Ctrl+X로 잘라야 합니다.", "Deletes the line under the cursor even with nothing selected; the line does not go to the clipboard, so cut it with Ctrl+X if you mean to paste it back.", "Borra la línea del cursor aunque no haya selección; esa línea no va al portapapeles, así que usa Ctrl+X si piensas volver a pegarla.", "Apaga a linha do cursor mesmo sem seleção; ela não vai para a área de transferência, então use Ctrl+X se quiser colar de volta.", "何も選んでいなくてもカーソルのある行を消します。消した行はクリップボードに残らないので、貼り直すつもりなら Ctrl+X で切り取ります。", "Löscht die Zeile unter dem Cursor auch ohne Auswahl; die Zeile landet nicht in der Zwischenablage — zum Wiedereinfügen mit Ctrl+X ausschneiden.", "Supprime la ligne du curseur même sans sélection ; cette ligne ne va pas dans le presse-papiers, utilisez Ctrl+X si vous voulez la recoller.", "कुछ चुना न हो तब भी cursor वाली पंक्ति मिटा देता है; वह पंक्ति clipboard में नहीं जाती, इसलिए फिर चिपकाना हो तो Ctrl+X से काटें।", "即使什么都没选，也会删掉光标所在行；这一行不会进剪贴板，想再粘回来就得用 Ctrl+X 剪切。", "即使什麼都沒選，也會刪掉游標所在行；這一行不會進剪貼簿，想再貼回來就得用 Ctrl+X 剪下。"],
  'vscode-insert-line-below': ["줄 어디에 있든 아래에 새 줄을 열고 그리로 내려갑니다. 줄 끝까지 커서를 옮긴 다음 Enter를 칠 필요가 없습니다.", "Opens a new line below and moves there from anywhere in the line, so you never have to walk the cursor to the end and press Enter.", "Abre una línea nueva debajo y baja a ella desde cualquier punto de la línea, sin tener que llevar el cursor al final y pulsar Enter.", "Abre uma linha nova abaixo e desce para ela de qualquer ponto da linha, sem precisar levar o cursor ao fim e apertar Enter.", "行のどこにいても下に新しい行を開いてそこへ移ります。末尾までカーソルを送って Enter を押す必要はありません。", "Öffnet eine neue Zeile darunter und springt hin, egal wo im Text der Cursor steht — kein Weg zum Zeilenende und kein Enter nötig.", "Ouvre une nouvelle ligne en dessous et y descend depuis n'importe où dans la ligne, sans amener le curseur à la fin pour appuyer sur Enter.", "पंक्ति में कहीं भी हों, नीचे नई पंक्ति खोलकर वहाँ ले जाता है; cursor को अंत तक ले जाकर Enter दबाने की ज़रूरत नहीं।", "无论光标在行中哪里，都会在下面开一新行并跳过去，不用先把光标移到行尾再按 Enter。", "無論游標在行中哪裡，都會在下面開一新行並跳過去，不用先把游標移到行尾再按 Enter。"],
  'vscode-insert-line-above': ["줄 어디에 있든 위에 새 줄을 열고 그리로 올라갑니다. import 한 줄이나 주석을 위에 끼워 넣을 때 가장 빠릅니다.", "Opens a new line above and moves there from anywhere in the line — the quickest way to slip in an import or a comment.", "Abre una línea nueva arriba y sube a ella desde cualquier punto de la línea: lo más rápido para colar un import o un comentario.", "Abre uma linha nova acima e sobe para ela de qualquer ponto da linha: o jeito mais rápido de encaixar um import ou comentário.", "行のどこにいても上に新しい行を開いてそこへ移ります。import 一行やコメントを差し込むのに最も速い方法です。", "Öffnet eine neue Zeile darüber und springt hin — der schnellste Weg, ein Import oder einen Kommentar einzuschieben.", "Ouvre une nouvelle ligne au-dessus et y monte depuis n'importe où : le plus rapide pour glisser un import ou un commentaire.", "पंक्ति में कहीं भी हों, ऊपर नई पंक्ति खोलकर वहाँ ले जाता है — import या टिप्पणी घुसाने का सबसे तेज़ तरीक़ा।", "无论光标在行中哪里，都会在上面开一新行并跳过去，插一行 import 或注释最快。", "無論游標在行中哪裡，都會在上面開一新行並跳過去，插一行 import 或註解最快。"],
  'vscode-indent-line': ["커서가 줄 어디에 있어도 그 줄을 한 단 들여씁니다. Tab은 고른 것이 있을 때만 이렇게 움직이고, 그러지 않으면 그 자리에 탭을 넣습니다.", "Indents the whole line wherever the cursor sits; Tab only does this when text is selected, otherwise it inserts a tab at the cursor.", "Aumenta la sangría de toda la línea esté donde esté el cursor; Tab solo hace esto si hay texto seleccionado, si no inserta un tabulador.", "Aumenta o recuo da linha inteira onde o cursor estiver; Tab só faz isso com texto selecionado, senão insere uma tabulação.", "カーソルが行のどこにあってもその行を一段字下げします。Tab は選択があるときだけ同じ働きをし、そうでなければその場にタブを入れます。", "Rückt die ganze Zeile ein, egal wo der Cursor steht; Tab tut das nur bei markiertem Text, sonst fügt es einen Tabulator ein.", "Indente toute la ligne où que soit le curseur ; Tab ne fait cela que si du texte est sélectionné, sinon il insère une tabulation.", "cursor पंक्ति में कहीं भी हो, पूरी पंक्ति एक स्तर indent कर देता है; Tab ऐसा केवल चयन होने पर करता है, वरना वहीं एक tab डाल देता है।", "光标在行里任何位置都能把整行缩进一级；Tab 只在有选中文本时这样，否则只是在光标处插入一个制表符。", "游標在行裡任何位置都能把整行縮排一級；Tab 只在有選取文字時這樣，否則只是在游標處插入一個定位字元。"],
  'vscode-outdent-line': ["줄을 한 단 내어씁니다. 맥의 Cmd+[가 여기에 쓰이기 때문에, 뒤로 가기가 Ctrl+-로 밀려났습니다.", "Outdents the line by one step; because mac spends Cmd+[ here, Go back had to move to Ctrl+- there.", "Reduce la sangría de la línea un paso; como en mac Cmd+[ se usa aquí, Ir atrás tuvo que pasar a Ctrl+-.", "Diminui o recuo da linha um passo; como no mac Cmd+[ é usado aqui, Ir para trás teve de mudar para Ctrl+-.", "行を一段外へ出します。Mac ではこの Cmd+[ が使われているため、戻る操作が Ctrl+- に押し出されました。", "Rückt die Zeile eine Stufe aus; weil der Mac Cmd+[ hierfür verbraucht, musste Zurück dort auf Ctrl+- ausweichen.", "Désindente la ligne d'un cran ; comme mac consacre Cmd+[ à cela, Reculer a dû se déplacer vers Ctrl+-.", "पंक्ति का indent एक स्तर घटाता है; mac पर Cmd+[ यहीं ख़र्च होता है, इसलिए पीछे जाना Ctrl+- पर खिसक गया।", "把行的缩进减一级；正因为 mac 把 Cmd+[ 用在这里，后退才被挪到 Ctrl+-。", "把行的縮排減一級；正因為 mac 把 Cmd+[ 用在這裡，上一步才被挪到 Ctrl+-。"],
  'vscode-toggle-line-comment': ["줄을 주석으로 만들거나 되돌립니다. 주석 기호는 파일의 언어 모드에서 오므로, 모드가 틀리면 엉뚱한 기호가 붙습니다.", "Comments the line out or brings it back; the comment characters come from the file's language mode, so a wrong mode inserts the wrong marker.", "Comenta la línea o la restaura; los caracteres de comentario vienen del modo de lenguaje del archivo, así que un modo equivocado pone el marcador equivocado.", "Comenta a linha ou traz de volta; os caracteres de comentário vêm do modo de linguagem do arquivo, então um modo errado insere o marcador errado.", "行をコメントにしたり戻したりします。コメント記号はファイルの言語モードから来るので、モードが違うと見当違いの記号が付きます。", "Kommentiert die Zeile aus oder holt sie zurück; die Kommentarzeichen stammen aus dem Sprachmodus der Datei — ein falscher Modus setzt das falsche Zeichen.", "Met la ligne en commentaire ou l'en sort ; les marqueurs viennent du mode de langage du fichier, donc un mauvais mode insère le mauvais signe.", "पंक्ति को टिप्पणी बनाता या वापस लाता है; टिप्पणी चिह्न फ़ाइल के language mode से आते हैं, इसलिए mode ग़लत हो तो ग़लत चिह्न लगता है।", "把这一行注释掉或取消注释；注释符号来自文件的语言模式，模式选错就会插入不对的符号。", "把這一行註解掉或取消註解；註解符號來自檔案的語言模式，模式選錯就會插入不對的符號。"],
  'vscode-toggle-block-comment': ["고른 덩어리를 여닫는 주석으로 감쌉니다. 그런 주석이 없는 언어에서는 줄 주석으로 대신 처리되고, 고른 것이 없으면 커서 자리에 빈 주석이 열립니다.", "Wraps the selection in an opening and closing comment; languages without block comments fall back to line comments, and with no selection it opens an empty pair at the cursor.", "Envuelve la selección en un comentario de apertura y cierre; los lenguajes sin comentarios de bloque usan comentarios de línea, y sin selección abre un par vacío en el cursor.", "Envolve a seleção em um comentário de abrir e fechar; linguagens sem comentário de bloco caem no de linha, e sem seleção abre um par vazio no cursor.", "選んだ塊を開き閉じのコメントで包みます。そうしたコメントが無い言語では行コメントで代わりに処理され、選択が無ければカーソル位置に空の対が開きます。", "Umschließt die Auswahl mit einem öffnenden und schließenden Kommentar; Sprachen ohne Blockkommentar weichen auf Zeilenkommentare aus, ohne Auswahl entsteht ein leeres Paar am Cursor.", "Entoure la sélection d'un commentaire ouvrant et fermant ; les langages sans commentaire de bloc retombent sur des commentaires de ligne, et sans sélection une paire vide s'ouvre au curseur.", "चयन को खुलने-बंद होने वाली टिप्पणी में लपेटता है; जिन भाषाओं में block comment नहीं है वहाँ line comment लगता है, और चयन न हो तो cursor पर ख़ाली जोड़ा खुल जाता है।", "把选中的内容用成对的注释包起来；没有块注释的语言退回到行注释，什么都没选时会在光标处开一对空注释。", "把選取的內容用成對的註解包起來；沒有區塊註解的語言退回到行註解，什麼都沒選時會在游標處開一對空註解。"],
  'vscode-trim-trailing-whitespace': ["줄 끝에 남은 빈칸을 모두 털어 냅니다. 저장할 때마다 저절로 하려면 files.trimTrailingWhitespace를 켜 둡니다.", "Strips the spaces left at the end of every line; turn on files.trimTrailingWhitespace to have it happen on every save.", "Quita los espacios que quedan al final de cada línea; activa files.trimTrailingWhitespace para que ocurra en cada guardado.", "Remove os espaços que sobram no fim de cada linha; ligue files.trimTrailingWhitespace para isso acontecer a cada salvamento.", "行末に残った空白をすべて払い落とします。保存のたびに自動でやらせるには files.trimTrailingWhitespace を有効にします。", "Entfernt die Leerzeichen am Ende jeder Zeile; mit files.trimTrailingWhitespace passiert das bei jedem Speichern.", "Supprime les espaces restés en fin de chaque ligne ; activez files.trimTrailingWhitespace pour que cela se fasse à chaque enregistrement.", "हर पंक्ति के अंत में बचे space हटा देता है; हर बार सहेजने पर यही हो, इसके लिए files.trimTrailingWhitespace चालू रखें।", "清掉每行末尾多余的空格；想每次保存都自动做，就打开 files.trimTrailingWhitespace。", "清掉每行結尾多餘的空格；想每次儲存都自動做，就打開 files.trimTrailingWhitespace。"],
  /* ───────── Code ───────── */
  'vscode-format-document': ["파일 전체를 그 언어의 서식기에 맞춰 다시 정돈합니다. 서식기가 없으면 아무 일도 없이 무엇을 쓸지 묻는 창만 뜹니다.", "Reformats the whole file with the formatter for that language; with no formatter installed nothing happens except a prompt asking you to pick one.", "Reformatea todo el archivo con el formateador de ese lenguaje; si no hay ninguno instalado, solo aparece un aviso pidiendo que elijas uno.", "Reformata o arquivo inteiro com o formatador daquela linguagem; sem formatador instalado nada acontece além de um aviso pedindo para escolher um.", "ファイル全体をその言語の整形器に合わせて組み直します。整形器が無い場合は何も起きず、どれを使うか尋ねる表示だけが出ます。", "Formatiert die ganze Datei mit dem Formatierer der Sprache; ist keiner installiert, passiert nichts außer der Frage, welchen Sie wählen.", "Reformate tout le fichier avec le formateur du langage ; sans formateur installé, rien ne se passe hormis une invite à en choisir un.", "पूरी फ़ाइल को उस भाषा के formatter से फिर से सजाता है; कोई formatter न हो तो कुछ नहीं होता, बस कौन सा चुनें यह पूछा जाता है।", "用该语言的格式化程序重排整个文件；没装格式化程序时什么都不会发生，只会弹出让你选一个的提示。", "用該語言的格式化程式重排整個檔案；沒裝格式化程式時什麼都不會發生，只會彈出讓你選一個的提示。"],
  'vscode-format-selection': ["고른 부분만 다시 정돈합니다. 파일 전체를 건드리면 남의 줄까지 바뀌어 커밋이 지저분해질 때 이것을 씁니다.", "Reformats only what you selected — the way out when formatting the whole file would touch other people's lines and muddy the commit.", "Reformatea solo lo seleccionado: la salida cuando formatear todo el archivo tocaría líneas ajenas y ensuciaría el commit.", "Reformata só o que você selecionou: a saída quando formatar o arquivo inteiro mexeria em linhas alheias e sujaria o commit.", "選んだところだけを組み直します。ファイル全体を触ると他人の行まで変わって履歴が汚れる、そんなときに使います。", "Formatiert nur die Auswahl — der Ausweg, wenn das Formatieren der ganzen Datei fremde Zeilen anfasst und den Commit verschmutzt.", "Reformate seulement la sélection : la solution quand formater tout le fichier toucherait les lignes des autres et salirait le commit.", "केवल चुने हुए हिस्से को फिर सजाता है — जब पूरी फ़ाइल छूने से दूसरों की पंक्तियाँ बदलकर commit गंदा हो जाए, तब यही रास्ता है।", "只重排选中的部分——当格式化整个文件会动到别人的行、把提交搞乱时，就用它。", "只重排選取的部分——當格式化整個檔案會動到別人的行、把提交弄亂時，就用它。"],
  'vscode-rename-symbol': ["이름을 참조하는 자리까지 함께 바꿉니다. 언어 서버가 뜻을 알고 고치므로, 문자열이나 주석 속의 같은 글자는 건드리지 않습니다.", "Renames a symbol together with every reference to it; the language server understands the code, so the same letters inside strings and comments are left alone.", "Renombra un símbolo junto con todas sus referencias; el servidor de lenguaje entiende el código, así que las mismas letras dentro de cadenas y comentarios se quedan igual.", "Renomeia um símbolo junto com todas as referências; o servidor de linguagem entende o código, então as mesmas letras dentro de strings e comentários ficam intactas.", "名前を参照している場所まで一緒に書き換えます。言語サーバーが意味を分かって直すので、文字列やコメントの中の同じ文字は触りません。", "Benennt ein Symbol samt aller Verweise um; der Sprachserver versteht den Code, deshalb bleiben gleiche Zeichen in Strings und Kommentaren unangetastet.", "Renomme un symbole avec toutes ses références ; le serveur de langage comprend le code, donc les mêmes lettres dans les chaînes et les commentaires ne bougent pas.", "किसी symbol को उसके सभी संदर्भों के साथ बदल देता है; language server अर्थ समझकर बदलता है, इसलिए strings और टिप्पणियों में वही अक्षर अछूते रहते हैं।", "把一个符号连同它的所有引用一起改名；语言服务器懂代码，所以字符串和注释里相同的字不会被动。", "把一個符號連同它的所有引用一起改名；語言伺服器懂程式碼，所以字串和註解裡相同的字不會被動。"],
  'vscode-quick-fix': ["전구가 들고 있는 고침 목록을 엽니다. 오류가 없는 자리에서도 열려서, import 넣기나 작은 리팩터링을 여기서 고를 수 있습니다.", "Opens the lightbulb menu of fixes; it opens where there is no error too, offering missing imports and small refactors.", "Abre el menú de la bombilla con las correcciones; también se abre donde no hay error y ofrece imports que faltan y pequeñas refactorizaciones.", "Abre o menu da lâmpada com as correções; também abre onde não há erro, oferecendo imports que faltam e pequenas refatorações.", "電球が持っている修正の一覧を開きます。エラーの無い場所でも開き、import の追加や小さな書き換えを選べます。", "Öffnet das Glühbirnen-Menü mit Korrekturen; es öffnet auch ohne Fehler und bietet fehlende Imports und kleine Umbauten an.", "Ouvre le menu de l'ampoule avec les correctifs ; il s'ouvre aussi là où il n'y a pas d'erreur et propose des imports manquants et de petits remaniements.", "बल्ब वाले सुधारों की सूची खोलता है; जहाँ कोई त्रुटि नहीं है वहाँ भी खुलता है और छूटे import या छोटे refactor सुझाता है।", "打开灯泡里的修复菜单；没有错误的地方也能打开，可以补 import 或做小重构。", "打開燈泡裡的修復選單；沒有錯誤的地方也能打開，可以補 import 或做小重構。"],
  'vscode-trigger-suggest': ["자동 완성 목록을 손으로 불러냅니다. 맥에서도 Ctrl+Space라서, 입력기 전환을 그 키에 둔 사람은 둘이 부딪칩니다.", "Calls up the completion list by hand; on mac it is Ctrl+Space as well, so it clashes for anyone who left the input-source switch on that key.", "Abre a mano la lista de autocompletado; en mac también es Ctrl+Space, así que choca con quien tenga el cambio de teclado en esa tecla.", "Chama a lista de autocompletar na mão; no mac também é Ctrl+Space, então briga com quem deixou a troca de idioma nessa tecla.", "補完の一覧を手で呼び出します。Mac でも Ctrl+Space なので、入力ソースの切り替えをそのキーに残している人はぶつかります。", "Ruft die Vorschlagsliste von Hand auf; auf dem Mac ist es ebenfalls Ctrl+Space und kollidiert mit dem dort belegten Wechsel der Eingabequelle.", "Appelle à la main la liste de complétion ; sur mac c'est aussi Ctrl+Space, ce qui entre en conflit avec le changement de source de saisie.", "स्वतः पूर्ति की सूची हाथ से बुलाता है; mac पर भी यह Ctrl+Space है, इसलिए जिनके यहाँ input source बदलना उसी key पर है, उनका टकराव होता है।", "手动调出补全列表；mac 上也是 Ctrl+Space，所以把输入法切换留在这个键上的人会冲突。", "手動叫出自動完成清單；mac 上也是 Ctrl+Space，所以把輸入法切換留在這個鍵上的人會衝突。"],
  'vscode-parameter-hints': ["지금 들어가 있는 호출의 인수 목록을 띄웁니다. 괄호 밖으로 나가면 사라지므로, 괄호 안에서 눌러야 보입니다.", "Shows the argument list of the call you are inside; it disappears once the cursor leaves the parentheses, so press it in there.", "Muestra la lista de argumentos de la llamada en la que estás; desaparece al salir de los paréntesis, así que púlsalo dentro.", "Mostra a lista de argumentos da chamada em que você está; desaparece quando o cursor sai dos parênteses, então aperte lá dentro.", "今入っている呼び出しの引数一覧を出します。括弧の外へ出ると消えるので、括弧の中で押します。", "Zeigt die Argumentliste des Aufrufs, in dem Sie stehen; sie verschwindet, sobald der Cursor die Klammern verlässt.", "Affiche la liste des arguments de l'appel où vous êtes ; elle disparaît dès que le curseur sort des parenthèses.", "जिस call के भीतर आप हैं उसके arguments की सूची दिखाता है; cursor कोष्ठक से बाहर जाते ही यह हट जाती है, इसलिए भीतर ही दबाएँ।", "显示你当前所在调用的参数列表；光标一离开括号它就消失，所以要在括号里按。", "顯示你目前所在呼叫的參數清單；游標一離開括號它就消失，所以要在括號裡按。"],

  /* ───────── Folding ───────── */
  'vscode-fold': ["커서를 품은 가장 안쪽 블록을 접습니다. 접는 것은 보기 상태일 뿐이라 파일 내용은 하나도 바뀌지 않습니다.", "Folds the innermost block that contains the cursor; folding is only a view state and changes nothing in the file.", "Plega el bloque más interno que contiene el cursor; plegar es solo un estado de vista y no cambia nada del archivo.", "Recolhe o bloco mais interno que contém o cursor; recolher é só estado de exibição e não muda nada no arquivo.", "カーソルを含む一番内側の塊を折りたたみます。折りたたみは表示の状態にすぎず、ファイルの中身は少しも変わりません。", "Faltet den innersten Block um den Cursor zusammen; das Falten ist nur ein Anzeigezustand und ändert die Datei nicht.", "Replie le bloc le plus interne contenant le curseur ; le pliage n'est qu'un état d'affichage et ne modifie pas le fichier.", "cursor को समेटे सबसे भीतरी खंड को समेट देता है; समेटना केवल दिखावे की स्थिति है, फ़ाइल में कुछ नहीं बदलता।", "折叠包含光标的最内层代码块；折叠只是视图状态，文件内容一个字都不变。", "折疊包含游標的最內層程式碼區塊；折疊只是檢視狀態，檔案內容一個字都不變。"],
  'vscode-unfold': ["접힌 블록을 커서 자리에서 한 겹 펼칩니다. 접힌 줄에 글을 붙여 넣으면 접힌 안쪽으로 들어가니 먼저 펼치는 편이 낫습니다.", "Unfolds one layer at the cursor; pasting onto a folded line drops the text inside the hidden part, so it is better to unfold first.", "Despliega una capa en la posición del cursor; pegar sobre una línea plegada mete el texto en la parte oculta, así que conviene desplegar antes.", "Expande uma camada na posição do cursor; colar sobre uma linha recolhida joga o texto na parte escondida, então é melhor expandir antes.", "折りたたまれた塊をカーソル位置で一枚開きます。折りたたんだ行に貼り付けると隠れた内側に入るので、先に開く方が安全です。", "Klappt am Cursor eine Ebene auf; Einfügen auf einer gefalteten Zeile landet im verborgenen Teil, also besser vorher aufklappen.", "Déplie d'un niveau à l'endroit du curseur ; coller sur une ligne pliée dépose le texte dans la partie cachée, mieux vaut déplier d'abord.", "cursor की जगह पर एक परत खोल देता है; समेटी हुई पंक्ति पर चिपकाने से पाठ छिपे हिस्से में चला जाता है, इसलिए पहले खोल लेना बेहतर है।", "在光标处展开一层折叠；往折叠行上粘贴会把文字塞进隐藏部分，所以最好先展开。", "在游標處展開一層折疊；往折疊行上貼上會把文字塞進隱藏部分，所以最好先展開。"],
  'vscode-fold-all': ["파일의 모든 블록을 한꺼번에 접어 뼈대만 남깁니다. 마지막 키는 영문 O가 아니라 숫자 0입니다.", "Folds every region in the file at once so only the skeleton is left; the last key is the digit 0, not the letter O.", "Plega todas las regiones del archivo de una vez y deja solo el esqueleto; la última tecla es el dígito 0, no la letra O.", "Recolhe todas as regiões do arquivo de uma vez e deixa só o esqueleto; a última tecla é o dígito 0, não a letra O.", "ファイルのすべての塊を一度に折りたたみ、骨組みだけを残します。最後のキーは英字の O ではなく数字の 0 です。", "Faltet alle Bereiche der Datei auf einmal, sodass nur das Skelett bleibt; die letzte Taste ist die Ziffer 0, nicht der Buchstabe O.", "Replie toutes les régions du fichier d'un coup et ne laisse que le squelette ; la dernière touche est le chiffre 0, pas la lettre O.", "फ़ाइल के सारे खंड एक साथ समेटकर केवल ढाँचा छोड़ देता है; अंतिम key अंक 0 है, अक्षर O नहीं।", "一次折叠文件里所有区域，只留骨架；最后一个键是数字 0，不是字母 O。", "一次折疊檔案裡所有區域，只留骨架；最後一個鍵是數字 0，不是字母 O。"],
  'vscode-unfold-all': ["접힌 것을 파일 전체에서 모두 펼칩니다. 접힌 자리를 놓쳐 검색 결과가 안 보일 때 먼저 눌러 볼 단축키입니다.", "Unfolds everything in the file; press it first when a search hit seems to be hiding inside something you forgot you folded.", "Despliega todo el archivo; púlsalo primero cuando un resultado de búsqueda parece esconderse en algo que plegaste y olvidaste.", "Expande tudo no arquivo; aperte primeiro quando um resultado de busca parece escondido em algo que você recolheu e esqueceu.", "ファイル全体の折りたたみをすべて開きます。検索結果が見つからないとき、折りたたみを忘れていないか最初に確かめる操作です。", "Klappt in der ganzen Datei alles auf; drücken Sie es zuerst, wenn ein Suchtreffer in etwas Gefaltetem zu stecken scheint.", "Déplie tout dans le fichier ; à presser en premier quand un résultat de recherche semble caché dans un pli oublié.", "पूरी फ़ाइल का समेटा हुआ सब खोल देता है; कोई खोज-परिणाम किसी भूली हुई समेटी जगह में छिपा लगे तो पहले यही दबाएँ।", "展开文件里所有折叠；搜索结果好像藏在你忘了的折叠里时，先按这个。", "展開檔案裡所有折疊；搜尋結果好像藏在你忘了的折疊裡時，先按這個。"],

  /* ───────── Editors ───────── */
  'vscode-split-editor': ["편집기를 둘로 갈라 같은 파일을 나란히 놓습니다. 두 쪽은 한 문서라서, 한쪽에서 고치면 다른 쪽도 그 자리에서 바뜁니다.", "Splits the editor and shows the same file side by side; both panes are one document, so an edit in one appears at once in the other.", "Divide el editor y muestra el mismo archivo en paralelo; los dos paneles son un solo documento, así que lo que edites en uno aparece al instante en el otro.", "Divide o editor e mostra o mesmo arquivo lado a lado; os dois painéis são um só documento, então uma edição em um aparece na hora no outro.", "編集画面を二つに割って同じファイルを並べます。二つは一つの文書なので、片方で直すともう片方もその場で変わります。", "Teilt den Editor und zeigt dieselbe Datei nebeneinander; beide Bereiche sind ein Dokument, eine Änderung erscheint sofort auch im anderen.", "Divise l'éditeur et affiche le même fichier côte à côte ; les deux volets forment un seul document, une modification apparaît aussitôt dans l'autre.", "संपादक को दो हिस्सों में बाँटकर वही फ़ाइल साथ-साथ दिखाता है; दोनों एक ही दस्तावेज़ हैं, इसलिए एक में बदलाव दूसरे में तुरंत दिखता है।", "把编辑器一分为二，并排显示同一个文件；两边是同一份文档，在一边改动另一边立刻同步。", "把編輯器一分為二，並排顯示同一個檔案；兩邊是同一份文件，在一邊改動另一邊立刻同步。"],
  'vscode-close-editor': ["지금 탭만 닫습니다. 창을 닫는 것은 Ctrl+Shift+W이고, 저장하지 않은 파일이면 물어보고 나서 닫습니다.", "Closes the current tab only; the window itself goes with Ctrl+Shift+W, and an unsaved file asks before it goes.", "Cierra solo la pestaña actual; la ventana se cierra con Ctrl+Shift+W, y un archivo sin guardar pregunta antes.", "Fecha só a aba atual; a janela em si sai com Ctrl+Shift+W, e um arquivo não salvo pergunta antes.", "今のタブだけを閉じます。窓そのものを閉じるのは Ctrl+Shift+W で、保存していないファイルは確認してから閉じます。", "Schließt nur den aktuellen Tab; das Fenster selbst geht mit Ctrl+Shift+W, und eine ungespeicherte Datei fragt vorher nach.", "Ferme seulement l'onglet courant ; la fenêtre se ferme avec Ctrl+Shift+W, et un fichier non enregistré demande confirmation.", "केवल मौजूदा tab बंद करता है; खिड़की ख़ुद Ctrl+Shift+W से बंद होती है, और बिना सहेजी फ़ाइल पहले पूछती है।", "只关掉当前标签页；关窗口是 Ctrl+Shift+W，未保存的文件会先问一句。", "只關掉目前標籤頁；關視窗是 Ctrl+Shift+W，未儲存的檔案會先問一句。"],
  'vscode-reopen-closed-editor': ["방금 닫은 탭을 되살립니다. 닫은 차례를 거꾸로 되짚으므로 여러 번 눌러 아까 닫은 것까지 불러올 수 있습니다.", "Brings back the tab you just closed; it walks the closed list backwards, so pressing it again reaches the one before that.", "Recupera la pestaña que acabas de cerrar; recorre la lista de cerradas hacia atrás, así que pulsándolo de nuevo llegas a la anterior.", "Traz de volta a aba que você acabou de fechar; percorre a lista de fechadas de trás para frente, então apertar de novo alcança a anterior.", "たった今閉じたタブを呼び戻します。閉じた順を逆にたどるので、何度か押せばもっと前のものまで戻せます。", "Holt den gerade geschlossenen Tab zurück; es geht die Liste rückwärts, weitere Drücke bringen noch ältere zurück.", "Rouvre l'onglet que vous venez de fermer ; il remonte la liste des fermetures, une nouvelle pression atteint le précédent.", "अभी बंद किया tab वापस ले आता है; बंद किए क्रम को उलटा चलता है, इसलिए बार-बार दबाने पर उससे पहले वाला भी आ जाता है।", "把你刚关掉的标签页找回来；它按关闭顺序倒着走，多按几次能一直找回更早的。", "把你剛關掉的標籤頁找回來；它按關閉順序倒著走，多按幾次能一直找回更早的。"],
  'vscode-next-editor': ["열어 둔 편집기 사이를 옮겨 다닙니다. 기본은 최근에 본 차례라 탭이 놓인 순서와 다르고, Ctrl을 누른 채로 있으면 목록이 열린 채 남습니다.", "Moves between the editors you have open; by default the order is most recently used rather than the tab order, and holding Ctrl keeps the list on screen.", "Cambia entre los editores abiertos; por defecto el orden es el de uso reciente, no el de las pestañas, y manteniendo Ctrl la lista sigue visible.", "Alterna entre os editores abertos; por padrão a ordem é a de uso recente, não a das abas, e segurando Ctrl a lista fica na tela.", "開いている編集画面の間を移動します。既定は最近使った順でタブの並び順とは違い、Ctrl を押したままにすると一覧が開いたまま残ります。", "Wechselt zwischen den geöffneten Editoren; die Reihenfolge ist standardmäßig die der letzten Nutzung, nicht die der Tabs, und gehaltenes Ctrl hält die Liste offen.", "Passe d'un éditeur ouvert à l'autre ; l'ordre est par défaut celui d'utilisation récente et non celui des onglets, et maintenir Ctrl garde la liste affichée.", "खुले संपादकों के बीच घूमता है; डिफ़ॉल्ट क्रम हाल में देखे जाने का है, tab के क्रम का नहीं, और Ctrl दबाए रखने पर सूची खुली रहती है।", "在打开的编辑器之间切换；默认按最近使用顺序而不是标签顺序，按住 Ctrl 列表就一直开着。", "在開啟的編輯器之間切換；預設按最近使用順序而不是標籤順序，按住 Ctrl 清單就一直開著。"],

  /* ───────── View ───────── */
  'vscode-toggle-sidebar': ["왼쪽 사이드바를 접고 펴 화면을 넓힙니다. 다시 펼치면 마지막에 보던 보기가 그대로 돌아옵니다.", "Hides and shows the left sidebar to widen the code; reopening brings back whichever view you had there.", "Oculta y muestra la barra lateral izquierda para ganar espacio; al volver a abrirla reaparece la vista que tenías.", "Esconde e mostra a barra lateral esquerda para ganhar espaço; ao reabrir volta a mesma visão que estava lá.", "左のサイドバーを閉じたり開いたりして画面を広げます。開き直すと最後に見ていた表示がそのまま戻ります。", "Blendet die linke Seitenleiste aus und wieder ein, um Platz zu gewinnen; beim Öffnen kehrt die zuletzt gezeigte Ansicht zurück.", "Masque et réaffiche la barre latérale gauche pour élargir le code ; à la réouverture, la vue précédente revient.", "बाईं sidebar छिपाकर या दिखाकर जगह बढ़ाता है; फिर खोलने पर वही दृश्य लौट आता है जो पहले था।", "收起或展开左侧边栏来腾出空间；再打开时会回到你上次看的那个视图。", "收起或展開左側邊欄來騰出空間；再打開時會回到你上次看的那個檢視。"],
  'vscode-toggle-panel': ["아래쪽 판을 통째로 접습니다. 터미널만 여닫는 Ctrl+`와 달리 터미널·문제·출력이 한꺼번에 사라집니다.", "Collapses the whole bottom panel; unlike Ctrl+` which only toggles the terminal, this takes terminal, problems and output away together.", "Colapsa todo el panel inferior; a diferencia de Ctrl+`, que solo alterna la terminal, este se lleva terminal, problemas y salida a la vez.", "Recolhe todo o painel de baixo; diferente do Ctrl+`, que só alterna o terminal, este leva terminal, problemas e saída juntos.", "下の枠を丸ごとたたみます。ターミナルだけを開閉する Ctrl+` と違い、ターミナル・問題・出力がまとめて消えます。", "Klappt das gesamte untere Panel ein; anders als Ctrl+`, das nur das Terminal umschaltet, verschwinden Terminal, Probleme und Ausgabe zusammen.", "Replie tout le panneau du bas ; contrairement à Ctrl+` qui ne bascule que le terminal, terminal, problèmes et sortie disparaissent ensemble.", "नीचे का पूरा panel समेट देता है; Ctrl+` जो केवल terminal खोलता-बंद करता है, उसके उलट यहाँ terminal, problems और output सब एक साथ हट जाते हैं।", "整块收起底部面板；和只切换终端的 Ctrl+` 不同，这一下把终端、问题、输出一起收走。", "整塊收起底部面板；和只切換終端機的 Ctrl+` 不同，這一下把終端機、問題、輸出一起收走。"],
  'vscode-zen-mode': ["글만 남기고 모든 테두리를 감춥니다. 나올 때는 Esc를 두 번 이어 눌러야 하고, 한 번만 누르면 그대로 있습니다.", "Hides every frame and leaves only the text; to get out you press Esc twice in a row, since one press does nothing.", "Oculta todo el marco y deja solo el texto; para salir hay que pulsar Esc dos veces seguidas, porque una sola no hace nada.", "Esconde todas as bordas e deixa só o texto; para sair aperte Esc duas vezes seguidas, pois uma só não faz nada.", "文字だけを残して枠をすべて隠します。抜けるには Esc を続けて二回押す必要があり、一回では戻りません。", "Verbirgt alle Rahmen und lässt nur den Text; zum Verlassen drückt man Esc zweimal hintereinander, einmal genügt nicht.", "Masque tous les cadres et ne laisse que le texte ; pour sortir, il faut appuyer deux fois de suite sur Esc, une seule ne fait rien.", "सारे किनारे छिपाकर केवल पाठ छोड़ देता है; बाहर निकलने के लिए Esc लगातार दो बार दबाना पड़ता है, एक बार से कुछ नहीं होता।", "隐藏所有边框，只留下文本；退出要连按两次 Esc，按一次没反应。", "隱藏所有邊框，只留下文字；離開要連按兩次 Esc，按一次沒反應。"],
  'vscode-toggle-word-wrap': ["긴 줄을 화면 폭에 맞춰 접어 보여 줍니다. 보이는 것만 바뀌고 파일에는 줄바꿈이 들어가지 않습니다.", "Wraps long lines to the width of the window; only the display changes and no line breaks are written into the file.", "Ajusta las líneas largas al ancho de la ventana; solo cambia la vista y no se escribe ningún salto de línea en el archivo.", "Quebra as linhas longas na largura da janela; só a exibição muda e nenhuma quebra é escrita no arquivo.", "長い行を画面の幅に合わせて折り返して見せます。見え方だけが変わり、ファイルに改行は入りません。", "Bricht lange Zeilen auf Fensterbreite um; nur die Anzeige ändert sich, in die Datei kommen keine Umbrüche.", "Renvoie les longues lignes à la largeur de la fenêtre ; seul l'affichage change, aucun saut de ligne n'est écrit dans le fichier.", "लंबी पंक्तियों को खिड़की की चौड़ाई पर मोड़कर दिखाता है; केवल दिखावा बदलता है, फ़ाइल में कोई newline नहीं जाती।", "把长行按窗口宽度折行显示；只改变显示，文件里不会写入换行符。", "把長行按視窗寬度折行顯示；只改變顯示，檔案裡不會寫入換行字元。"],
  'vscode-show-problems': ["프로젝트에 쌓인 오류와 경고를 한 목록으로 엽니다. 파일을 열지 않아도 목록에 오르므로, 여기 숫자와 편집기 밑줄의 셈이 다를 수 있습니다.", "Opens one list of the errors and warnings in the project; entries appear without opening the files, so the count here can differ from the squiggles you see.", "Abre una lista con los errores y avisos del proyecto; aparecen sin abrir los archivos, así que el número puede no coincidir con los subrayados que ves.", "Abre uma lista com os erros e avisos do projeto; eles aparecem sem abrir os arquivos, então o número pode não bater com os sublinhados que você vê.", "プロジェクトに溜まったエラーと警告を一つの一覧で開きます。ファイルを開かなくても並ぶので、ここの数と編集画面の波線の数は食い違うことがあります。", "Öffnet eine Liste aller Fehler und Warnungen im Projekt; Einträge erscheinen ohne die Dateien zu öffnen, daher kann die Zahl von den sichtbaren Wellenlinien abweichen.", "Ouvre une liste des erreurs et avertissements du projet ; ils apparaissent sans ouvrir les fichiers, donc le compte peut différer des soulignements visibles.", "project की सारी errors और warnings एक सूची में खोलता है; फ़ाइलें खोले बिना भी वे आ जाती हैं, इसलिए यहाँ की गिनती संपादक की लहरदार रेखाओं से अलग हो सकती है।", "把项目里的错误和警告汇总成一个列表；不打开文件也会列出来，所以这里的数字可能和你看到的波浪线对不上。", "把專案裡的錯誤和警告匯總成一個清單；不開啟檔案也會列出來，所以這裡的數字可能和你看到的波浪線對不上。"],
  'vscode-source-control': ["바뀐 파일과 스테이지를 보여 주는 보기를 엽니다. 맥에서도 Cmd가 아니라 Ctrl+Shift+G이고, 스테이지에 올리는 것 자체에는 기본 키가 없어 명령 팔레트를 씁니다.", "Opens the view of changed and staged files; on mac it is Ctrl+Shift+G with Ctrl, not Cmd, and staging itself has no default key, so use the command palette.", "Abre la vista de archivos modificados y preparados; en mac es Ctrl+Shift+G con Ctrl, no Cmd, y preparar cambios no tiene atajo propio, así que usa la paleta de comandos.", "Abre a visão de arquivos alterados e no stage; no mac é Ctrl+Shift+G com Ctrl, não Cmd, e dar stage não tem tecla padrão, então use a paleta de comandos.", "変更したファイルとステージを見せる表示を開きます。Mac でも Cmd ではなく Ctrl+Shift+G で、ステージに上げる操作自体には既定のキーが無いためコマンドパレットを使います。", "Öffnet die Ansicht geänderter und vorgemerkter Dateien; auf dem Mac gilt Ctrl+Shift+G mit Ctrl statt Cmd, und für das Vormerken selbst gibt es kein Standardkürzel — dafür die Befehlspalette.", "Ouvre la vue des fichiers modifiés et indexés ; sur mac c'est Ctrl+Shift+G avec Ctrl et non Cmd, et l'indexation elle-même n'a pas de raccourci par défaut, passez par la palette de commandes.", "बदली और stage की गई फ़ाइलों का दृश्य खोलता है; mac पर भी Cmd नहीं, Ctrl+Shift+G है, और stage करने के लिए कोई डिफ़ॉल्ट key नहीं है, इसलिए command palette से करें।", "打开显示已改动和已暂存文件的视图；mac 上也是 Ctrl+Shift+G 用 Ctrl 而非 Cmd，而暂存本身没有默认按键，要用命令面板。", "打開顯示已改動和已暫存檔案的檢視；mac 上也是 Ctrl+Shift+G 用 Ctrl 而非 Cmd，而暫存本身沒有預設按鍵，要用命令面板。"],
  'vscode-extensions': ["확장 검색과 설치, 사용 정지를 한자리에서 합니다. 지금 프로젝트에서만 끄고 켜는 것도 여기서 고를 수 있습니다.", "Search, install and disable extensions in one place; you can also disable one for this workspace only from here.", "Busca, instala y desactiva extensiones en un solo lugar; también puedes desactivar una solo para este proyecto.", "Busca, instala e desativa extensões em um só lugar; daqui também se desativa uma só para este projeto.", "拡張の検索、導入、停止をここでまとめて行います。今のプロジェクトだけで無効にする選択もここからできます。", "Erweiterungen suchen, installieren und abschalten an einem Ort; hier lässt sich eine auch nur für dieses Projekt deaktivieren.", "Rechercher, installer et désactiver des extensions au même endroit ; on peut aussi n'en désactiver une que pour ce projet.", "Extensions खोजना, स्थापित करना और बंद करना एक ही जगह; यहीं से किसी को केवल इस project के लिए बंद भी कर सकते हैं।", "在一个地方搜索、安装和禁用扩展；也可以只在当前项目里禁用某个扩展。", "在一個地方搜尋、安裝和停用擴充；也可以只在目前專案裡停用某個擴充。"],
  'vscode-settings': ["설정 화면을 엽니다. 파일로 직접 고치려면 명령 팔레트에서 사용자 설정 JSON을 따로 열어야 합니다.", "Opens the settings screen; to edit the file itself you have to open the user settings JSON from the command palette.", "Abre la pantalla de ajustes; para editar el archivo hay que abrir el JSON de ajustes de usuario desde la paleta de comandos.", "Abre a tela de configurações; para editar o arquivo é preciso abrir o JSON de configurações do usuário pela paleta de comandos.", "設定画面を開きます。ファイルとして直接直したい場合は、コマンドパレットからユーザー設定の JSON を別に開きます。", "Öffnet die Einstellungsoberfläche; die Datei selbst bearbeitet man über die Benutzereinstellungen als JSON aus der Befehlspalette.", "Ouvre l'écran des paramètres ; pour modifier le fichier lui-même, ouvrez le JSON des paramètres utilisateur depuis la palette de commandes.", "सेटिंग्स की स्क्रीन खोलता है; फ़ाइल को सीधे बदलना हो तो command palette से user settings JSON अलग से खोलें।", "打开设置界面；想直接改文件，得从命令面板打开用户设置 JSON。", "打開設定介面；想直接改檔案，得從命令面板打開使用者設定 JSON。"],
  'vscode-keyboard-shortcuts': ["키 배치를 보고 바꾸는 화면을 엽니다. 녹음 단추를 켜면 Ctrl+K Ctrl+S처럼 이어 누르는 코드도 그대로 기록됩니다.", "Opens the screen where you read and change the key bindings; the record button captures chords such as Ctrl+K Ctrl+S exactly as you type them.", "Abre la pantalla para ver y cambiar las combinaciones; el botón de grabar captura acordes como Ctrl+K Ctrl+S tal como los teclees.", "Abre a tela para ver e mudar as combinações; o botão de gravar captura acordes como Ctrl+K Ctrl+S exatamente como você digita.", "キー割り当てを見て変える画面を開きます。記録ボタンを押せば Ctrl+K Ctrl+S のように続けて押す組み合わせもそのまま記録されます。", "Öffnet die Oberfläche zum Ansehen und Ändern der Tastenbelegung; die Aufnahmetaste erfasst Akkorde wie Ctrl+K Ctrl+S genau so, wie Sie sie tippen.", "Ouvre l'écran pour consulter et modifier les raccourcis ; le bouton d'enregistrement capture les accords comme Ctrl+K Ctrl+S tels que vous les tapez.", "keys देखने और बदलने की स्क्रीन खोलता है; record बटन Ctrl+K Ctrl+S जैसे क्रम भी वैसे ही दर्ज कर लेता है।", "打开查看和修改按键绑定的界面；打开录制按钮，连按的组合如 Ctrl+K Ctrl+S 也会被原样记下。", "打開檢視和修改按鍵繫結的介面；打開錄製按鈕，連按的組合如 Ctrl+K Ctrl+S 也會被原樣記下。"],
  'vscode-change-language-mode': ["이 파일을 어떤 언어로 볼지 바꿉니다. 지금 파일에만 걸리는 것이라, 확장자 전체를 바꾸려면 설정에서 연결을 손봐야 합니다.", "Changes which language this file is read as; it applies to this file only, so remapping a whole extension means editing the file associations in settings.", "Cambia con qué lenguaje se lee este archivo; solo afecta a este archivo, así que reasignar una extensión completa exige editar las asociaciones en los ajustes.", "Muda com qual linguagem este arquivo é lido; vale só para este arquivo, então remapear uma extensão inteira exige editar as associações nas configurações.", "このファイルをどの言語として見るかを変えます。今のファイルにだけ効くので、拡張子ごと変えるには設定の関連付けを直します。", "Ändert, als welche Sprache diese Datei gelesen wird; es gilt nur für diese Datei — für eine ganze Endung müssen die Zuordnungen in den Einstellungen geändert werden.", "Change le langage avec lequel ce fichier est lu ; cela ne vaut que pour ce fichier, réaffecter toute une extension demande de modifier les associations dans les paramètres.", "यह फ़ाइल किस भाषा के रूप में पढ़ी जाए, वह बदलता है; असर केवल इसी फ़ाइल पर है, पूरे extension के लिए settings में associations बदलनी पड़ती हैं।", "改变这个文件按哪种语言解析；只对当前文件生效，要改整个扩展名得去设置里改文件关联。", "改變這個檔案按哪種語言解析；只對目前檔案生效，要改整個副檔名得去設定裡改檔案關聯。"],
  'vscode-markdown-preview': ["마크다운을 그려 보여 줍니다. Ctrl+K V(맥은 Cmd+K V)로 열면 원본 옆에 붙어 함께 스크롤됩니다.", "Renders the markdown; opened with Ctrl+K V, or Cmd+K V on mac, it sits beside the source and scrolls with it.", "Muestra el markdown renderizado; abierto con Ctrl+K V, o Cmd+K V en mac, se coloca al lado del original y desplaza con él.", "Renderiza o markdown; aberto com Ctrl+K V, ou Cmd+K V no mac, fica ao lado do original e rola junto.", "マークダウンを描画して見せます。Ctrl+K V(Mac は Cmd+K V)で開くと原文の横に並び、一緒にスクロールします。", "Stellt das Markdown dar; mit Ctrl+K V bzw. Cmd+K V geöffnet, liegt es neben der Quelle und scrollt mit.", "Affiche le markdown rendu ; ouvert avec Ctrl+K V, ou Cmd+K V sur mac, il se place à côté de la source et défile avec elle.", "markdown को बनाकर दिखाता है; Ctrl+K V (mac पर Cmd+K V) से खोलें तो यह स्रोत के बग़ल में बैठकर साथ-साथ scroll होता है।", "把 markdown 渲染出来看；用 Ctrl+K V（mac 上 Cmd+K V）打开会贴在原文旁边并同步滚动。", "把 markdown 算繪出來看；用 Ctrl+K V（mac 上 Cmd+K V）開啟會貼在原文旁邊並同步捲動。"],

  /* ───────── Terminal ───────── */
  'vscode-toggle-terminal': ["안에 붙은 터미널을 열고 닫습니다. 맥에서도 Cmd가 아니라 Ctrl+`이고, 백틱은 숫자 1 왼쪽의 그 키입니다.", "Opens and closes the built-in terminal; on mac it is Ctrl+` with Ctrl, not Cmd, and the backtick is the key left of the 1.", "Abre y cierra la terminal integrada; en mac es Ctrl+` con Ctrl, no Cmd, y la tilde invertida es la tecla a la izquierda del 1.", "Abre e fecha o terminal integrado; no mac é Ctrl+` com Ctrl, não Cmd, e o acento grave é a tecla à esquerda do 1.", "内蔵のターミナルを開いたり閉じたりします。Mac でも Cmd ではなく Ctrl+` で、バックティックは数字の 1 の左のキーです。", "Öffnet und schließt das eingebaute Terminal; auf dem Mac gilt Ctrl+` mit Ctrl statt Cmd, und der Backtick liegt links der 1.", "Ouvre et ferme le terminal intégré ; sur mac c'est Ctrl+` avec Ctrl et non Cmd, et l'accent grave est la touche à gauche du 1.", "अंदर लगा terminal खोलता-बंद करता है; mac पर भी Cmd नहीं, Ctrl+` है, और backtick अंक 1 के बाईं ओर की key है।", "打开或关闭内置终端；mac 上也是 Ctrl+` 用 Ctrl 而非 Cmd，反引号就是数字 1 左边那个键。", "打開或關閉內建終端機；mac 上也是 Ctrl+` 用 Ctrl 而非 Cmd，反引號就是數字 1 左邊那個鍵。"],
  'vscode-new-terminal': ["터미널을 하나 더 만듭니다. 이미 열린 것으로 돌아가는 것이 아니라 새 셸이 뜨므로, 서버를 띄운 채 다른 명령을 칠 때 씁니다.", "Creates another terminal instead of returning to the open one, which is how you keep a server running and still type commands.", "Crea otra terminal en vez de volver a la abierta, que es como se deja un servidor corriendo y aun así se escriben órdenes.", "Cria outro terminal em vez de voltar ao já aberto, que é como se mantém um servidor rodando e ainda se digita comandos.", "ターミナルをもう一つ作ります。既に開いているものへ戻るのではなく新しいシェルが立つので、サーバーを動かしたまま別の命令を打てます。", "Erzeugt ein weiteres Terminal statt zum offenen zurückzukehren — so bleibt ein Server laufen, während man weiter Befehle tippt.", "Crée un terminal supplémentaire au lieu de revenir à celui ouvert, ce qui permet de laisser un serveur tourner tout en tapant des commandes.", "पहले खुले terminal पर लौटने के बजाय एक और terminal बनाता है, जिससे server चलता रहे और आप दूसरे commands भी चला सकें।", "新建一个终端，而不是回到已经打开的那个，这样可以让服务器一直跑着还能敲别的命令。", "新增一個終端機，而不是回到已經打開的那個，這樣可以讓伺服器一直跑著還能敲別的命令。"],
  /* ═════════ terminal ═════════ */

  /* ───────── Cursor ───────── */
  'terminal-line-start': ["줄 맨 앞으로 커서를 보냅니다. tmux나 screen 안에서는 Ctrl+A가 접두어 키로 먹히기 때문에 셸까지 닿지 않습니다.", "Sends the cursor to the start of the line; inside tmux or screen Ctrl+A is the prefix key and never reaches the shell.", "Lleva el cursor al principio de la línea; dentro de tmux o screen Ctrl+A es la tecla de prefijo y no llega al shell.", "Leva o cursor para o início da linha; dentro do tmux ou screen Ctrl+A é a tecla de prefixo e nunca chega ao shell.", "カーソルを行頭へ送ります。tmux や screen の中では Ctrl+A が接頭キーとして取られるため、シェルまで届きません。", "Setzt den Cursor an den Zeilenanfang; in tmux oder screen ist Ctrl+A die Präfixtaste und erreicht die Shell nie.", "Envoie le curseur en début de ligne ; dans tmux ou screen, Ctrl+A est la touche de préfixe et n'atteint jamais le shell.", "cursor को पंक्ति के शुरू में भेजता है; tmux या screen के भीतर Ctrl+A उपसर्ग key बन जाता है और shell तक नहीं पहुँचता।", "把光标送到行首；在 tmux 或 screen 里 Ctrl+A 是前缀键，根本传不到 shell。", "把游標送到行首；在 tmux 或 screen 裡 Ctrl+A 是前置鍵，根本傳不到 shell。"],
  'terminal-line-end': ["줄 맨 끝으로 커서를 보냅니다. ssh로 들어간 낯선 터미널에서는 End 키가 엉뚱한 글자를 보낼 때가 있어도 이 키는 늘 통합니다.", "Sends the cursor to the end of the line; on a strange terminal over ssh the End key sometimes sends junk, but this one always works.", "Lleva el cursor al final de la línea; en una terminal extraña por ssh la tecla End a veces manda basura, pero esta siempre funciona.", "Leva o cursor para o fim da linha; em um terminal estranho por ssh a tecla End às vezes manda lixo, mas esta sempre funciona.", "カーソルを行末へ送ります。ssh で入った見慣れない端末では End キーが妙な文字を送ることがありますが、このキーは必ず効きます。", "Setzt den Cursor an das Zeilenende; auf einem fremden Terminal über ssh sendet die End-Taste manchmal Unsinn, dieses Kürzel wirkt immer.", "Envoie le curseur en fin de ligne ; sur un terminal inconnu via ssh, la touche End envoie parfois n'importe quoi, alors que celle-ci marche toujours.", "cursor को पंक्ति के अंत में भेजता है; ssh से जुड़े अनजाने terminal पर End key कभी-कभी कचरा भेजती है, पर यह हमेशा चलता है।", "把光标送到行尾；通过 ssh 连上的陌生终端里 End 键有时会发出乱码，而这个键总是有效。", "把游標送到行尾；透過 ssh 連上的陌生終端機裡 End 鍵有時會送出亂碼，而這個鍵總是有效。"],
  'terminal-char-back': ["커서를 한 글자 왼쪽으로 옮깁니다. tmux의 기본 접두어가 Ctrl+B라서, tmux 안에서는 이 키가 셸에 오지 않습니다.", "Moves the cursor one character left; because tmux uses Ctrl+B as its default prefix, the shell never sees this key inside tmux.", "Mueve el cursor un carácter a la izquierda; como tmux usa Ctrl+B como prefijo, el shell no ve esta tecla dentro de tmux.", "Move o cursor um caractere à esquerda; como o tmux usa Ctrl+B como prefixo, o shell não vê essa tecla dentro do tmux.", "カーソルを一文字左へ動かします。tmux の既定の接頭キーが Ctrl+B なので、tmux の中ではこのキーがシェルに届きません。", "Bewegt den Cursor ein Zeichen nach links; da tmux Ctrl+B als Präfix nutzt, sieht die Shell diese Taste dort nie.", "Déplace le curseur d'un caractère vers la gauche ; comme tmux utilise Ctrl+B en préfixe, le shell ne voit pas cette touche dans tmux.", "cursor को एक अक्षर बाएँ ले जाता है; tmux का डिफ़ॉल्ट उपसर्ग Ctrl+B होने से tmux के भीतर यह key shell तक नहीं आती।", "把光标左移一个字符；因为 tmux 默认前缀就是 Ctrl+B，在 tmux 里 shell 收不到这个键。", "把游標左移一個字元；因為 tmux 預設前置鍵就是 Ctrl+B，在 tmux 裡 shell 收不到這個鍵。"],
  'terminal-char-forward': ["커서를 한 글자 오른쪽으로 옮깁니다. set -o vi로 vi 배치를 쓰고 있으면 이 emacs 배치는 통째로 사라집니다.", "Moves the cursor one character right; if you switched to vi keys with set -o vi, these emacs bindings are gone altogether.", "Mueve el cursor un carácter a la derecha; si cambiaste a teclas vi con set -o vi, estas combinaciones emacs desaparecen por completo.", "Move o cursor um caractere à direita; se você trocou para as teclas do vi com set -o vi, essas combinações emacs desaparecem.", "カーソルを一文字右へ動かします。set -o vi で vi 配置にしている場合、この emacs 配置はまるごと無くなります。", "Bewegt den Cursor ein Zeichen nach rechts; wer mit set -o vi auf vi-Tasten umgestellt hat, verliert diese Emacs-Belegungen ganz.", "Déplace le curseur d'un caractère vers la droite ; si vous êtes passé aux touches vi avec set -o vi, ces raccourcis emacs disparaissent.", "cursor को एक अक्षर दाएँ ले जाता है; set -o vi से vi keys पर गए हों तो ये emacs bindings पूरी तरह ग़ायब हो जाती हैं।", "把光标右移一个字符；如果你用 set -o vi 换成了 vi 键位，这套 emacs 键位会整体消失。", "把游標右移一個字元；如果你用 set -o vi 換成了 vi 鍵位，這套 emacs 鍵位會整體消失。"],
  'terminal-word-back': ["낱말 하나만큼 뒤로 건너갑니다. macOS 기본 터미널에서는 Option이 Meta가 아니어서, 설정에서 Meta로 쓰겠다고 켜거나 Esc를 먼저 눌러야 합니다.", "Jumps back one word; in the stock macOS Terminal, Option is not the Meta key, so either turn that on in the profile or press Esc first.", "Salta una palabra atrás; en la Terminal de macOS, Option no es la tecla Meta, así que actívalo en el perfil o pulsa Esc antes.", "Salta uma palavra para trás; no Terminal padrão do macOS, Option não é a tecla Meta, então ative isso no perfil ou aperte Esc antes.", "語ひとつ分だけ後ろへ跳びます。macOS の標準ターミナルでは Option が Meta ではないので、設定で Meta として使う指定をするか、先に Esc を押します。", "Springt ein Wort zurück; im macOS-Terminal ist Option nicht die Meta-Taste — aktivieren Sie das im Profil oder drücken Sie zuerst Esc.", "Recule d'un mot ; dans le Terminal de macOS, Option n'est pas la touche Meta, activez-le dans le profil ou appuyez d'abord sur Esc.", "एक शब्द पीछे कूदता है; macOS के डिफ़ॉल्ट Terminal में Option, Meta नहीं होता, इसलिए profile में वह चालू करें या पहले Esc दबाएँ।", "往后跳一个词；macOS 自带终端里 Option 不是 Meta 键，要么在配置里打开这一项，要么先按 Esc。", "往後跳一個字詞；macOS 內建終端機裡 Option 不是 Meta 鍵，要嘛在設定裡打開這一項，要嘛先按 Esc。"],
  'terminal-word-forward': ["낱말 하나만큼 앞으로 건너갑니다. 여기서 낱말은 글자와 숫자만 세기 때문에 /usr/local/bin 같은 경로는 여러 칸으로 쪼개집니다.", "Jumps forward one word; a word here counts only letters and digits, so a path like /usr/local/bin breaks into several hops.", "Avanza una palabra; aquí una palabra son solo letras y dígitos, así que una ruta como /usr/local/bin se parte en varios saltos.", "Avança uma palavra; aqui palavra são só letras e dígitos, então um caminho como /usr/local/bin se parte em vários saltos.", "語ひとつ分だけ前へ跳びます。ここでの語は英数字だけを数えるので、/usr/local/bin のような経路はいくつにも分かれます。", "Springt ein Wort vorwärts; ein Wort umfasst hier nur Buchstaben und Ziffern, weshalb ein Pfad wie /usr/local/bin in mehrere Sprünge zerfällt.", "Avance d'un mot ; ici un mot ne compte que lettres et chiffres, donc un chemin comme /usr/local/bin se découpe en plusieurs sauts.", "एक शब्द आगे कूदता है; यहाँ शब्द में केवल अक्षर और अंक गिने जाते हैं, इसलिए /usr/local/bin जैसा रास्ता कई टुकड़ों में बँट जाता है।", "往前跳一个词；这里的词只算字母和数字，所以 /usr/local/bin 这样的路径会被拆成好几跳。", "往前跳一個字詞；這裡的字詞只算字母和數字，所以 /usr/local/bin 這樣的路徑會被拆成好幾跳。"],
  'terminal-set-mark': ["지금 자리에 표를 남깁니다. readline 문서에서는 C-@로 적히는 그 키이고, 표를 남겨 두면 Ctrl+X Ctrl+X로 그 자리와 오갈 수 있습니다.", "Leaves a mark at the cursor — the binding readline writes as C-@ — and once set you can bounce to it with Ctrl+X Ctrl+X.", "Deja una marca en el cursor, la combinación que readline escribe como C-@, y una vez puesta puedes ir y volver con Ctrl+X Ctrl+X.", "Deixa uma marca no cursor, a combinação que o readline escreve como C-@, e depois você pula até ela com Ctrl+X Ctrl+X.", "今の位置に印を残します。readline の文書で C-@ と書かれるキーで、印を残しておけば Ctrl+X Ctrl+X でその位置と行き来できます。", "Setzt eine Marke an der Cursorposition — in readline als C-@ notiert — und danach springt man mit Ctrl+X Ctrl+X hin und her.", "Pose une marque à la position du curseur — la combinaison notée C-@ dans readline — puis on va et vient avec Ctrl+X Ctrl+X.", "cursor की जगह पर निशान छोड़ता है — readline इसे C-@ लिखता है — और निशान लगने पर Ctrl+X Ctrl+X से उस जगह आ-जा सकते हैं।", "在当前位置留一个标记，readline 文档里写作 C-@；标记留下后就能用 Ctrl+X Ctrl+X 来回跳。", "在目前位置留一個標記，readline 文件裡寫作 C-@；標記留下後就能用 Ctrl+X Ctrl+X 來回跳。"],
  'terminal-swap-mark': ["표를 남긴 자리와 지금 자리를 맞바꿉니다. 표를 남기지 않았으면 줄 맨 앞이 표여서, 앞과 뒤를 왕복하는 단축키처럼 쓰입니다.", "Swaps the cursor with the mark; with no mark set the mark is the start of the line, which is why it feels like a jump-to-front-and-back toggle.", "Intercambia el cursor con la marca; si no pusiste ninguna, la marca es el principio de la línea, por eso parece un ir y volver al inicio.", "Troca o cursor com a marca; sem marca definida, a marca é o início da linha, e por isso parece um vai e volta até o começo.", "印の位置と今の位置を入れ替えます。印を残していなければ行頭が印なので、先頭と元の位置を往復する操作のように使えます。", "Tauscht Cursor und Marke; ohne gesetzte Marke ist der Zeilenanfang die Marke, weshalb es wie ein Hin und Zurück zum Anfang wirkt.", "Échange le curseur et la marque ; sans marque posée, la marque est le début de la ligne, d'où cet effet d'aller-retour vers le début.", "cursor और निशान की जगहें बदल देता है; कोई निशान न हो तो पंक्ति का आरंभ ही निशान होता है, इसीलिए यह शुरू और वापस का टॉगल लगता है।", "把光标和标记的位置互换；没设过标记时，标记就是行首，所以它像一个来回跳行首的开关。", "把游標和標記的位置互換；沒設過標記時，標記就是行首，所以它像一個來回跳行首的開關。"],

  /* ───────── Killing ───────── */
  'terminal-kill-to-start': ["커서 앞쪽을 줄 맨 앞까지 잘라 냅니다. bash는 커서 앞만 자르지만 zsh는 같은 키로 줄 전체를 버리므로, 셸을 옮겨 타면 결과가 다릅니다.", "Cuts from the cursor back to the start of the line; bash takes only what is behind the cursor while zsh throws away the whole line with the same key.", "Corta desde el cursor hasta el principio de la línea; bash se lleva solo lo anterior al cursor, mientras zsh descarta la línea entera con la misma tecla.", "Corta do cursor até o início da linha; o bash leva só o que está antes do cursor, enquanto o zsh descarta a linha inteira com a mesma tecla.", "カーソルより前を行頭まで切り取ります。bash は前だけを切りますが、zsh は同じキーで行全体を捨てるので、シェルを移ると結果が違います。", "Schneidet vom Cursor bis zum Zeilenanfang; bash nimmt nur den Teil davor, zsh verwirft mit derselben Taste die ganze Zeile.", "Coupe du curseur jusqu'au début de la ligne ; bash ne prend que ce qui précède, tandis que zsh jette la ligne entière avec la même touche.", "cursor से पंक्ति के आरंभ तक काट देता है; bash केवल cursor से पहले का लेता है, जबकि zsh उसी key से पूरी पंक्ति फेंक देता है।", "把光标之前的内容一直剪到行首；bash 只剪光标前面的，而 zsh 用同一个键会把整行丢掉。", "把游標之前的內容一直剪到行首；bash 只剪游標前面的，而 zsh 用同一個鍵會把整行丟掉。"],
  'terminal-kill-to-end': ["커서 뒤쪽을 줄 끝까지 잘라 냅니다. 잘린 것은 kill ring에 담기므로 Ctrl+Y로 그대로 되붙일 수 있습니다.", "Cuts from the cursor to the end of the line; what it takes goes into the kill ring, so Ctrl+Y puts it straight back.", "Corta desde el cursor hasta el final de la línea; lo cortado va al kill ring, así que Ctrl+Y lo devuelve tal cual.", "Corta do cursor até o fim da linha; o que sai vai para o kill ring, então Ctrl+Y traz de volta igual.", "カーソルより後ろを行末まで切り取ります。切ったものは kill ring に入るので、Ctrl+Y でそのまま貼り戻せます。", "Schneidet vom Cursor bis zum Zeilenende; das Ausgeschnittene landet im Kill-Ring, Ctrl+Y bringt es unverändert zurück.", "Coupe du curseur jusqu'à la fin de la ligne ; le morceau va dans le kill ring, et Ctrl+Y le remet tel quel.", "cursor से पंक्ति के अंत तक काट देता है; कटा हुआ kill ring में जाता है, इसलिए Ctrl+Y उसे वैसा ही लौटा देता है।", "把光标之后的内容剪到行尾；剪下来的进 kill ring，用 Ctrl+Y 就能原样贴回来。", "把游標之後的內容剪到行尾；剪下來的進 kill ring，用 Ctrl+Y 就能原樣貼回來。"],
  'terminal-kill-word-back': ["커서 앞의 낱말을 빈칸까지 잘라 냅니다. 빈칸을 경계로 삼기 때문에 /usr/local/bin 같은 경로가 한 번에 통째로 날아갑니다.", "Cuts the word before the cursor back to the nearest space; because whitespace is the only boundary, a whole path like /usr/local/bin goes in one press.", "Corta la palabra anterior al cursor hasta el espacio más cercano; como el único límite es el espacio, una ruta entera como /usr/local/bin desaparece de una vez.", "Corta a palavra antes do cursor até o espaço mais próximo; como o único limite é o espaço, um caminho inteiro como /usr/local/bin sai de uma vez.", "カーソル前の語を空白まで切り取ります。境目が空白だけなので、/usr/local/bin のような経路が一度で丸ごと消えます。", "Schneidet das Wort vor dem Cursor bis zum nächsten Leerzeichen; da nur Leerraum trennt, verschwindet ein ganzer Pfad wie /usr/local/bin in einem Zug.", "Coupe le mot avant le curseur jusqu'à l'espace le plus proche ; l'espace étant la seule frontière, tout un chemin comme /usr/local/bin part d'un coup.", "cursor से पहले का शब्द निकटतम space तक काट देता है; सीमा केवल space होने से /usr/local/bin जैसा पूरा रास्ता एक बार में उड़ जाता है।", "把光标前的词一直剪到最近的空格；因为只以空白为界，/usr/local/bin 这样的整条路径一下就没了。", "把游標前的字詞一直剪到最近的空格；因為只以空白為界，/usr/local/bin 這樣的整條路徑一下就沒了。"],
  'terminal-kill-word-back-readline': ["커서 앞의 낱말을 글자·숫자 경계까지만 잘라 냅니다. 경로의 슬래시마다 멈추므로, 한 번에 다 날리는 Ctrl+W와 여기서 갈립니다.", "Cuts the word before the cursor by word characters, stopping at each slash of a path — that is exactly how it differs from Ctrl+W.", "Corta la palabra anterior usando caracteres de palabra y se detiene en cada barra de una ruta: ahí está la diferencia con Ctrl+W.", "Corta a palavra anterior por caracteres de palavra e para em cada barra do caminho: é justamente a diferença em relação ao Ctrl+W.", "カーソル前の語を英数字の境目までで切ります。経路のスラッシュごとに止まる点が Ctrl+W との違いです。", "Schneidet das Wort vor dem Cursor nach Wortzeichen und hält an jedem Schrägstrich eines Pfades — genau darin unterscheidet es sich von Ctrl+W.", "Coupe le mot précédent selon les caractères de mot et s'arrête à chaque barre oblique d'un chemin : c'est là toute la différence avec Ctrl+W.", "cursor से पहले का शब्द word-अक्षरों के हिसाब से काटता है और रास्ते के हर slash पर रुक जाता है — Ctrl+W से फ़र्क़ यही है।", "按单词字符剪掉光标前的词，会在路径的每个斜杠处停下——这正是它和 Ctrl+W 的区别。", "按單字字元剪掉游標前的字詞，會在路徑的每個斜線處停下——這正是它和 Ctrl+W 的區別。"],
  'terminal-kill-word-forward': ["커서 뒤의 낱말을 잘라 냅니다. 낱말 가운데 서 있으면 그 뒤쪽만 잘리므로 앞부분은 그대로 남습니다.", "Cuts the word after the cursor; standing in the middle of a word it takes only the tail and leaves the head behind.", "Corta la palabra que sigue al cursor; si estás en medio de una palabra se lleva solo la cola y deja la cabeza.", "Corta a palavra depois do cursor; no meio de uma palavra ele leva só o final e deixa o começo.", "カーソルより後ろの語を切り取ります。語の途中に立っていると後ろ半分だけが切れ、前半は残ります。", "Schneidet das Wort nach dem Cursor; mitten in einem Wort nimmt es nur den Rest und lässt den Anfang stehen.", "Coupe le mot après le curseur ; au milieu d'un mot, il n'emporte que la fin et laisse le début.", "cursor के बाद का शब्द काट देता है; शब्द के बीच खड़े हों तो केवल पिछला हिस्सा जाता है, आगे का बचा रहता है।", "剪掉光标后面的词；如果站在词中间，只会剪掉后半截，前半截留着。", "剪掉游標後面的字詞；如果站在字詞中間，只會剪掉後半截，前半截留著。"],
  'terminal-yank': ["Ctrl+U·Ctrl+K·Ctrl+W로 잘라 둔 것을 커서 자리에 되붙입니다. 이것은 셸의 kill ring이라 시스템 클립보드와 다르고, 터미널에서 Ctrl+V는 붙여넣기가 아닙니다.", "Pastes back what Ctrl+U, Ctrl+K or Ctrl+W cut; this is the shell's own kill ring, not the system clipboard, and Ctrl+V is not paste in a terminal.", "Pega lo que cortaron Ctrl+U, Ctrl+K o Ctrl+W; es el kill ring del shell, no el portapapeles del sistema, y Ctrl+V no pega en una terminal.", "Cola de volta o que Ctrl+U, Ctrl+K ou Ctrl+W cortaram; é o kill ring do shell, não a área de transferência do sistema, e Ctrl+V não cola no terminal.", "Ctrl+U・Ctrl+K・Ctrl+W で切ったものをカーソル位置に貼り戻します。これはシェルの kill ring で OS のクリップボードとは別物で、端末の Ctrl+V は貼り付けではありません。", "Fügt zurück, was Ctrl+U, Ctrl+K oder Ctrl+W ausgeschnitten hat; das ist der Kill-Ring der Shell, nicht die Systemablage, und Ctrl+V fügt im Terminal nichts ein.", "Recolle ce que Ctrl+U, Ctrl+K ou Ctrl+W ont coupé ; c'est le kill ring du shell, pas le presse-papiers du système, et Ctrl+V ne colle pas dans un terminal.", "Ctrl+U, Ctrl+K या Ctrl+W से काटा हुआ cursor की जगह वापस चिपकाता है; यह shell का kill ring है, सिस्टम का clipboard नहीं, और terminal में Ctrl+V चिपकाना नहीं है।", "把 Ctrl+U、Ctrl+K、Ctrl+W 剪掉的内容贴回光标处；这是 shell 自己的 kill ring，不是系统剪贴板，而终端里 Ctrl+V 并不是粘贴。", "把 Ctrl+U、Ctrl+K、Ctrl+W 剪掉的內容貼回游標處；這是 shell 自己的 kill ring，不是系統剪貼簿，而終端機裡 Ctrl+V 並不是貼上。"],
  'terminal-yank-pop': ["방금 되붙인 것을 그 앞에 잘랐던 것으로 갈아 끼웁니다. Ctrl+Y 바로 뒤에서만 뜻이 있고, 누를 때마다 kill ring을 더 옛것으로 거슬러 갑니다.", "Replaces what you just yanked with the cut before it; it only means anything right after Ctrl+Y, and each press walks further back through the kill ring.", "Sustituye lo que acabas de pegar por el corte anterior; solo tiene sentido justo después de Ctrl+Y y cada pulsación retrocede más en el kill ring.", "Troca o que você acabou de colar pelo corte anterior; só faz sentido logo após Ctrl+Y e cada toque volta mais no kill ring.", "たった今貼ったものを、その前に切ったものへ差し替えます。Ctrl+Y の直後にしか意味がなく、押すたびに kill ring をさらに古い方へさかのぼります。", "Ersetzt das eben Eingefügte durch den vorherigen Schnitt; es wirkt nur direkt nach Ctrl+Y und geht mit jedem Druck weiter im Kill-Ring zurück.", "Remplace ce que vous venez de coller par la coupe précédente ; cela n'a de sens qu'immédiatement après Ctrl+Y, et chaque pression remonte le kill ring.", "अभी चिपकाई चीज़ को उससे पहले काटी चीज़ से बदल देता है; इसका अर्थ केवल Ctrl+Y के तुरंत बाद है, और हर दबाव kill ring में और पीछे ले जाता है।", "把刚贴上的内容换成上一次剪下的；只有紧接 Ctrl+Y 之后才有意义，每按一次就在 kill ring 里往更早退一格。", "把剛貼上的內容換成上一次剪下的；只有緊接 Ctrl+Y 之後才有意義，每按一次就在 kill ring 裡往更早退一格。"],

  /* ───────── Editing ───────── */
  'terminal-transpose-chars': ["커서 앞 글자와 커서 밑 글자를 맞바꾸고 한 칸 오른쪽으로 갑니다. sl을 ls로 고칠 때처럼 두 글자가 뒤집힌 오타를 한 번에 잡습니다.", "Swaps the character before the cursor with the one under it and steps right — the one-key fix for a typo like sl instead of ls.", "Intercambia el carácter anterior con el que está bajo el cursor y avanza uno: el arreglo de una tecla para un error como sl en vez de ls.", "Troca o caractere anterior com o que está sob o cursor e avança um: o conserto de uma tecla para um erro como sl em vez de ls.", "カーソル前の文字とカーソル下の文字を入れ替えて一つ右へ進みます。sl を ls に直すような二文字の入れ違いを一発で直せます。", "Vertauscht das Zeichen vor dem Cursor mit dem darunter und rückt eins weiter — die Ein-Tasten-Korrektur für Tippfehler wie sl statt ls.", "Échange le caractère précédent avec celui sous le curseur et avance d'un cran : la correction en une touche d'une faute comme sl au lieu de ls.", "cursor से पहले वाले और cursor के नीचे वाले अक्षर की जगह बदलकर एक कदम दाएँ जाता है — sl को ls करने जैसी उलटी टाइप एक ही key से ठीक।", "把光标前的字符和光标下的字符互换并右移一格——像把 sl 改成 ls 这种颠倒的手误，一键就好。", "把游標前的字元和游標下的字元互換並右移一格——像把 sl 改成 ls 這種顛倒的手誤，一鍵就好。"],
  'terminal-transpose-words': ["커서 앞의 낱말을 그 앞 낱말과 맞바꿉니다. 인수 두 개의 순서를 잘못 쳤을 때 지우지 않고 되돌릴 수 있습니다.", "Swaps the word before the cursor with the one before that, so two arguments typed in the wrong order can be righted without deleting.", "Intercambia la palabra anterior con la de antes, así dos argumentos escritos al revés se corrigen sin borrar.", "Troca a palavra anterior com a de antes, assim dois argumentos digitados na ordem errada se ajeitam sem apagar.", "カーソル前の語をその前の語と入れ替えます。引数二つの順番を打ち間違えたとき、消さずに直せます。", "Vertauscht das Wort vor dem Cursor mit dem davor, sodass zwei falsch getippte Argumente ohne Löschen korrigiert werden.", "Échange le mot avant le curseur avec celui qui le précède, ce qui corrige deux arguments tapés à l'envers sans rien effacer.", "cursor से पहले वाले शब्द को उससे पहले वाले से बदल देता है, जिससे उलटे क्रम में लिखे दो arguments मिटाए बिना ठीक हो जाते हैं।", "把光标前的词和它前面那个词互换，两个参数打反了不用删就能纠正。", "把游標前的字詞和它前面那個字詞互換，兩個引數打反了不用刪就能糾正。"],
  'terminal-undo': ["줄에 한 편집을 한 단계씩 되돌립니다. 이미 실행한 명령을 되돌리는 것이 아니라, 지금 치고 있는 줄만 되돌립니다.", "Undoes your edits to the line one step at a time; it takes back typing, never a command you already ran.", "Deshace las ediciones de la línea paso a paso; recupera lo que escribiste, nunca un comando ya ejecutado.", "Desfaz as edições da linha passo a passo; recupera o que você digitou, nunca um comando já executado.", "その行に加えた編集を一段ずつ戻します。すでに実行した命令を取り消すのではなく、いま打っている行だけを戻します。", "Nimmt die Bearbeitungen an der Zeile Schritt für Schritt zurück; es widerruft Eingetipptes, niemals einen bereits ausgeführten Befehl.", "Annule vos modifications de la ligne pas à pas ; il reprend la saisie, jamais une commande déjà exécutée.", "पंक्ति में किए संपादन एक-एक कदम पीछे लेता है; यह टाइपिंग वापस लेता है, पहले चला दिया command कभी नहीं।", "一步步撤销你对这一行的编辑；它撤的是输入，绝不是已经执行过的命令。", "一步步復原你對這一行的編輯；它復原的是輸入，絕不是已經執行過的命令。"],
  'terminal-literal-next': ["다음에 누르는 키를 뜻 없이 글자로 넣습니다. Ctrl+V Tab으로 진짜 탭 문자를 넣거나 방향키가 무엇을 보내는지 볼 때 쓰고, 터미널에서 Ctrl+V는 붙여넣기가 아닙니다.", "Inserts the next key as a plain character — Ctrl+V Tab types a real tab, and it also reveals what an arrow key sends — since Ctrl+V is not paste in a terminal.", "Inserta la siguiente tecla como carácter literal: Ctrl+V Tab escribe un tabulador real y también revela qué envía una flecha, ya que Ctrl+V no pega en una terminal.", "Insere a próxima tecla como caractere literal: Ctrl+V Tab digita uma tabulação real e também revela o que uma seta envia, já que Ctrl+V não cola no terminal.", "次に押すキーを意味のない文字として入れます。Ctrl+V Tab で本物のタブを入れたり、矢印キーが何を送るか確かめたりでき、端末の Ctrl+V は貼り付けではありません。", "Fügt die nächste Taste als reines Zeichen ein — Ctrl+V Tab tippt einen echten Tabulator und zeigt auch, was eine Pfeiltaste sendet, denn Ctrl+V fügt im Terminal nichts ein.", "Insère la touche suivante comme simple caractère : Ctrl+V Tab tape une vraie tabulation et révèle aussi ce qu'envoie une flèche, puisque Ctrl+V ne colle pas dans un terminal.", "अगली key को सादा अक्षर बनाकर डालता है — Ctrl+V Tab असली tab डालता है और यह भी दिखाता है कि arrow key क्या भेजती है, क्योंकि terminal में Ctrl+V चिपकाना नहीं है।", "把接下来按的键当普通字符插进去：Ctrl+V Tab 能打出真正的制表符，也能看出方向键发的是什么，毕竟终端里 Ctrl+V 不是粘贴。", "把接下來按的鍵當普通字元插進去：Ctrl+V Tab 能打出真正的定位字元，也能看出方向鍵送的是什麼，畢竟終端機裡 Ctrl+V 不是貼上。"],
  'terminal-accept-line': ["줄을 실행합니다. Enter와 똑같은 제어 문자를 보내기 때문에 둘은 완전히 같은 일을 합니다.", "Runs the line; it sends the very same control character as Enter, so the two are identical.", "Ejecuta la línea; envía exactamente el mismo carácter de control que Enter, así que son idénticos.", "Executa a linha; envia exatamente o mesmo caractere de controle que o Enter, então são idênticos.", "行を実行します。Enter とまったく同じ制御文字を送るので、二つは完全に同じ働きです。", "Führt die Zeile aus; es sendet genau dasselbe Steuerzeichen wie Enter, beide sind identisch.", "Exécute la ligne ; il envoie exactement le même caractère de contrôle qu'Enter, les deux sont identiques.", "पंक्ति चलाता है; यह Enter जैसा ही control अक्षर भेजता है, इसलिए दोनों बिलकुल एक हैं।", "执行当前行；它发出的控制字符和 Enter 完全一样，两者等价。", "執行目前行；它送出的控制字元和 Enter 完全一樣，兩者等價。"],
  'terminal-backspace': ["커서 앞 글자를 지웁니다. 낡은 ssh 연결에서 Backspace가 이 문자를 보내는 바람에 화면에 ^H가 찍히는 일이 있습니다.", "Deletes the character before the cursor; on some old ssh sessions Backspace sends this very character, which is why ^H shows up on screen.", "Borra el carácter anterior al cursor; en algunas sesiones ssh antiguas Backspace envía justo este carácter, por eso aparece ^H en pantalla.", "Apaga o caractere antes do cursor; em sessões ssh antigas o Backspace manda exatamente esse caractere, e é por isso que aparece ^H na tela.", "カーソル前の文字を消します。古い ssh 接続では Backspace がこの文字を送るため、画面に ^H が出ることがあります。", "Löscht das Zeichen vor dem Cursor; in alten ssh-Sitzungen sendet Backspace genau dieses Zeichen, weshalb ^H auf dem Schirm erscheint.", "Supprime le caractère avant le curseur ; sur certaines vieilles sessions ssh, Backspace envoie précisément ce caractère, d'où le ^H affiché.", "cursor से पहले का अक्षर मिटाता है; कुछ पुराने ssh sessions में Backspace यही अक्षर भेजता है, इसीलिए स्क्रीन पर ^H दिखता है।", "删除光标前的一个字符；有些老的 ssh 会话里 Backspace 发的正是这个字符，所以屏幕上会冒出 ^H。", "刪除游標前的一個字元；有些老的 ssh 連線裡 Backspace 送的正是這個字元，所以螢幕上會冒出 ^H。"],
  'terminal-uppercase-word': ["커서 자리에서 낱말 끝까지 대문자로 바꿉니다. 낱말 가운데에서 누르면 뒤쪽만 대문자가 되니 먼저 낱말 앞으로 가야 합니다.", "Upper-cases from the cursor to the end of the word; pressed mid-word it only shouts the tail, so move to the front of the word first.", "Pone en mayúsculas desde el cursor hasta el final de la palabra; en medio de una palabra solo afecta la cola, así que ve primero al inicio.", "Passa para maiúsculas do cursor até o fim da palavra; no meio de uma palavra só afeta o final, então vá ao começo primeiro.", "カーソル位置から語の末尾までを大文字にします。語の途中で押すと後ろだけが大文字になるので、先に語の頭へ移ります。", "Schreibt vom Cursor bis zum Wortende groß; mitten im Wort erwischt es nur den Rest, also zuerst an den Wortanfang gehen.", "Met en majuscules du curseur jusqu'à la fin du mot ; au milieu d'un mot seule la fin change, allez d'abord au début du mot.", "cursor से शब्द के अंत तक बड़े अक्षर कर देता है; शब्द के बीच दबाने पर केवल पिछला हिस्सा बदलता है, इसलिए पहले शब्द के आरंभ पर जाएँ।", "把光标处到词尾变成大写；在词中间按只会改后半截，所以先移到词首。", "把游標處到字尾變成大寫；在字詞中間按只會改後半截，所以先移到字首。"],
  'terminal-lowercase-word': ["커서 자리에서 낱말 끝까지 소문자로 바꿉니다. 대문자로 잘못 켜 둔 Caps Lock 때문에 소리치듯 쳐 놓은 줄을 되살릴 때 씁니다.", "Lower-cases from the cursor to the end of the word — the repair for a line you typed while Caps Lock was on.", "Pone en minúsculas desde el cursor hasta el final de la palabra: el remedio para una línea escrita con Caps Lock activado.", "Passa para minúsculas do cursor até o fim da palavra: o reparo para uma linha digitada com o Caps Lock ligado.", "カーソル位置から語の末尾までを小文字にします。Caps Lock が入ったまま叫ぶように打ってしまった行を直すのに使います。", "Schreibt vom Cursor bis zum Wortende klein — die Reparatur für eine Zeile, die man mit aktivem Caps Lock getippt hat.", "Met en minuscules du curseur jusqu'à la fin du mot : le remède pour une ligne tapée avec Caps Lock activé.", "cursor से शब्द के अंत तक छोटे अक्षर कर देता है — Caps Lock चालू रहते लिखी पंक्ति की मरम्मत।", "把光标处到词尾变成小写——Caps Lock 忘了关而全大写的那一行就靠它救。", "把游標處到字尾變成小寫——Caps Lock 忘了關而全大寫的那一行就靠它救。"],
  'terminal-capitalize-word': ["낱말의 첫 글자만 대문자로 올립니다. 이름이 비슷해도 복사가 아니니, 터미널에서 Alt+C는 클립보드와 상관이 없습니다.", "Capitalizes just the first letter of the word; despite the letter, Alt+C here has nothing to do with copying.", "Pone en mayúscula solo la primera letra de la palabra; a pesar de la letra, aquí Alt+C no tiene nada que ver con copiar.", "Deixa maiúscula só a primeira letra da palavra; apesar da letra, aqui Alt+C não tem nada a ver com copiar.", "語の最初の一文字だけを大文字にします。文字は同じでも、端末の Alt+C は複写とは何の関係もありません。", "Schreibt nur den ersten Buchstaben des Wortes groß; trotz des Buchstabens hat Alt+C hier nichts mit Kopieren zu tun.", "Met en majuscule seulement la première lettre du mot ; malgré la lettre, Alt+C n'a rien à voir ici avec copier.", "शब्द का केवल पहला अक्षर बड़ा करता है; अक्षर वही होने पर भी यहाँ Alt+C का copy से कोई संबंध नहीं।", "只把词的首字母变成大写；虽然是 C，这里的 Alt+C 和复制毫无关系。", "只把字詞的首字母變成大寫；雖然是 C，這裡的 Alt+C 和複製毫無關係。"],
  'terminal-edit-in-editor': ["지금 줄을 $EDITOR로 열어 고치고, 저장하고 나오면 그대로 실행합니다. bash는 그냥 되지만 zsh는 edit-command-line을 autoload로 불러 키에 매어야 합니다.", "Opens the current line in $EDITOR and runs it when you save and quit; bash has this out of the box while zsh needs edit-command-line autoloaded and bound.", "Abre la línea actual en $EDITOR y la ejecuta al guardar y salir; bash lo trae de fábrica, zsh necesita autoload de edit-command-line y un bindkey.", "Abre a linha atual no $EDITOR e executa quando você salva e sai; o bash já vem com isso, o zsh precisa de edit-command-line com autoload e bindkey.", "いまの行を $EDITOR で開いて直し、保存して抜けるとそのまま実行します。bash は最初から使えますが、zsh は edit-command-line を autoload してキーに割り当てる必要があります。", "Öffnet die aktuelle Zeile im $EDITOR und führt sie nach Speichern und Beenden aus; bash kann das von Haus aus, zsh braucht edit-command-line per autoload und bindkey.", "Ouvre la ligne courante dans $EDITOR et l'exécute dès que vous enregistrez et quittez ; bash le fait d'origine, zsh exige edit-command-line en autoload puis un bindkey.", "मौजूदा पंक्ति को $EDITOR में खोलता है और सहेजकर निकलते ही चला देता है; bash में यह पहले से है, zsh में edit-command-line को autoload कर key से बाँधना पड़ता है।", "把当前行放到 $EDITOR 里改，保存退出后直接执行；bash 自带，zsh 需要 autoload edit-command-line 再绑到键上。", "把目前行放到 $EDITOR 裡改，儲存離開後直接執行；bash 內建，zsh 需要 autoload edit-command-line 再繫到鍵上。"],
  'terminal-meta-with-esc': ["Alt로 시작하는 모든 조합은 Esc를 먼저 누른 뒤 그 키를 눌러도 됩니다. Option이 Meta가 아닌 macOS 기본 터미널에서 사람들이 실제로 쓰는 길입니다.", "Every Alt combination can be typed as Esc followed by the key, which is the route people actually take in the macOS Terminal where Option is not Meta.", "Toda combinación con Alt puede escribirse como Esc y luego la tecla, que es el camino real en la Terminal de macOS donde Option no es Meta.", "Toda combinação com Alt pode ser digitada como Esc e depois a tecla, o caminho real no Terminal do macOS onde Option não é Meta.", "Alt で始まる組み合わせはすべて、Esc を押してからそのキーを押しても同じです。Option が Meta でない macOS の標準ターミナルで実際に使われる道です。", "Jede Alt-Kombination lässt sich als Esc gefolgt von der Taste tippen — der Weg, den man im macOS-Terminal geht, wo Option kein Meta ist.", "Toute combinaison avec Alt peut se taper comme Esc puis la touche, la voie réellement empruntée dans le Terminal de macOS où Option n'est pas Meta.", "Alt वाली हर जोड़ी को Esc दबाकर फिर वह key दबाकर भी लिखा जा सकता है — macOS Terminal में, जहाँ Option, Meta नहीं है, लोग यही रास्ता लेते हैं।", "所有以 Alt 开头的组合，都可以先按 Esc 再按那个键；在 Option 不是 Meta 的 macOS 终端里，大家走的就是这条路。", "所有以 Alt 開頭的組合，都可以先按 Esc 再按那個鍵；在 Option 不是 Meta 的 macOS 終端機裡，大家走的就是這條路。"],

  /* ───────── History ───────── */
  'terminal-reverse-search': ["치는 동안 히스토리를 거꾸로 훑어 맞는 명령을 보여 줍니다. 한 번 더 누르면 더 옛것으로 가고, Enter는 바로 실행이니 고치려면 방향키로 빠져나옵니다.", "Searches history backwards as you type; press it again for an older match, and remember Enter runs the command straight away, so leave with an arrow key to edit it first.", "Busca en el historial hacia atrás mientras escribes; púlsalo otra vez para una coincidencia más antigua, y ten en cuenta que Enter ejecuta al instante, así que sal con una flecha para editar.", "Busca no histórico para trás enquanto você digita; aperte de novo para uma ocorrência mais antiga, e lembre que Enter executa na hora, então saia com uma seta para editar.", "打ちながら履歴を後ろへたどり、合う命令を見せます。もう一度押すとさらに古い方へ進み、Enter はすぐ実行なので直したいときは矢印キーで抜けます。", "Durchsucht die History rückwärts während des Tippens; ein weiterer Druck findet Älteres, und Enter führt sofort aus — zum Bearbeiten mit einer Pfeiltaste verlassen.", "Cherche dans l'historique à reculons pendant la frappe ; une nouvelle pression remonte plus loin, et Enter exécute aussitôt, alors sortez avec une flèche pour modifier.", "टाइप करते-करते history में पीछे खोजता है; दोबारा दबाने पर और पुराना मेल मिलता है, और Enter सीधे चला देता है, इसलिए बदलने के लिए arrow key से बाहर आएँ।", "边输入边往回搜历史并显示匹配的命令；再按一次找更早的，注意 Enter 会立刻执行，想改就用方向键先退出来。", "邊輸入邊往回搜歷史並顯示符合的命令；再按一次找更早的，注意 Enter 會立刻執行，想改就用方向鍵先退出來。"],
  'terminal-abort-search': ["검색을 버리고 줄을 원래대로 돌려놓습니다. Esc는 찾은 명령을 줄에 남기지만 이 키는 찾기 전 상태로 되돌립니다.", "Abandons the search and restores the line as it was; Esc leaves the found command on the line, this key does not.", "Abandona la búsqueda y devuelve la línea a como estaba; Esc deja el comando encontrado, esta tecla no.", "Abandona a busca e devolve a linha como estava; Esc deixa o comando encontrado, esta tecla não.", "検索をやめて行を元の状態に戻します。Esc は見つけた命令を行に残しますが、このキーは探す前に戻します。", "Bricht die Suche ab und stellt die Zeile wie zuvor her; Esc lässt den gefundenen Befehl stehen, diese Taste nicht.", "Abandonne la recherche et rétablit la ligne telle qu'elle était ; Esc laisse la commande trouvée, cette touche non.", "खोज छोड़कर पंक्ति को पहले जैसा कर देता है; Esc मिला command पंक्ति में छोड़ देता है, यह key नहीं।", "放弃搜索并把这一行恢复原样；Esc 会把找到的命令留在行上，这个键不会。", "放棄搜尋並把這一行恢復原樣；Esc 會把找到的命令留在行上，這個鍵不會。"],
  'terminal-history-previous': ["히스토리에서 한 칸 앞의 명령을 불러옵니다. Up 방향키와 같은 일이라, 방향키가 통하지 않는 좁은 터미널에서 쓸 수 있습니다.", "Pulls the previous command from history; it is the same as the Up arrow, which makes it the fallback where arrow keys do not come through.", "Trae el comando anterior del historial; hace lo mismo que la flecha arriba, y sirve donde las flechas no llegan.", "Traz o comando anterior do histórico; faz o mesmo que a seta para cima, e serve onde as setas não passam.", "履歴から一つ前の命令を呼び出します。Up 矢印と同じ働きなので、矢印キーが通らない端末でも使えます。", "Holt den vorherigen Befehl aus der History; es entspricht der Pfeiltaste nach oben und hilft, wo Pfeiltasten nicht ankommen.", "Rappelle la commande précédente de l'historique ; identique à la flèche du haut, utile là où les flèches ne passent pas.", "history से पिछला command लाता है; यह Up arrow जैसा ही है, इसलिए जहाँ arrow keys नहीं पहुँचतीं वहाँ काम आता है।", "从历史里取出上一条命令；作用和上方向键相同，方向键传不过去的终端里就靠它。", "從歷史裡取出上一條命令；作用和上方向鍵相同，方向鍵傳不過去的終端機裡就靠它。"],
  'terminal-history-next': ["히스토리에서 한 칸 뒤의 명령으로 내려갑니다. 마지막까지 내려가면 치고 있던 빈 줄로 돌아옵니다.", "Steps forward to the next command in history; walking past the last one brings back the empty line you were typing.", "Avanza al siguiente comando del historial; al pasar del último vuelve la línea vacía que estabas escribiendo.", "Avança para o próximo comando do histórico; ao passar do último volta a linha vazia que você estava digitando.", "履歴で一つ後ろの命令へ下ります。最後まで下りると、打ちかけていた空の行に戻ります。", "Geht zum nächsten Befehl in der History; hinter dem letzten kehrt die leere Zeile zurück, die Sie gerade tippten.", "Avance à la commande suivante de l'historique ; au-delà de la dernière, la ligne vide que vous tapiez revient.", "history में अगले command पर जाता है; अंतिम के आगे बढ़ने पर वही ख़ाली पंक्ति लौट आती है जो आप लिख रहे थे।", "在历史里往后走一条命令；走过最后一条就回到你原本在敲的空行。", "在歷史裡往後走一條命令；走過最後一條就回到你原本在敲的空行。"],
  'terminal-last-command': ["앞 명령을 그대로 다시 실행합니다. sudo !! 로 쓰는 그 재주인데, 셸이 먼저 펼쳐 실행하므로 앞 명령이 위험한 것이었다면 그대로 한 번 더 일어납니다.", "Runs the previous command again — the trick behind sudo !! — and since the shell expands it before running, a dangerous last command happens a second time.", "Vuelve a ejecutar el comando anterior, el truco detrás de sudo !!; el shell lo expande antes de ejecutar, así que un comando peligroso se repite tal cual.", "Executa o comando anterior de novo, o truque por trás de sudo !!; o shell expande antes de rodar, então um comando perigoso acontece outra vez.", "直前の命令をそのまま再実行します。sudo !! の正体で、シェルが先に展開して走らせるため、前の命令が危ないものならもう一度そのまま起こります。", "Führt den vorherigen Befehl erneut aus — der Trick hinter sudo !! — und da die Shell vorher expandiert, wiederholt sich auch ein gefährlicher Befehl.", "Réexécute la commande précédente, l'astuce derrière sudo !! ; le shell l'étend avant de lancer, donc une commande dangereuse se reproduit à l'identique.", "पिछला command वैसा ही फिर चलाता है — sudo !! का राज़ यही है — और shell पहले उसे खोलकर चलाता है, इसलिए ख़तरनाक command दोबारा घट जाता है।", "把上一条命令原样再跑一次，这就是 sudo !! 的把戏；shell 会先展开再执行，所以上一条要是危险命令，它会再发生一次。", "把上一條命令原樣再跑一次，這就是 sudo !! 的把戲；shell 會先展開再執行，所以上一條要是危險命令，它會再發生一次。"],
  'terminal-last-argument': ["앞 명령의 마지막 인수를 그 자리에 세웁니다. 실행할 때 셸이 펼치는 것이라, Enter를 누르기 전에는 무엇이 들어갈지 화면에 보이지 않습니다.", "Stands in for the last argument of the previous command; the shell expands it at run time, so you cannot see what it will become before you press Enter.", "Sustituye al último argumento del comando anterior; el shell lo expande al ejecutar, así que no ves en qué se convierte antes de pulsar Enter.", "Substitui o último argumento do comando anterior; o shell expande na hora de executar, então você não vê no que vira antes de apertar Enter.", "直前の命令の最後の引数の代わりに立ちます。実行時にシェルが展開するので、Enter を押す前には何になるか画面に見えません。", "Steht für das letzte Argument des vorherigen Befehls; die Shell expandiert es erst beim Ausführen, man sieht das Ergebnis vorher nicht.", "Remplace le dernier argument de la commande précédente ; le shell l'étend à l'exécution, donc on ne voit pas le résultat avant Enter.", "पिछले command के अंतिम argument की जगह खड़ा होता है; shell इसे चलाते समय खोलता है, इसलिए Enter दबाने से पहले दिखता नहीं कि क्या बनेगा।", "代表上一条命令的最后一个参数；shell 是执行时才展开的，所以按 Enter 之前你看不到它会变成什么。", "代表上一條命令的最後一個引數；shell 是執行時才展開的，所以按 Enter 之前你看不到它會變成什麼。"],
  'terminal-yank-last-arg': ["앞 명령의 마지막 인수를 지금 줄에 글자로 넣어 줍니다. !$ 와 달리 눈으로 보고 고칠 수 있고, 한 번 더 누르면 그 앞 명령의 마지막 인수로 거슬러 갑니다.", "Inserts the last argument of the previous command as text you can see and edit, unlike !$, and pressing it again reaches back to the command before that.", "Inserta el último argumento del comando anterior como texto que puedes ver y editar, a diferencia de !$, y otra pulsación llega al comando previo.", "Insere o último argumento do comando anterior como texto que você vê e edita, diferente de !$, e outro toque alcança o comando anterior a esse.", "直前の命令の最後の引数を、いまの行に文字として入れます。!$ と違って目で見て直せ、もう一度押すとさらに前の命令の最後の引数へさかのぼります。", "Fügt das letzte Argument des vorherigen Befehls als sichtbaren, editierbaren Text ein — anders als !$ — und ein weiterer Druck greift auf den Befehl davor zurück.", "Insère le dernier argument de la commande précédente en texte visible et modifiable, contrairement à !$, et une nouvelle pression remonte à la commande antérieure.", "पिछले command का अंतिम argument दिखने-बदलने योग्य पाठ के रूप में डालता है, !$ की तरह नहीं, और दोबारा दबाने पर उससे पहले वाले command तक जाता है।", "把上一条命令的最后一个参数以可见可改的文字插进来，和 !$ 不同；再按一次就往前一条命令取。", "把上一條命令的最後一個引數以可見可改的文字插進來，和 !$ 不同；再按一次就往前一條命令取。"],
  'terminal-operate-and-get-next': ["줄을 실행한 다음, 히스토리에서 그 뒤에 있던 줄을 프롬프트에 올려 줍니다. 예전에 이어서 치던 명령 몇 개를 순서대로 다시 돌릴 때 씁니다.", "Runs the line and then puts the line that followed it in history onto the prompt — the way to replay a run of commands in order.", "Ejecuta la línea y luego coloca en el prompt la que la seguía en el historial: la forma de repetir una tanda de comandos en orden.", "Executa a linha e depois coloca no prompt a linha que vinha depois dela no histórico: o jeito de repetir uma sequência de comandos em ordem.", "行を実行し、続いて履歴でその次にあった行をプロンプトに出します。以前続けて打った命令をいくつか順番にやり直すのに使います。", "Führt die Zeile aus und legt danach die in der History folgende Zeile an den Prompt — so spielt man eine Befehlsfolge der Reihe nach nach.", "Exécute la ligne puis place au prompt celle qui la suivait dans l'historique : de quoi rejouer une série de commandes dans l'ordre.", "पंक्ति चलाकर फिर history में उसके बाद वाली पंक्ति prompt पर रख देता है — पहले चलाए कई commands को क्रम से दोहराने का तरीक़ा।", "先执行当前行，再把历史里紧跟其后的那一行放到提示符上——按顺序重放一串命令就靠它。", "先執行目前行，再把歷史裡緊跟其後的那一行放到提示符上——按順序重播一串命令就靠它。"],

  /* ───────── Completion ───────── */
  'terminal-complete': ["파일 이름이나 명령을 이어서 채웁니다. 두 번 누르면 후보를 늘어놓고, 아무 반응이 없다면 그 명령의 자동 완성 규칙이 깔려 있지 않은 것입니다.", "Completes a file name or a command; press it twice to list the candidates, and no reaction at all usually means that command's completion rules are not installed.", "Completa un nombre de archivo o un comando; pulsa dos veces para listar candidatos, y si no pasa nada suele ser que faltan las reglas de completado de ese comando.", "Completa um nome de arquivo ou um comando; aperte duas vezes para listar os candidatos, e nenhuma reação em geral significa que faltam as regras de completar daquele comando.", "ファイル名や命令の続きを埋めます。二度押すと候補を並べ、まったく反応が無いときはその命令の補完規則が入っていないということです。", "Vervollständigt einen Dateinamen oder Befehl; zweimal gedrückt listet es die Kandidaten, und gar keine Reaktion heißt meist, dass die Completion-Regeln fehlen.", "Complète un nom de fichier ou une commande ; deux pressions listent les candidats, et l'absence de réaction signifie généralement que les règles de complétion manquent.", "फ़ाइल नाम या command पूरा करता है; दो बार दबाने पर उम्मीदवार दिखते हैं, और कोई प्रतिक्रिया न हो तो अक्सर उस command के completion नियम स्थापित नहीं हैं।", "补全文件名或命令；按两次会列出候选，完全没反应通常是那个命令的补全规则没装。", "補全檔名或命令；按兩次會列出候選，完全沒反應通常是那個命令的補全規則沒裝。"],
  'terminal-list-completions': ["가능한 후보를 줄에 넣지 않고 아래에 늘어놓기만 합니다. Tab을 두 번 누르는 것과 같은 일인데, 반쯤 채워지는 것이 싫을 때 이 키를 씁니다.", "Lists every possible completion below without inserting anything; it is the same as pressing Tab twice, but it never half-fills the line.", "Enumera todas las opciones debajo sin insertar nada; equivale a pulsar Tab dos veces, pero nunca completa la línea a medias.", "Lista todas as opções abaixo sem inserir nada; equivale a apertar Tab duas vezes, mas nunca preenche a linha pela metade.", "候補を行に入れずに下へ並べるだけです。Tab を二度押すのと同じですが、中途半端に埋まるのが嫌なときはこちらを使います。", "Listet alle möglichen Ergänzungen darunter, ohne etwas einzufügen; wie zweimal Tab, füllt die Zeile aber nie halb.", "Liste toutes les complétions possibles en dessous sans rien insérer ; équivalent à deux Tab, mais sans remplir la ligne à moitié.", "सभी संभावित विकल्प नीचे दिखा देता है, कुछ डालता नहीं; यह Tab दो बार दबाने जैसा है, पर पंक्ति आधी नहीं भरता।", "只在下面列出所有可能的候选，不往行里插任何东西；等于按两次 Tab，但绝不把行填一半。", "只在下面列出所有可能的候選，不往行裡插任何東西；等於按兩次 Tab，但絕不把行填一半。"],
  'terminal-insert-completions': ["후보를 하나 고르지 않고 모두 줄에 넣습니다. *.log가 무엇으로 펼쳐지는지 실행하기 전에 눈으로 확인할 때 씁니다.", "Puts every match on the line instead of choosing one — the way to see what *.log expands to before you run anything.", "Pone todas las coincidencias en la línea en vez de elegir una: así ves en qué se expande *.log antes de ejecutar.", "Coloca todas as ocorrências na linha em vez de escolher uma: assim você vê no que *.log se expande antes de executar.", "候補を一つ選ぶのではなく全部を行に入れます。*.log が何に展開されるのかを実行前に目で確かめるのに使えます。", "Setzt alle Treffer in die Zeile statt einen auszuwählen — so sieht man, wozu *.log expandiert, bevor man etwas ausführt.", "Place toutes les correspondances sur la ligne au lieu d'en choisir une : pratique pour voir en quoi *.log se développe avant d'exécuter.", "एक चुनने की जगह सभी मेल पंक्ति में डाल देता है — चलाने से पहले देख लें कि *.log किसमें खुलता है।", "不是选一个，而是把所有匹配都放进行里——执行前先看清 *.log 会展开成什么。", "不是選一個，而是把所有符合的都放進行裡——執行前先看清 *.log 會展開成什麼。"],

  /* ───────── Signals ───────── */
  'terminal-interrupt': ["돌고 있는 명령에 SIGINT를 보내 멈춥니다. 프로그램이 이 신호를 잡아 무시할 수도 있고, 멈춰 세운 작업에는 닿지 않습니다.", "Sends SIGINT to the running command to stop it; a program is allowed to catch and ignore it, and it does not reach a job you already suspended.", "Envía SIGINT al comando en marcha para detenerlo; un programa puede capturarlo e ignorarlo, y no alcanza a un trabajo ya suspendido.", "Envia SIGINT ao comando em execução para pará-lo; um programa pode capturar e ignorar, e não alcança um trabalho já suspenso.", "動いている命令に SIGINT を送って止めます。プログラムはこの信号を捕まえて無視できますし、すでに止めた仕事には届きません。", "Sendet SIGINT an den laufenden Befehl; ein Programm darf es abfangen und ignorieren, und einen bereits angehaltenen Job erreicht es nicht.", "Envoie SIGINT à la commande en cours pour l'arrêter ; un programme peut l'intercepter et l'ignorer, et il n'atteint pas un travail déjà suspendu.", "चल रहे command को SIGINT भेजकर रोकता है; कोई program इसे पकड़कर अनदेखा कर सकता है, और पहले से रोके गए काम तक यह नहीं पहुँचता।", "给正在跑的命令发 SIGINT 让它停下；程序可以捕获并忽略它，而且它管不到已经被挂起的作业。", "給正在跑的命令發 SIGINT 讓它停下；程式可以攔截並忽略它，而且它管不到已經被暫停的工作。"],
  'terminal-eof': ["입력이 끝났다는 표를 보냅니다. 줄이 비어 있으면 셸 자체가 끝나 창이 닫히고, 줄에 글자가 있으면 커서 밑의 글자를 지우는 다른 일을 합니다.", "Signals end of input; on an empty line it ends the shell and the window closes, while on a line with text it deletes the character under the cursor instead.", "Indica fin de entrada; en una línea vacía termina el shell y la ventana se cierra, mientras que con texto borra el carácter bajo el cursor.", "Sinaliza fim de entrada; em uma linha vazia encerra o shell e a janela fecha, mas em uma linha com texto apaga o caractere sob o cursor.", "入力の終わりを知らせます。行が空ならシェル自体が終わって窓が閉じ、行に文字があるときはカーソル下の一文字を消す別の働きになります。", "Signalisiert das Ende der Eingabe; auf leerer Zeile endet die Shell und das Fenster schließt, bei Text löscht es stattdessen das Zeichen unter dem Cursor.", "Signale la fin de l'entrée ; sur une ligne vide, le shell se termine et la fenêtre se ferme, sur une ligne remplie il supprime le caractère sous le curseur.", "इनपुट के अंत का संकेत भेजता है; पंक्ति ख़ाली हो तो shell ही ख़त्म होकर खिड़की बंद हो जाती है, और पंक्ति में पाठ हो तो cursor के नीचे का अक्षर मिट जाता है।", "发出输入结束的信号；行是空的就结束 shell、窗口关掉，行里有字则改成删除光标下的那个字符。", "發出輸入結束的訊號；行是空的就結束 shell、視窗關掉，行裡有字則改成刪除游標下的那個字元。"],
  'terminal-suspend': ["돌고 있는 작업을 멈춰 세우고 프롬프트를 돌려줍니다. 끝난 것이 아니라 멈춘 것이므로 fg나 bg로 다시 살려야 하고, 잊고 창을 닫으면 그대로 죽습니다.", "Stops the running job and hands the prompt back; the job is paused rather than finished, so bring it back with fg or bg, or it dies when you close the window.", "Detiene el trabajo en marcha y devuelve el prompt; el trabajo queda en pausa, no terminado, así que recupéralo con fg o bg o morirá al cerrar la ventana.", "Para o trabalho em execução e devolve o prompt; ele fica pausado, não terminado, então traga de volta com fg ou bg, senão morre ao fechar a janela.", "動いている仕事を止めてプロンプトを返します。終わったのではなく止まっただけなので fg か bg で戻す必要があり、忘れて窓を閉じるとそのまま死にます。", "Hält den laufenden Job an und gibt den Prompt zurück; der Job ist pausiert, nicht beendet — mit fg oder bg zurückholen, sonst stirbt er beim Schließen des Fensters.", "Suspend le travail en cours et rend le prompt ; il est en pause et non terminé, reprenez-le avec fg ou bg, sinon il meurt à la fermeture de la fenêtre.", "चल रहे काम को रोककर prompt लौटा देता है; काम ख़त्म नहीं, रुका है, इसलिए fg या bg से लौटाएँ, वरना खिड़की बंद करते ही वह मर जाता है।", "把正在跑的作业挂起并把提示符还给你；它是暂停而不是结束，要用 fg 或 bg 唤回，忘了就随窗口一起死掉。", "把正在跑的工作暫停並把提示符還給你；它是暫停而不是結束，要用 fg 或 bg 喚回，忘了就隨視窗一起死掉。"],

  /* ───────── Screen ───────── */
  'terminal-clear-screen': ["화면을 비우고 프롬프트를 맨 위로 올립니다. 치고 있던 줄은 그대로 남고, 위로 올려 보던 기록도 사라지지 않습니다.", "Wipes the screen and moves the prompt to the top; the line you were typing survives and the scrollback is still there.", "Limpia la pantalla y sube el prompt arriba; la línea que estabas escribiendo se mantiene y el historial de desplazamiento sigue ahí.", "Limpa a tela e sobe o prompt para o topo; a linha que você estava digitando permanece e o histórico de rolagem continua lá.", "画面を消してプロンプトを一番上へ上げます。打っていた行はそのまま残り、さかのぼって見られる記録も消えません。", "Löscht den Bildschirm und setzt den Prompt nach oben; die getippte Zeile bleibt, und der Scrollback ist weiterhin da.", "Efface l'écran et remonte le prompt en haut ; la ligne en cours de saisie reste, et l'historique de défilement est intact.", "स्क्रीन साफ़ करके prompt को सबसे ऊपर ले जाता है; जो पंक्ति आप लिख रहे थे वह बची रहती है और ऊपर का इतिहास भी मिटता नहीं।", "清屏并把提示符移到最上面；你正在敲的那一行还在，往上翻的记录也没丢。", "清除畫面並把提示符移到最上面；你正在敲的那一行還在，往上捲的記錄也沒丟。"],
  'terminal-stop-output': ["출력을 멈춰 세웁니다 — 터미널이 죽은 것처럼 보이는 그 범인입니다. 고장이 아니라 흐름 제어이니 Ctrl+Q로 풀리고, 이 키가 readline의 앞으로 찾기를 가로채므로 그것을 쓰려면 stty -ixon이 필요합니다.", "Freezes the output — this is the culprit behind a terminal that looks dead — so nothing is broken and Ctrl+Q releases it, and because it steals readline's forward search you need stty -ixon to get that back.", "Congela la salida: es el culpable de que una terminal parezca muerta, nada está roto y Ctrl+Q la libera, y como roba la búsqueda hacia delante de readline hace falta stty -ixon para recuperarla.", "Congela a saída: é o culpado por um terminal que parece morto, nada está quebrado e Ctrl+Q libera, e como ele rouba a busca para frente do readline você precisa de stty -ixon para reavê-la.", "出力を止めます — 端末が死んだように見える原因はこれです。故障ではなく流れ制御なので Ctrl+Q で解け、readline の前方検索を横取りするため、それを使うには stty -ixon が必要です。", "Friert die Ausgabe ein — der Schuldige, wenn ein Terminal totgeglaubt wird; nichts ist kaputt, Ctrl+Q löst es, und da es readlines Vorwärtssuche wegnimmt, braucht man dafür stty -ixon.", "Gèle la sortie : c'est le coupable derrière un terminal qui semble mort, rien n'est cassé et Ctrl+Q le libère, et comme il vole la recherche avant de readline il faut stty -ixon pour la retrouver.", "आउटपुट जमा देता है — terminal मरा हुआ लगने की वजह यही है; कुछ टूटा नहीं, Ctrl+Q से खुल जाता है, और यह readline की आगे-खोज छीन लेता है, इसलिए उसके लिए stty -ixon चाहिए।", "冻结输出——终端看起来死掉的元凶就是它；没坏，Ctrl+Q 就解开，而且它抢走了 readline 的向前搜索，想用得先 stty -ixon。", "凍結輸出——終端機看起來死掉的元凶就是它；沒壞，Ctrl+Q 就解開，而且它搶走了 readline 的向前搜尋，想用得先 stty -ixon。"],
  'terminal-resume-output': ["멈춰 둔 출력을 다시 흐르게 합니다. 터미널이 아무 반응도 없을 때 가장 먼저 눌러 볼 키이고, 멈춘 동안 쌓인 것이 한꺼번에 쏟아집니다.", "Lets the frozen output flow again; it is the first key to try on an unresponsive terminal, and everything held back pours out at once.", "Deja fluir de nuevo la salida congelada; es la primera tecla que probar en una terminal que no responde, y todo lo retenido sale de golpe.", "Deixa a saída congelada fluir de novo; é a primeira tecla a tentar num terminal que não responde, e tudo o que ficou preso jorra de uma vez.", "止めていた出力をまた流します。端末が何も反応しないときに最初に押すべきキーで、止まっている間に溜まったものが一気に流れ出します。", "Lässt die eingefrorene Ausgabe wieder fließen; die erste Taste bei einem stummen Terminal, und alles Zurückgehaltene bricht auf einmal hervor.", "Relance la sortie gelée ; c'est la première touche à essayer sur un terminal muet, et tout ce qui était retenu déferle d'un coup.", "जमे हुए आउटपुट को फिर बहने देता है; बिना प्रतिक्रिया वाले terminal पर पहले यही key दबाएँ, और रुका हुआ सब एक साथ बह निकलता है।", "让冻结的输出重新流动；终端毫无反应时第一个该按的就是它，憋着的内容会一下全涌出来。", "讓凍結的輸出重新流動；終端機毫無反應時第一個該按的就是它，憋著的內容會一下全湧出來。"],
  /* ═════════ slack ═════════ */

  /* ───────── Basics ───────── */
  'slack-all-shortcuts': ["슬랙 안에서 쓸 수 있는 단축키를 전부 목록으로 띄웁니다. 하나만 외운다면 이것을 외우면 되고, 목록은 지금 보고 있는 화면에 맞춰 달라집니다.", "Pops up the full list of Slack shortcuts; if you memorize only one, memorize this, and the list changes with the part of Slack you are in.", "Muestra la lista completa de atajos de Slack; si solo memorizas uno, que sea este, y la lista cambia según la parte de Slack en la que estés.", "Abre a lista completa de atalhos do Slack; se for memorizar só um, memorize este, e a lista muda conforme a parte do Slack em que você está.", "Slack で使えるキー割り当ての一覧をまるごと出します。一つだけ覚えるならこれで、一覧は今いる画面に応じて変わります。", "Zeigt die vollständige Liste der Slack-Kürzel; wenn Sie nur eines behalten, dann dieses, und die Liste richtet sich nach dem Bereich, in dem Sie sind.", "Affiche la liste complète des raccourcis Slack ; si vous n'en retenez qu'un, retenez celui-ci, et la liste varie selon l'endroit où vous êtes.", "Slack के सभी shortcuts की पूरी सूची दिखा देता है; एक ही याद रखना हो तो यही रखें, और सूची इस पर बदलती है कि आप किस हिस्से में हैं।", "弹出 Slack 全部快捷键的列表；只记一个的话就记它，而列表会随你当前所在的界面变化。", "彈出 Slack 全部快速鍵的清單；只記一個的話就記它，而清單會隨你目前所在的介面變化。"],
  'slack-preferences': ["알림과 테마 같은 내 설정 창을 엽니다. 워크스페이스 전체를 다루는 관리자 설정은 여기가 아니라 브라우저에서 열립니다.", "Opens your own preferences such as notifications and theme; workspace-wide admin settings are not here and open in the browser instead.", "Abre tus preferencias, como notificaciones y tema; la configuración de administrador del espacio de trabajo no está aquí y se abre en el navegador.", "Abre suas preferências, como notificações e tema; as configurações de administrador do workspace não ficam aqui e abrem no navegador.", "通知やテーマといった自分の設定を開きます。ワークスペース全体を扱う管理者設定はここではなく、ブラウザーで開きます。", "Öffnet die eigenen Einstellungen wie Benachrichtigungen und Design; die Administration des Workspace liegt nicht hier, sondern im Browser.", "Ouvre vos préférences, notifications et thème par exemple ; les réglages d'administration de l'espace de travail s'ouvrent dans le navigateur.", "अपनी सेटिंग्स — सूचनाएँ, थीम आदि — खोलता है; पूरे workspace की admin सेटिंग्स यहाँ नहीं, browser में खुलती हैं।", "打开你自己的偏好设置，比如通知和主题；管理整个工作区的管理员设置不在这里，会在浏览器里打开。", "打開你自己的偏好設定，比如通知和主題；管理整個工作區的管理員設定不在這裡，會在瀏覽器裡打開。"],
  'slack-set-status': ["상태 메시지와 이모지를 정하는 창을 엽니다. 지울 시각을 함께 고르지 않으면 그 상태가 계속 남아, 회의가 끝나도 회의 중으로 보입니다.", "Opens the box for your status text and emoji; unless you pick a clear-after time it stays up, so you still look busy long after the meeting ended.", "Abre el cuadro del texto de estado y su emoji; si no eliges cuándo borrarlo, se queda puesto y seguirás pareciendo ocupado tras la reunión.", "Abre a caixa do texto de status e do emoji; se você não escolher quando limpar, ele fica lá e você continua parecendo ocupado depois da reunião.", "状態のメッセージと絵文字を決める窓を開きます。消す時刻を選ばないと残り続けるので、会議が終わっても会議中に見えます。", "Öffnet das Feld für Statustext und Emoji; ohne gewählte Löschzeit bleibt er stehen, und Sie wirken noch lange nach dem Meeting beschäftigt.", "Ouvre la fenêtre du texte de statut et de son emoji ; sans durée d'effacement, il reste affiché et vous paraissez occupé bien après la réunion.", "स्थिति का संदेश और emoji तय करने का बक्सा खोलता है; हटाने का समय न चुनें तो वह टिका रहता है और बैठक ख़त्म होने पर भी आप व्यस्त दिखते हैं।", "打开设置状态文字和表情的框；不选清除时间它就一直挂着，会议早结束了你看着还在忙。", "打開設定狀態文字和表情的框；不選清除時間它就一直掛著，會議早結束了你看著還在忙。"],
  'slack-compose-message': ["받는 곳을 아직 고르지 않은 빈 메시지 창을 엽니다. 먼저 쓰고 나중에 채널이나 사람을 정할 수 있어 초안처럼 씁니다.", "Opens an empty message with no recipient chosen yet, so you can write first and decide the channel or person afterwards.", "Abre un mensaje vacío sin destinatario, así puedes escribir primero y decidir el canal o la persona después.", "Abre uma mensagem vazia sem destinatário, então você escreve primeiro e decide o canal ou a pessoa depois.", "宛先をまだ決めていない空のメッセージを開きます。先に書いてから channel や相手を決められるので、下書きのように使えます。", "Öffnet eine leere Nachricht ohne Empfänger, sodass man erst schreibt und Kanal oder Person danach wählt.", "Ouvre un message vide sans destinataire : on écrit d'abord et on choisit le canal ou la personne ensuite.", "बिना प्राप्तकर्ता वाला ख़ाली संदेश खोलता है, ताकि पहले लिखें और channel या व्यक्ति बाद में तय करें।", "打开一个还没选收件人的空消息，可以先写内容，之后再决定发到哪个频道或发给谁。", "打開一個還沒選收件人的空訊息，可以先寫內容，之後再決定發到哪個頻道或發給誰。"],
  'slack-upload-file': ["파일 고르는 창을 열어 지금 대화에 올립니다. 윈도우에서 Ctrl+O는 파일 열기가 아니라 올리기라는 점만 다릅니다.", "Opens the file picker to upload into the conversation you are in; note that here Ctrl+O uploads rather than opens.", "Abre el selector de archivos para subirlo a la conversación actual; ojo, aquí Ctrl+O sube en lugar de abrir.", "Abre o seletor de arquivos para enviar na conversa atual; note que aqui Ctrl+O envia em vez de abrir.", "ファイル選択の窓を開き、いまの会話に上げます。ここでの Ctrl+O は開くではなく上げるという点だけが違います。", "Öffnet die Dateiauswahl zum Hochladen in die aktuelle Unterhaltung; Ctrl+O lädt hier hoch statt zu öffnen.", "Ouvre le sélecteur de fichiers pour l'envoyer dans la conversation courante ; ici Ctrl+O envoie au lieu d'ouvrir.", "फ़ाइल चुनने का बक्सा खोलकर मौजूदा बातचीत में भेजता है; ध्यान दें कि यहाँ Ctrl+O खोलना नहीं, भेजना है।", "打开文件选择框，上传到当前会话；注意这里的 Ctrl+O 是上传，不是打开。", "打開檔案選擇框，上傳到目前對話；注意這裡的 Ctrl+O 是上傳，不是開啟。"],

  /* ───────── Navigation ───────── */
  'slack-quick-switcher': ["채널이나 사람 이름 몇 글자로 그 대화로 건너갑니다. 검색이 아니라 옮겨 다니는 창이라 메시지 본문은 찾지 못합니다 — 그것은 Ctrl+G입니다.", "Jumps to a conversation from a few letters of a channel or person's name; it is a switcher and not search, so it never looks inside messages — that is Ctrl+G.", "Salta a una conversación con unas letras del nombre del canal o la persona; es un conmutador, no una búsqueda, así que no mira dentro de los mensajes: eso es Ctrl+G.", "Salta para uma conversa com poucas letras do nome do canal ou da pessoa; é um alternador, não busca, então não olha dentro das mensagens: isso é Ctrl+G.", "channel や相手の名前の数文字でその会話へ飛びます。検索ではなく移動の窓なので、メッセージ本文は探せません — それは Ctrl+G です。", "Springt über wenige Buchstaben eines Kanal- oder Personennamens in die Unterhaltung; es ist ein Umschalter, keine Suche, und schaut nie in Nachrichten — das tut Ctrl+G.", "Va à une conversation depuis quelques lettres du nom d'un canal ou d'une personne ; c'est un sélecteur et non une recherche, il ne lit pas les messages — c'est Ctrl+G.", "channel या व्यक्ति के नाम के कुछ अक्षरों से उस बातचीत पर पहुँचाता है; यह switcher है, खोज नहीं, इसलिए संदेशों के भीतर नहीं देखता — वह Ctrl+G है।", "输入频道或人名的几个字母就跳到那个会话；它是切换器不是搜索，不会去看消息正文——那是 Ctrl+G。", "輸入頻道或人名的幾個字母就跳到那個對話；它是切換器不是搜尋，不會去看訊息內容——那是 Ctrl+G。"],
  'slack-search': ["워크스페이스 전체에서 메시지와 파일을 찾습니다. Ctrl+K로 이것을 기대하고 눌러 채널 이름만 나와 헤매는 사람이 많습니다.", "Searches messages and files across the whole workspace; plenty of people press Ctrl+K expecting this and get only channel names.", "Busca mensajes y archivos en todo el espacio de trabajo; mucha gente pulsa Ctrl+K esperando esto y solo obtiene nombres de canales.", "Busca mensagens e arquivos em todo o workspace; muita gente aperta Ctrl+K esperando isso e só recebe nomes de canais.", "ワークスペース全体からメッセージやファイルを探します。Ctrl+K でこれを期待して押し、channel の名前しか出ずに迷う人が多いところです。", "Sucht Nachrichten und Dateien im gesamten Workspace; viele drücken Ctrl+K in dieser Erwartung und erhalten nur Kanalnamen.", "Recherche messages et fichiers dans tout l'espace de travail ; beaucoup appuient sur Ctrl+K en espérant cela et n'obtiennent que des noms de canaux.", "पूरे workspace में संदेश और फ़ाइलें खोजता है; बहुत लोग यही सोचकर Ctrl+K दबाते हैं और उन्हें केवल channel के नाम मिलते हैं।", "在整个工作区里搜消息和文件；很多人以为按 Ctrl+K 就是这个，结果只搜到频道名。", "在整個工作區裡搜訊息和檔案；很多人以為按 Ctrl+K 就是這個，結果只搜到頻道名。"],
  'slack-search-conversation': ["찾는 범위를 지금 보고 있는 대화 하나로 좁힙니다. 결과가 너무 많을 때 워크스페이스 전체 검색 대신 쓰면 빠릅니다.", "Narrows the search to the one conversation you are looking at, which is faster than the workspace-wide search when the results flood you.", "Limita la búsqueda a la conversación que tienes delante, más rápido que buscar en todo el espacio de trabajo cuando salen demasiados resultados.", "Limita a busca à conversa que você está vendo, mais rápido que a busca em todo o workspace quando vêm resultados demais.", "探す範囲を、いま見ている会話ひとつに絞ります。結果が多すぎるときはワークスペース全体の検索より速く済みます。", "Beschränkt die Suche auf die gerade offene Unterhaltung — schneller als die workspaceweite Suche, wenn zu viele Treffer kommen.", "Restreint la recherche à la seule conversation affichée, plus rapide que la recherche globale quand les résultats abondent.", "खोज को केवल उसी बातचीत तक सीमित करता है जो आप देख रहे हैं, जो बहुत परिणाम आने पर पूरे workspace की खोज से तेज़ है।", "把搜索范围收窄到你正在看的这一个会话；结果太多时比全工作区搜索更快。", "把搜尋範圍收窄到你正在看的這一個對話；結果太多時比全工作區搜尋更快。"],
  'slack-previous-channel': ["사이드바에 놓인 차례대로 한 칸 위 대화로 옮깁니다. 새 글이 있는 곳을 골라 가는 것이 아니라 목록 순서를 따라가므로, 아래쪽 채널까지는 여러 번 눌러야 합니다.", "Moves one conversation up in the order the sidebar shows; it follows that order rather than where new messages are, so a channel near the bottom takes several presses.", "Sube una conversación en el orden de la barra lateral; sigue ese orden y no dónde hay mensajes nuevos, así que un canal del final necesita varias pulsaciones.", "Sobe uma conversa na ordem da barra lateral; segue essa ordem e não onde há mensagens novas, então um canal do fim exige várias apertadas.", "サイドバーに並んだ順で一つ上の会話へ移ります。新しい書き込みのある所を選ぶのではなく並び順をたどるので、下の channel までは何度も押します。", "Wechselt eine Unterhaltung nach oben in der Reihenfolge der Seitenleiste; sie folgt dieser Ordnung, nicht den neuen Nachrichten, weshalb ein Kanal weit unten mehrere Drücke braucht.", "Remonte d'une conversation dans l'ordre de la barre latérale ; il suit cet ordre et non les nouveaux messages, donc un canal en bas demande plusieurs pressions.", "sidebar में दिखे क्रम से एक बातचीत ऊपर जाता है; यह क्रम का पालन करता है, नए संदेशों का नहीं, इसलिए नीचे वाले channel तक कई बार दबाना पड़ता है।", "按侧边栏显示的顺序往上换一个会话；它跟的是这个顺序而不是哪里有新消息，所以靠底部的频道要按好几次。", "按側邊欄顯示的順序往上換一個對話；它跟的是這個順序而不是哪裡有新訊息，所以靠底部的頻道要按好幾次。"],
  'slack-next-channel': ["사이드바 차례대로 한 칸 아래 대화로 옮깁니다. 여기에 Shift를 더하면 읽지 않은 곳만 골라 건너뛰므로 훨씬 빠릅니다.", "Moves one conversation down the sidebar order; add Shift and it skips straight to the ones with unread messages instead.", "Baja una conversación en el orden de la barra lateral; añade Shift y salta solo a las que tienen mensajes sin leer.", "Desce uma conversa na ordem da barra lateral; acrescente Shift e ele pula direto para as que têm mensagens não lidas.", "サイドバーの順で一つ下の会話へ移ります。ここに Shift を足すと未読のある所だけを選んで飛ぶので、ずっと速くなります。", "Wechselt eine Unterhaltung nach unten in der Seitenleistenreihenfolge; mit Shift springt es stattdessen nur zu ungelesenen.", "Descend d'une conversation dans l'ordre de la barre latérale ; avec Shift, il ne saute qu'aux conversations non lues.", "sidebar के क्रम से एक बातचीत नीचे जाता है; इसमें Shift जोड़ें तो यह सीधे बिना पढ़े वालों पर ही कूदता है।", "按侧边栏顺序往下换一个会话；加上 Shift 就只跳到有未读的那些，快得多。", "按側邊欄順序往下換一個對話；加上 Shift 就只跳到有未讀的那些，快得多。"],
  'slack-history-back': ["브라우저처럼 방금 보던 화면으로 돌아갑니다. 윈도우는 Alt+Left인데 맥은 Cmd+[ 라서, 두 기계를 함께 쓰면 여기서 손이 헛돕니다.", "Goes back to the view you just left, like a browser; Windows uses Alt+Left while mac uses Cmd+[, so hands slip here when you use both.", "Vuelve a la vista anterior, como en un navegador; en Windows es Alt+Left y en mac Cmd+[, así que la mano se equivoca si usas ambos.", "Volta para a visão anterior, como num navegador; no Windows é Alt+Left e no mac Cmd+[, então a mão erra quando você usa os dois.", "ブラウザーのように直前に見ていた画面へ戻ります。Windows は Alt+Left ですが Mac は Cmd+[ なので、両方を使うと手が迷います。", "Geht zur zuletzt verlassenen Ansicht zurück wie im Browser; Windows nutzt Alt+Left, der Mac Cmd+[ — beim Wechsel greift die Hand daneben.", "Revient à la vue précédente, comme dans un navigateur ; Windows utilise Alt+Left et mac Cmd+[, d'où les fausses manœuvres quand on jongle.", "browser की तरह पिछली स्क्रीन पर लौटता है; Windows पर Alt+Left है और mac पर Cmd+[, इसलिए दोनों चलाने पर हाथ चूक जाता है।", "像浏览器一样退回刚才看的界面；Windows 是 Alt+Left，mac 是 Cmd+[，两台机器换着用手就会按错。", "像瀏覽器一樣退回剛才看的介面；Windows 是 Alt+Left，mac 是 Cmd+[，兩台機器換著用手就會按錯。"],
  'slack-history-forward': ["돌아온 만큼 다시 앞으로 갑니다. 채널을 옮겨 다닌 자취를 따라가는 것이라, 읽지 않은 글 순서와는 아무 상관이 없습니다.", "Moves forward again through the views you came back from; it follows your own trail between channels and has nothing to do with unread order.", "Avanza de nuevo por las vistas de las que volviste; sigue tu propio rastro entre canales y no tiene nada que ver con el orden de no leídos.", "Avança de novo pelas visões de onde você voltou; segue o seu próprio rastro entre canais e não tem relação com a ordem dos não lidos.", "戻った分をまた先へ進みます。channel を渡り歩いた足跡をたどるだけで、未読の順番とは関係ありません。", "Geht die zurückgegangenen Ansichten wieder vorwärts; es folgt Ihrer eigenen Spur zwischen Kanälen und nicht der Ungelesen-Reihenfolge.", "Avance de nouveau dans les vues quittées ; il suit votre propre parcours entre canaux, sans rapport avec l'ordre des non-lus.", "जिन स्क्रीनों से लौटे थे, उनमें फिर आगे जाता है; यह channel के बीच आपके ही रास्ते पर चलता है, बिना पढ़े क्रम से इसका कोई संबंध नहीं।", "沿着你退回来的路径再往前走；它跟的是你在频道间的足迹，与未读顺序无关。", "沿著你退回來的路徑再往前走；它跟的是你在頻道間的足跡，與未讀順序無關。"],

  /* ───────── Unreads ───────── */
  'slack-jump-to-unread': ["이 대화에서 읽던 자리로 데려다 줍니다. 채널을 열 때마다 위로 끌어 올리며 찾지 않아도 됩니다.", "Takes you to where you stopped reading in this conversation, so you do not have to scroll up hunting for it every time you open a channel.", "Te lleva a donde dejaste de leer en esta conversación, así no tienes que subir buscándolo cada vez que abres un canal.", "Leva você até onde parou de ler nesta conversa, sem precisar rolar para cima procurando a cada vez que abre um canal.", "この会話で読んでいた位置まで連れて行きます。channel を開くたびに上へたぐって探す必要がなくなります。", "Bringt Sie an die Stelle, an der Sie in dieser Unterhaltung aufgehört haben zu lesen — kein Hochscrollen und Suchen bei jedem Kanal.", "Vous ramène là où vous avez arrêté de lire dans cette conversation, sans remonter à la recherche du point de reprise.", "इस बातचीत में जहाँ आपने पढ़ना छोड़ा था वहाँ ले जाता है, ताकि हर बार channel खोलकर ऊपर खिसकाना न पड़े।", "带你回到这个会话里上次读到的位置，不用每次打开频道都往上翻找。", "帶你回到這個對話裡上次讀到的位置，不用每次打開頻道都往上翻找。"],
  'slack-previous-unread': ["읽지 않은 글이 있는 앞쪽 대화로 건너뜁니다. 이미 읽은 채널은 그냥 지나치므로 목록을 하나하나 오르는 것보다 빠릅니다.", "Skips to the previous conversation that has unread messages, stepping over the ones you already read.", "Salta a la conversación anterior con mensajes sin leer y pasa de largo las que ya leíste.", "Pula para a conversa anterior com mensagens não lidas, passando por cima das que você já leu.", "未読のある前の会話へ跳びます。すでに読んだ channel は飛ばすので、一つずつ上がるより速く済みます。", "Springt zur vorherigen Unterhaltung mit ungelesenen Nachrichten und überspringt die bereits gelesenen.", "Saute à la conversation précédente contenant des messages non lus, en passant par-dessus celles déjà lues.", "पिछली उस बातचीत पर कूदता है जिसमें बिना पढ़े संदेश हैं, और पढ़ी हुई को छोड़ देता है।", "跳到上一个有未读消息的会话，已经读过的直接跳过。", "跳到上一個有未讀訊息的對話，已經讀過的直接跳過。"],
  'slack-next-unread': ["읽지 않은 글이 있는 다음 대화로 건너뜁니다. 사이드바에서 접어 둔 구역까지 함께 돌기 때문에 잊고 있던 채널이 갑자기 열립니다.", "Skips to the next conversation with unread messages; it walks into collapsed sidebar sections too, so a channel you had forgotten suddenly opens.", "Salta a la siguiente conversación con mensajes sin leer; también entra en secciones plegadas de la barra lateral, así que aparece un canal que habías olvidado.", "Pula para a próxima conversa com mensagens não lidas; ele entra até em seções recolhidas da barra lateral, então um canal esquecido aparece de repente.", "未読のある次の会話へ跳びます。サイドバーで畳んだ区画まで回るので、忘れていた channel が突然開くことがあります。", "Springt zur nächsten Unterhaltung mit Ungelesenem; auch eingeklappte Bereiche der Seitenleiste werden durchlaufen, sodass plötzlich ein vergessener Kanal erscheint.", "Saute à la conversation suivante non lue ; il entre aussi dans les sections replagées de la barre latérale, si bien qu'un canal oublié s'ouvre soudain.", "अगली उस बातचीत पर कूदता है जिसमें बिना पढ़े संदेश हैं; यह sidebar के समेटे हुए हिस्सों में भी जाता है, इसलिए भूला हुआ channel अचानक खुल जाता है।", "跳到下一个有未读的会话；它连侧边栏里折叠的分区也会走，所以可能突然打开一个你早忘了的频道。", "跳到下一個有未讀的對話；它連側邊欄裡折疊的分區也會走，所以可能突然打開一個你早忘了的頻道。"],
  'slack-mark-read': ["지금 대화를 다 읽은 것으로 표시합니다. 창을 닫지도 옮기지도 않고 굵은 표시만 지워 줍니다.", "Marks the current conversation as read; it closes nothing and moves nowhere, it just clears the bold badge.", "Marca la conversación actual como leída; no cierra ni cambia nada, solo quita la marca en negrita.", "Marca a conversa atual como lida; não fecha nem muda nada, apenas limpa o destaque em negrito.", "いまの会話を読み終えたものとして印します。窓を閉じたり移動したりせず、太字の印だけを消します。", "Markiert die aktuelle Unterhaltung als gelesen; es schließt nichts und wechselt nirgends, es nimmt nur die fette Markierung weg.", "Marque la conversation courante comme lue ; rien ne se ferme, rien ne bouge, seule la marque en gras disparaît.", "मौजूदा बातचीत को पढ़ा हुआ चिह्नित करता है; कुछ बंद या बदलता नहीं, केवल गाढ़ा निशान हटा देता है।", "把当前会话标记为已读；不关也不跳，只是把加粗的提示去掉。", "把目前對話標記為已讀；不關也不跳，只是把粗體的提示去掉。"],
  'slack-mark-all-read': ["워크스페이스의 모든 대화를 읽은 것으로 한꺼번에 표시합니다. 되돌리는 단추가 없으니, 읽지 않은 표시를 할 일 목록처럼 쓰고 있었다면 그것이 모두 사라집니다.", "Marks every conversation in the workspace as read at once; there is no undo, so if you were using unread badges as a to-do list they are all gone.", "Marca de golpe todas las conversaciones del espacio de trabajo como leídas; no hay deshacer, así que si usabas los no leídos como lista de tareas, desaparecen.", "Marca de uma vez todas as conversas do workspace como lidas; não há como desfazer, então se você usava os não lidos como lista de tarefas, acabou.", "ワークスペースのすべての会話を一度に既読にします。取り消す手立てが無いので、未読の印を作業一覧として使っていた場合はまるごと消えます。", "Markiert alle Unterhaltungen im Workspace auf einmal als gelesen; es gibt kein Zurück, und wer Ungelesen-Markierungen als Aufgabenliste nutzte, verliert sie.", "Marque d'un coup toutes les conversations de l'espace de travail comme lues ; aucune annulation, donc si les non-lus vous servaient de liste de tâches, tout disparaît.", "workspace की सारी बातचीतें एक साथ पढ़ी हुई चिह्नित कर देता है; इसे उलटा करने का कोई तरीक़ा नहीं, और यदि आप बिना पढ़े निशानों को कामों की सूची मान रहे थे तो वह सब चला गया।", "一次把工作区里所有会话标记为已读；没有撤销，如果你把未读当待办清单用，那就全没了。", "一次把工作區裡所有對話標記為已讀；沒有復原，如果你把未讀當待辦清單用，那就全沒了。"],
  'slack-all-unreads-view': ["읽지 않은 글을 한 화면에 모아 보여 줍니다. 이 화면에서 Esc는 지금 묶음을 읽은 것으로 표시하는 뜻이라, 넘기다 잘못 누르면 되돌릴 수 없습니다.", "Gathers everything unread into one view; inside it Esc marks the group you are on as read, which cannot be taken back if you hit it while skimming.", "Reúne todo lo no leído en una sola vista; ahí Esc marca como leído el grupo actual, y eso no se puede deshacer si lo pulsas de pasada.", "Junta tudo o que está não lido em uma visão; ali o Esc marca o grupo atual como lido, e isso não volta atrás se você apertar sem pensar.", "未読をひとつの画面に集めて見せます。この画面の Esc はいまの束を既読にする意味なので、流し読み中に押すと戻せません。", "Sammelt alles Ungelesene in einer Ansicht; dort markiert Esc die aktuelle Gruppe als gelesen — unwiderruflich, wenn man es beim Überfliegen drückt.", "Rassemble tous les non-lus dans une seule vue ; là, Esc marque le groupe courant comme lu, sans retour possible si vous appuyez en survolant.", "बिना पढ़े सब कुछ एक ही दृश्य में जुटा देता है; वहाँ Esc मौजूदा समूह को पढ़ा हुआ चिह्नित करता है, और सरसरी नज़र में दबा दें तो वापसी नहीं।", "把所有未读汇总到一个视图里；在这里 Esc 是把当前这组标为已读，随手一按就收不回来了。", "把所有未讀匯總到一個檢視裡；在這裡 Esc 是把目前這組標為已讀，隨手一按就收不回來了。"],

  /* ───────── Views ───────── */
  'slack-home-view': ["채널 목록이 있는 홈 화면으로 돌아옵니다. 윈도우는 Ctrl+Shift+1인데 맥은 Cmd가 아니라 Ctrl+1이라, 이 갈래에서 특히 자주 틀립니다.", "Returns to the home view with the channel list; Windows uses Ctrl+Shift+1 while mac uses Ctrl+1 with Ctrl and not Cmd, which is a common miss.", "Vuelve a la vista de inicio con la lista de canales; en Windows es Ctrl+Shift+1 y en mac Ctrl+1 con Ctrl, no Cmd, algo que se falla a menudo.", "Volta para a visão inicial com a lista de canais; no Windows é Ctrl+Shift+1 e no mac Ctrl+1 com Ctrl, não Cmd, o que erra muita gente.", "channel の一覧があるホーム画面へ戻ります。Windows は Ctrl+Shift+1 ですが Mac は Cmd ではなく Ctrl+1 で、この系統は特に間違えやすいところです。", "Kehrt zur Startansicht mit der Kanalliste zurück; Windows nutzt Ctrl+Shift+1, der Mac Ctrl+1 mit Ctrl statt Cmd — ein häufiger Fehlgriff.", "Revient à l'accueil avec la liste des canaux ; Windows utilise Ctrl+Shift+1 et mac Ctrl+1 avec Ctrl et non Cmd, une erreur fréquente.", "channel सूची वाले home दृश्य पर लौटता है; Windows पर Ctrl+Shift+1 है और mac पर Cmd नहीं, Ctrl+1 — यहीं सबसे ज़्यादा चूक होती है।", "回到有频道列表的主视图；Windows 是 Ctrl+Shift+1，mac 却是 Ctrl+1 用 Ctrl 而非 Cmd，这一类最容易按错。", "回到有頻道清單的主檢視；Windows 是 Ctrl+Shift+1，mac 卻是 Ctrl+1 用 Ctrl 而非 Cmd，這一類最容易按錯。"],
  'slack-dms-view': ["다이렉트 메시지만 모아 놓은 화면을 엽니다. 옆자리 Ctrl+K는 옮겨 다니는 창이니, 한 글자 차이로 다른 곳이 열립니다.", "Opens the view that holds only direct messages; the neighbouring Ctrl+K is the switcher, so one key apart takes you somewhere else entirely.", "Abre la vista que reúne solo los mensajes directos; el vecino Ctrl+K es el conmutador, así que una tecla de diferencia lleva a otro sitio.", "Abre a visão que reúne só as mensagens diretas; o vizinho Ctrl+K é o alternador, então uma tecla de diferença leva a outro lugar.", "ダイレクトメッセージだけを集めた画面を開きます。隣の Ctrl+K は移動の窓なので、一文字違いで別の場所が開きます。", "Öffnet die Ansicht mit ausschließlich Direktnachrichten; das benachbarte Ctrl+K ist der Umschalter — eine Taste daneben führt ganz woandershin.", "Ouvre la vue réservée aux messages privés ; le voisin Ctrl+K est le sélecteur, une touche d'écart mène ailleurs.", "केवल direct messages वाला दृश्य खोलता है; बग़ल वाला Ctrl+K switcher है, इसलिए एक अक्षर के फ़र्क़ से कहीं और पहुँच जाते हैं।", "打开只放私信的视图；旁边的 Ctrl+K 是切换器，差一个键就去了别处。", "打開只放私訊的檢視；旁邊的 Ctrl+K 是切換器，差一個鍵就去了別處。"],
  'slack-activity-view': ["내 이름이 불린 곳과 이모지 반응을 한 화면에 모읍니다. 채널을 다 훑지 않고도 나에게 온 것만 볼 수 있습니다.", "Collects the mentions of your name and the reactions you got in one view, so you can see what came to you without combing the channels.", "Reúne las menciones a tu nombre y las reacciones que recibiste en una vista, para ver lo tuyo sin recorrer los canales.", "Reúne as menções ao seu nome e as reações que você recebeu em uma visão, para ver o que é seu sem varrer os canais.", "自分の名前が呼ばれた場所と絵文字の反応をひとつの画面に集めます。channel を全部たどらずに自分宛てのものだけ見られます。", "Sammelt Erwähnungen Ihres Namens und erhaltene Reaktionen in einer Ansicht, damit Sie Ihres sehen, ohne alle Kanäle durchzugehen.", "Rassemble les mentions de votre nom et les réactions reçues dans une vue, pour voir ce qui vous concerne sans parcourir les canaux.", "आपके नाम के उल्लेख और मिली emoji प्रतिक्रियाएँ एक दृश्य में जुटा देता है, ताकि सारे channel छाने बिना अपना हिस्सा दिख जाए।", "把提到你的地方和你收到的表情回应汇总到一个视图，不用把频道翻个遍就能看到跟你有关的。", "把提到你的地方和你收到的表情回應匯總到一個檢視，不用把頻道翻個遍就能看到跟你有關的。"],
  'slack-threads-view': ["내가 따라가고 있는 스레드를 모아 봅니다. 스레드 답글은 채널 본문에 뜨지 않으므로, 이 화면을 보지 않으면 놓친 대화가 쌓입니다.", "Collects the threads you follow; replies inside a thread never appear in the channel itself, so conversations pile up unseen unless you open this view.", "Reúne los hilos que sigues; las respuestas dentro de un hilo no aparecen en el canal, así que las conversaciones se acumulan si no abres esta vista.", "Reúne os tópicos que você segue; respostas dentro de um tópico não aparecem no canal, então conversas se acumulam se você não abrir esta visão.", "自分が追っているスレッドを集めて見ます。スレッドの返信は channel 本体には出ないので、この画面を見ないと見落ちが溜まります。", "Sammelt die Threads, denen Sie folgen; Antworten in einem Thread erscheinen nie im Kanal selbst, also stauen sich unbemerkte Gespräche.", "Rassemble les fils que vous suivez ; les réponses dans un fil n'apparaissent pas dans le canal, alors les conversations s'accumulent sans cette vue.", "आप जिन threads का पीछा कर रहे हैं उन्हें जुटाता है; thread के भीतर के उत्तर channel में नहीं दिखते, इसलिए यह दृश्य न देखें तो बातचीत जमा होती रहती है।", "汇总你正在关注的话题；话题里的回复不会出现在频道正文，所以不看这个视图就会漏掉一堆对话。", "匯總你正在關注的討論串；討論串裡的回覆不會出現在頻道內容，所以不看這個檢視就會漏掉一堆對話。"],
  'slack-browse-channels': ["들어갈 수 있는 채널 목록을 엽니다. 아직 들어가지 않은 채널도 사람 수와 함께 보여 주므로, 어디에 이야기가 있는지 여기서 고릅니다.", "Opens the directory of channels you can join, showing member counts even for the ones you are not in yet, so you can pick where the talking happens.", "Abre el directorio de canales a los que puedes unirte, con el número de miembros incluso de los que no integras, para elegir dónde está la conversación.", "Abre o diretório de canais que você pode entrar, com o número de membros mesmo dos que você não integra, para escolher onde a conversa acontece.", "入れる channel の一覧を開きます。まだ入っていない channel も人数付きで並ぶので、話がある場所をここで選べます。", "Öffnet das Verzeichnis der Kanäle, die Sie betreten können, mit Mitgliederzahlen auch für noch nicht betretene — so wählen Sie, wo geredet wird.", "Ouvre l'annuaire des canaux que vous pouvez rejoindre, avec le nombre de membres même pour ceux où vous n'êtes pas, afin de choisir où ça discute.", "जिन channels में शामिल हो सकते हैं उनकी सूची खोलता है, और जिनमें आप नहीं हैं उनकी सदस्य-संख्या भी दिखाता है, ताकि चुन सकें कि बात कहाँ हो रही है।", "打开你可以加入的频道目录，连没加入的也显示成员数，方便挑出讨论真正发生的地方。", "打開你可以加入的頻道目錄，連沒加入的也顯示成員數，方便挑出討論真正發生的地方。"],
  'slack-hide-right-sidebar': ["오른쪽 판을 접어 본문을 넓힙니다 — 스레드나 프로필, 캔버스가 열려 있던 그 자리입니다. 왼쪽 사이드바를 접는 기본 단축키는 슬랙에 없습니다.", "Collapses the right pane — where a thread, a profile or a canvas sits — to widen the messages; Slack has no default shortcut for the left sidebar.", "Colapsa el panel derecho, donde vive un hilo, un perfil o un canvas, para ensanchar los mensajes; Slack no tiene atajo por defecto para la barra izquierda.", "Recolhe o painel direito, onde fica um tópico, um perfil ou um canvas, para alargar as mensagens; o Slack não tem atalho padrão para a barra esquerda.", "右の枠を畳んで本文を広げます — スレッドやプロフィール、canvas が開いていたあの場所です。左のサイドバーを畳む既定のキーは Slack にはありません。", "Klappt den rechten Bereich ein — dort sitzen Thread, Profil oder Canvas — und verbreitert die Nachrichten; für die linke Seitenleiste gibt es kein Standardkürzel.", "Replie le volet droit — celui du fil, du profil ou du canvas — pour élargir les messages ; Slack n'a aucun raccourci par défaut pour la barre latérale gauche.", "दाएँ हिस्से को समेटकर संदेशों की जगह बढ़ाता है — वहीं thread, profile या canvas खुलता है; बाईं sidebar समेटने का कोई डिफ़ॉल्ट shortcut Slack में नहीं है।", "收起右侧面板——话题、个人资料或 canvas 就在那儿——把消息区变宽；Slack 没有收起左侧边栏的默认快捷键。", "收起右側面板——討論串、個人資料或 canvas 就在那兒——把訊息區變寬；Slack 沒有收起左側邊欄的預設快速鍵。"],
  'slack-conversation-details': ["지금 대화의 자세한 정보를 오른쪽 판에 엽니다. 사람과 고정된 글, 파일이 여기 모여 있고, 그 판을 다시 접는 것은 Ctrl+. 입니다.", "Opens the details of this conversation in the right pane, where the members, pinned items and files live; Ctrl+. closes that pane again.", "Abre los detalles de la conversación en el panel derecho, donde están los miembros, los elementos fijados y los archivos; Ctrl+. cierra ese panel.", "Abre os detalhes da conversa no painel direito, onde ficam membros, itens fixados e arquivos; Ctrl+. fecha esse painel.", "いまの会話の詳しい情報を右の枠に開きます。参加者や固定した投稿、ファイルがここに集まり、その枠を畳むのは Ctrl+. です。", "Öffnet die Details dieser Unterhaltung im rechten Bereich mit Mitgliedern, Angepinntem und Dateien; Ctrl+. schließt diesen Bereich wieder.", "Ouvre les détails de la conversation dans le volet droit, où se trouvent membres, épingles et fichiers ; Ctrl+. referme ce volet.", "इस बातचीत का ब्योरा दाएँ हिस्से में खोलता है, जहाँ सदस्य, pin किए संदेश और फ़ाइलें रहती हैं; उस हिस्से को समेटना Ctrl+. है।", "在右侧面板打开这个会话的详情，成员、置顶和文件都在那里；再收起这个面板是 Ctrl+.。", "在右側面板打開這個對話的詳細資料，成員、釘選和檔案都在那裡；再收起這個面板是 Ctrl+.。"],

  /* ───────── Workspaces ───────── */
  'slack-workspace-switcher': ["워크스페이스를 고르는 줄을 펴고 접습니다. Ctrl에 번호를 더하면 그 자리 워크스페이스로 곧장 갑니다.", "Shows and hides the workspace switcher; Ctrl together with a number jumps straight to the workspace in that position.", "Muestra y oculta el conmutador de espacios de trabajo; Ctrl con un número salta directo al que ocupa esa posición.", "Mostra e esconde o alternador de workspaces; Ctrl com um número salta direto para o que está naquela posição.", "ワークスペースを選ぶ列を開いたり閉じたりします。Ctrl に番号を足すと、その位置のワークスペースへ直接移れます。", "Zeigt und verbirgt den Workspace-Umschalter; Ctrl mit einer Zahl springt direkt zum Workspace an dieser Position.", "Affiche et masque le sélecteur d'espaces de travail ; Ctrl avec un chiffre saute directement à celui de cette position.", "workspace चुनने की पट्टी दिखाता-छिपाता है; Ctrl के साथ अंक दबाने पर उस स्थान वाले workspace पर सीधे पहुँच जाते हैं।", "显示或隐藏工作区切换栏；Ctrl 加数字可以直接跳到那个位置的工作区。", "顯示或隱藏工作區切換列；Ctrl 加數字可以直接跳到那個位置的工作區。"],
  'slack-next-workspace': ["다음 워크스페이스로 넘어갑니다. 윈도우와 맥이 같은 키이고, 슬랙 안에서는 탭이 아니라 워크스페이스가 바뀝니다.", "Moves to the next workspace; the key is the same on Windows and mac, and inside Slack it changes workspaces rather than tabs.", "Pasa al siguiente espacio de trabajo; la tecla es la misma en Windows y mac, y dentro de Slack cambia espacios, no pestañas.", "Vai para o próximo workspace; a tecla é a mesma no Windows e no mac, e dentro do Slack muda workspaces, não abas.", "次のワークスペースへ移ります。Windows と Mac で同じキーで、Slack の中ではタブではなくワークスペースが変わります。", "Wechselt zum nächsten Workspace; die Taste ist auf Windows und Mac gleich, und in Slack wechselt sie Workspaces statt Tabs.", "Passe à l'espace de travail suivant ; la touche est la même sous Windows et mac, et dans Slack elle change d'espace, pas d'onglet.", "अगले workspace पर जाता है; Windows और mac में यही key है, और Slack के भीतर यह tab नहीं, workspace बदलता है।", "切到下一个工作区；Windows 和 mac 用同一个键，而在 Slack 里它换的是工作区不是标签页。", "切到下一個工作區；Windows 和 mac 用同一個鍵，而在 Slack 裡它換的是工作區不是標籤頁。"],
  'slack-previous-workspace': ["앞 워크스페이스로 돌아갑니다. 워크스페이스가 하나뿐이면 눌러도 아무 일이 없습니다.", "Goes back to the previous workspace; with only one workspace signed in, pressing it does nothing at all.", "Vuelve al espacio de trabajo anterior; si solo tienes uno conectado, no pasa nada al pulsarlo.", "Volta ao workspace anterior; com apenas um conectado, apertar não faz nada.", "前のワークスペースへ戻ります。ワークスペースが一つだけなら押しても何も起きません。", "Geht zum vorherigen Workspace zurück; ist nur einer angemeldet, passiert gar nichts.", "Revient à l'espace de travail précédent ; avec un seul espace connecté, appuyer ne fait rien.", "पिछले workspace पर लौटता है; केवल एक workspace जुड़ा हो तो दबाने से कुछ नहीं होता।", "回到上一个工作区；只登录了一个工作区时按了也没反应。", "回到上一個工作區；只登入了一個工作區時按了也沒反應。"],

  /* ───────── Huddles ───────── */
  'slack-huddle': ["지금 있는 대화에서 허들을 켜거나 들어가거나 나옵니다. 엉뚱한 채널에서 누르면 그 채널에 허들이 열려 사람들에게 알림이 갑니다.", "Starts, joins or leaves a huddle in the conversation you are in; pressed in the wrong channel it opens a huddle there and pings everyone.", "Inicia, entra o sale de un huddle en la conversación actual; pulsado en el canal equivocado abre un huddle allí y avisa a todos.", "Inicia, entra ou sai de um huddle na conversa atual; apertado no canal errado abre um huddle lá e avisa todo mundo.", "いまいる会話で huddle を始めたり、入ったり、出たりします。違う channel で押すとその channel に huddle が開き、皆に通知が飛びます。", "Startet, betritt oder verlässt ein Huddle in der aktuellen Unterhaltung; im falschen Kanal gedrückt, öffnet es dort ein Huddle und benachrichtigt alle.", "Démarre, rejoint ou quitte un huddle dans la conversation courante ; pressé dans le mauvais canal, il y ouvre un huddle et prévient tout le monde.", "आप जिस बातचीत में हैं वहाँ huddle शुरू करता, उसमें शामिल होता या बाहर आता है; ग़लत channel में दबाएँ तो वहीं huddle खुलकर सबको सूचना चली जाती है।", "在你当前所在的会话里开始、加入或离开一个 huddle；在错误的频道按下就会在那儿开 huddle 并通知所有人。", "在你目前所在的對話裡開始、加入或離開一個 huddle；在錯誤的頻道按下就會在那兒開 huddle 並通知所有人。"],
  'slack-huddle-mute': ["허들에서 내 마이크를 켜고 끕니다. 말하기 시작했는데 소리가 안 나갈 때 찾는 그 키입니다.", "Mutes and unmutes your microphone in a huddle — the key you hunt for the moment you start talking and nobody hears you.", "Silencia y activa tu micrófono en un huddle: la tecla que buscas justo cuando empiezas a hablar y nadie te oye.", "Desliga e liga o seu microfone num huddle: a tecla que você procura quando começa a falar e ninguém ouve.", "huddle で自分のマイクを入れたり切ったりします。話し始めたのに声が届かないときに探すのがこのキーです。", "Schaltet Ihr Mikrofon im Huddle stumm und wieder frei — die Taste, die man sucht, wenn man redet und keiner etwas hört.", "Coupe et rétablit votre micro dans un huddle : la touche qu'on cherche quand on parle sans que personne n'entende.", "huddle में अपना microphone बंद-चालू करता है — जब आप बोलने लगें और किसी को सुनाई न दे, तब यही key खोजी जाती है।", "在 huddle 里开关你的麦克风——一开口发现没人听得到时，找的就是这个键。", "在 huddle 裡開關你的麥克風——一開口發現沒人聽得到時，找的就是這個鍵。"],

  /* ───────── Message actions ───────── */
  'slack-edit-message': ["고른 내 메시지를 고칩니다. 메시지에 초점이 있어야 듣는 키이고, 빈 입력창에서 방향키로 마지막 메시지를 불러오는 기본 단축키는 슬랙에 없습니다.", "Edits the message of yours that has focus; the letter only works on a focused message, and Slack has no default shortcut that pulls up your last message from an empty box.", "Edita el mensaje tuyo que tiene el foco; la letra solo actúa sobre un mensaje enfocado, y Slack no trae atajo para recuperar tu último mensaje desde el cuadro vacío.", "Edita a sua mensagem que está em foco; a letra só funciona sobre uma mensagem em foco, e o Slack não tem atalho padrão para puxar sua última mensagem do campo vazio.", "焦点のある自分のメッセージを直します。メッセージに焦点が無いと効かず、空の入力欄から最後のメッセージを呼び出す既定のキーは Slack にはありません。", "Bearbeitet die eigene Nachricht, die den Fokus hat; der Buchstabe wirkt nur auf eine fokussierte Nachricht, und für das Zurückholen der letzten Nachricht aus dem leeren Feld gibt es kein Standardkürzel.", "Modifie votre message qui a le focus ; la lettre n'agit que sur un message ciblé, et Slack n'offre aucun raccourci pour rappeler votre dernier message depuis la zone vide.", "जिस अपने संदेश पर focus है उसे बदलता है; यह अक्षर केवल focus किए संदेश पर चलता है, और ख़ाली बक्से से अपना पिछला संदेश लाने का कोई डिफ़ॉल्ट shortcut Slack में नहीं है।", "编辑你被选中的那条消息；这个字母只在消息处于焦点时有效，而 Slack 没有从空输入框调出上一条消息的默认快捷键。", "編輯你被選取的那條訊息；這個字母只在訊息處於焦點時有效，而 Slack 沒有從空輸入框調出上一條訊息的預設快速鍵。"],
  'slack-delete-message': ["고른 내 메시지를 지웁니다. 정말 지울지 한 번 묻고, 맥에서는 Backspace처럼 움직이는 그 Delete 키를 씁니다.", "Deletes the message of yours that has focus after asking once; on mac the key is the one labelled Delete that behaves like Backspace.", "Borra tu mensaje enfocado tras preguntar una vez; en mac la tecla es la marcada Delete, que funciona como Backspace.", "Apaga a sua mensagem em foco depois de perguntar uma vez; no mac a tecla é a marcada Delete, que age como Backspace.", "焦点のある自分のメッセージを消します。本当に消すか一度尋ね、Mac では Backspace のように働くあの Delete キーを使います。", "Löscht die fokussierte eigene Nachricht nach einer Rückfrage; auf dem Mac ist es die mit Delete beschriftete Taste, die wie Backspace arbeitet.", "Supprime votre message ciblé après une confirmation ; sur mac, la touche est celle marquée Delete, qui agit comme Backspace.", "focus किए अपने संदेश को एक बार पूछकर मिटा देता है; mac पर वह Delete वाली key है जो Backspace की तरह काम करती है।", "删除你被选中的那条消息，会先问一次；mac 上用的是标着 Delete、实际当退格用的那个键。", "刪除你被選取的那條訊息，會先問一次；mac 上用的是標著 Delete、實際當退格用的那個鍵。"],
  'slack-reply-in-thread': ["고른 메시지의 스레드를 열어 거기에 답합니다. Right 방향키도 같은 일을 하고, 여기 쓴 답글은 채널 본문에 뜨지 않습니다.", "Opens the thread of the focused message to reply there; the Right arrow does the same, and what you write stays out of the channel body.", "Abre el hilo del mensaje enfocado para responder ahí; la flecha derecha hace lo mismo, y lo que escribes no aparece en el canal.", "Abre o tópico da mensagem em foco para responder ali; a seta direita faz o mesmo, e o que você escreve não aparece no canal.", "焦点のあるメッセージのスレッドを開いてそこに返します。Right 矢印も同じ働きで、ここに書いた返信は channel 本体には出ません。", "Öffnet den Thread der fokussierten Nachricht zum Antworten; die Rechts-Pfeiltaste tut dasselbe, und Geschriebenes bleibt aus dem Kanal heraus.", "Ouvre le fil du message ciblé pour y répondre ; la flèche droite fait pareil, et ce que vous écrivez ne paraît pas dans le canal.", "focus किए संदेश का thread खोलकर वहीं उत्तर देता है; Right arrow भी वही करता है, और वहाँ लिखा उत्तर channel में नहीं दिखता।", "打开被选中消息的话题，在里面回复；右方向键也一样，而在这里写的回复不会出现在频道正文。", "打開被選取訊息的討論串，在裡面回覆；右方向鍵也一樣，而在這裡寫的回覆不會出現在頻道內容。"],
  'slack-forward-message': ["고른 메시지를 다른 대화로 넘깁니다. 한 마디 덧붙여 보낼 수 있어, 링크만 복사해 붙이는 것보다 맥락이 남습니다.", "Forwards the focused message to another conversation; you can add a line with it, which keeps more context than pasting a link.", "Reenvía el mensaje enfocado a otra conversación; puedes añadir una línea, lo que conserva más contexto que pegar un enlace.", "Encaminha a mensagem em foco para outra conversa; você pode acrescentar uma linha, o que guarda mais contexto do que colar um link.", "焦点のあるメッセージを別の会話へ回します。一言添えて送れるので、リンクを貼るだけより文脈が残ります。", "Leitet die fokussierte Nachricht in eine andere Unterhaltung weiter; man kann eine Zeile dazuschreiben, was mehr Zusammenhang bewahrt als ein Link.", "Transfère le message ciblé vers une autre conversation ; on peut y joindre un mot, ce qui garde plus de contexte qu'un lien collé.", "focus किए संदेश को दूसरी बातचीत में भेजता है; साथ में एक पंक्ति जोड़ सकते हैं, जिससे link चिपकाने से ज़्यादा संदर्भ बचा रहता है।", "把被选中的消息转到另一个会话；可以顺手加一句话，比只粘个链接留下的上下文更多。", "把被選取的訊息轉到另一個對話；可以順手加一句話，比只貼個連結留下的上下文更多。"],
  'slack-pin-message': ["고른 메시지를 이 대화에 고정하거나 뗍니다. 사람들이 없다고 여기는 것과 달리 실제로 기본 키가 있고, 고정한 것은 대화 정보 판에 모입니다.", "Pins or unpins the focused message in this conversation; unlike what people assume it does have a default key, and pinned items gather in the details pane.", "Fija o quita de fijados el mensaje enfocado en esta conversación; al contrario de lo que se cree, sí tiene tecla por defecto, y lo fijado se reúne en el panel de detalles.", "Fixa ou desafixa a mensagem em foco nesta conversa; ao contrário do que se pensa, ela tem tecla padrão, e o que é fixado se junta no painel de detalhes.", "焦点のあるメッセージをこの会話に固定したり外したりします。無いと思われがちですが既定のキーが実際にあり、固定したものは会話情報の枠に集まります。", "Pinnt die fokussierte Nachricht in dieser Unterhaltung an oder löst sie; anders als vermutet gibt es dafür ein Standardkürzel, und Angepinntes sammelt sich im Detailbereich.", "Épingle ou désépingle le message ciblé dans cette conversation ; contrairement à ce qu'on croit, il a bien une touche par défaut, et les épingles se retrouvent dans le volet des détails.", "focus किए संदेश को इस बातचीत में pin या unpin करता है; लोगों की धारणा के उलट इसका डिफ़ॉल्ट key है, और pin की गई चीज़ें ब्योरे के हिस्से में जमा होती हैं।", "把被选中的消息在这个会话里置顶或取消置顶；和大家以为的不同，它确实有默认按键，置顶的内容会汇集在详情面板里。", "把被選取的訊息在這個對話裡釘選或取消釘選；和大家以為的不同，它確實有預設按鍵，釘選的內容會匯集在詳細資料面板裡。"],
  'slack-save-message': ["고른 메시지를 나중에 볼 것으로 담아 둡니다. 예전에 별을 붙이던 그 기능이고, 담아 둔 것은 나만 봅니다.", "Saves the focused message for later; this is what starring used to be, and only you can see what you saved.", "Guarda el mensaje enfocado para después; es lo que antes era marcar con estrella, y solo tú ves lo guardado.", "Salva a mensagem em foco para depois; é o que antes era marcar com estrela, e só você vê o que guardou.", "焦点のあるメッセージを後で見るものとして取り置きます。かつての星印がこれで、取り置いたものは自分にしか見えません。", "Speichert die fokussierte Nachricht für später; das war früher das Sternchen, und nur Sie sehen Gespeichertes.", "Enregistre le message ciblé pour plus tard ; c'est l'ancien système d'étoile, et vous seul voyez vos enregistrements.", "focus किए संदेश को बाद के लिए सहेज लेता है; पहले यही तारा लगाना था, और सहेजा हुआ केवल आपको दिखता है।", "把被选中的消息存起来稍后再看；这就是以前的加星，存的东西只有你能看到。", "把被選取的訊息存起來稍後再看；這就是以前的加星，存的東西只有你能看到。"],
  'slack-mark-above-unread': ["고른 메시지 위쪽을 다시 읽지 않은 것으로 돌립니다. 길게 밀린 채널을 나중에 처음부터 읽으려고 표시해 두는 데 씁니다.", "Marks everything above the focused message as unread again — the way to bookmark a long backlog you mean to read from the top later.", "Marca como no leído todo lo que está sobre el mensaje enfocado: así se deja señalado un atraso largo para leerlo desde arriba más tarde.", "Marca como não lido tudo acima da mensagem em foco: é como se deixa um marcador num atraso longo para ler do começo depois.", "焦点のあるメッセージより上を、また未読に戻します。溜まった channel を後で頭から読むための目印として使えます。", "Markiert alles oberhalb der fokussierten Nachricht wieder als ungelesen — so setzt man eine Lesemarke in einen langen Rückstand.", "Remarque comme non lu tout ce qui se trouve au-dessus du message ciblé : de quoi signaler un retard à relire depuis le début.", "focus किए संदेश के ऊपर का सब फिर बिना पढ़ा चिह्नित कर देता है — लंबे बकाया को बाद में शुरू से पढ़ने के लिए निशान।", "把被选中消息上方的内容重新标为未读——想稍后从头读一段长长的积压，就这么做标记。", "把被選取訊息上方的內容重新標為未讀——想稍後從頭讀一段長長的積壓，就這麼做標記。"],
  'slack-remind-me': ["고른 메시지를 두고 알림을 걸어 둡니다. 정한 시각이 되면 슬랙봇이 그 메시지를 다시 보내 주므로 잊어도 됩니다.", "Sets a reminder about the focused message; when the time comes Slackbot sends the message back to you, so you are allowed to forget it.", "Programa un recordatorio sobre el mensaje enfocado; a la hora fijada Slackbot te lo devuelve, así que puedes olvidarlo.", "Programa um lembrete sobre a mensagem em foco; na hora marcada o Slackbot devolve a mensagem, então você pode esquecer.", "焦点のあるメッセージについて通知を仕掛けます。決めた時刻になると Slackbot がそのメッセージを送り直すので、忘れても大丈夫です。", "Legt eine Erinnerung zur fokussierten Nachricht an; zur gewählten Zeit schickt Slackbot sie zurück, Sie dürfen sie also vergessen.", "Programme un rappel sur le message ciblé ; à l'heure dite, Slackbot vous le renvoie, vous pouvez donc l'oublier.", "focus किए संदेश के लिए याद-दिलावा लगाता है; तय समय पर Slackbot वही संदेश लौटा देता है, इसलिए भूल जाना ठीक है।", "给被选中的消息设个提醒；到点 Slackbot 会把这条消息再发给你，所以忘了也没关系。", "給被選取的訊息設個提醒；到點 Slackbot 會把這條訊息再發給你，所以忘了也沒關係。"],
  'slack-react': ["고른 메시지에 이모지 반응을 고르는 창을 엽니다. 입력창에서 이모지를 고르는 키는 자판 배치에 따라 달라 하나로 적을 수 없지만, 반응은 어디서나 이 한 글자입니다.", "Opens the emoji picker on the focused message; the picker for the message box has no single spelling because it depends on your keyboard layout, but reacting is this one letter everywhere.", "Abre el selector de emoji sobre el mensaje enfocado; el del cuadro de mensaje no tiene una forma única porque depende del teclado, pero reaccionar es esta letra en cualquier sitio.", "Abre o seletor de emoji na mensagem em foco; o do campo de mensagem não tem uma forma única porque depende do teclado, mas reagir é esta letra em qualquer lugar.", "焦点のあるメッセージに絵文字の反応を選ぶ窓を開きます。入力欄の絵文字を選ぶキーはキーボード配列で変わるため一つに書けませんが、反応はどこでもこの一文字です。", "Öffnet die Emoji-Auswahl für die fokussierte Nachricht; die Auswahl im Eingabefeld lässt sich nicht einheitlich angeben, weil sie vom Tastaturlayout abhängt, das Reagieren aber ist überall dieser Buchstabe.", "Ouvre le sélecteur d'emoji sur le message ciblé ; celui de la zone de saisie n'a pas d'écriture unique car il dépend de la disposition du clavier, mais réagir tient à cette lettre partout.", "focus किए संदेश पर emoji चुनने का बक्सा खोलता है; संदेश-बक्से का emoji चुनने वाला key keyboard layout पर निर्भर है इसलिए एक रूप में नहीं लिखा जा सकता, पर प्रतिक्रिया हर जगह यही अक्षर है।", "在被选中的消息上打开表情选择框；输入框里的表情选择键取决于键盘布局，写不成统一的一种，而回应在哪儿都是这一个字母。", "在被選取的訊息上打開表情選擇框；輸入框裡的表情選擇鍵取決於鍵盤配置，寫不成統一的一種，而回應在哪兒都是這一個字母。"],

  /* ───────── Formatting ───────── */
  'slack-new-line': ["보내지 않고 줄만 바꿉니다. Enter를 보내기로 두었을 때 이야기이고, 그 설정을 바꿔 두면 두 키의 뜻이 서로 바뀝니다.", "Breaks the line without sending; that holds while Enter is set to send, and flipping that preference swaps what the two keys do.", "Salta de línea sin enviar; eso vale mientras Enter esté configurado para enviar, y cambiar esa preferencia intercambia el papel de las dos teclas.", "Quebra a linha sem enviar; isso vale enquanto o Enter estiver configurado para enviar, e mudar essa preferência troca o papel das duas teclas.", "送らずに行だけ変えます。Enter を送信に設定しているときの話で、その設定を変えると二つのキーの意味が入れ替わります。", "Fügt einen Zeilenumbruch ein, ohne zu senden; das gilt, solange Enter zum Senden dient — kippt man die Einstellung, tauschen beide Tasten die Rollen.", "Passe à la ligne sans envoyer ; cela vaut tant qu'Enter sert à envoyer, et inverser ce réglage échange le rôle des deux touches.", "भेजे बिना नई पंक्ति बनाता है; यह तब तक सही है जब Enter भेजने पर सेट हो, और वह सेटिंग बदलने पर दोनों keys के काम आपस में बदल जाते हैं।", "只换行不发送；这在 Enter 设为发送时成立，改了那个设置，两个键的作用就互换。", "只換行不發送；這在 Enter 設為發送時成立，改了那個設定，兩個鍵的作用就互換。"],
  'slack-bold': ["고른 글자를 굵게 만듭니다. 서식 도구줄을 감춰 두어도 키는 그대로 듣습니다.", "Makes the selected text bold; the key keeps working even when you have hidden the formatting toolbar.", "Pone en negrita el texto seleccionado; la tecla sigue funcionando aunque hayas ocultado la barra de formato.", "Deixa o texto selecionado em negrito; a tecla continua funcionando mesmo com a barra de formatação escondida.", "選んだ文字を太くします。書式のツールバーを隠していてもキーはそのまま効きます。", "Setzt den markierten Text fett; die Taste wirkt auch dann, wenn die Formatierungsleiste ausgeblendet ist.", "Met le texte sélectionné en gras ; la touche fonctionne même si la barre de mise en forme est masquée.", "चुने हुए पाठ को गाढ़ा करता है; formatting toolbar छिपा रखा हो तब भी key काम करती है।", "把选中的文字加粗；即使你把格式工具栏藏起来了，这个键照样有效。", "把選取的文字加粗；即使你把格式工具列藏起來了，這個鍵照樣有效。"],
  'slack-italic': ["고른 글자를 기울입니다. 슬랙은 밑줄 서식을 보내는 기능이 없어, 강조는 굵게와 기울임 둘로 끝납니다.", "Italicizes the selected text; Slack cannot send underlined text at all, so emphasis comes down to bold and italic.", "Pone en cursiva el texto seleccionado; Slack no puede enviar texto subrayado, así que el énfasis se reduce a negrita y cursiva.", "Deixa o texto selecionado em itálico; o Slack não envia texto sublinhado, então a ênfase se resume a negrito e itálico.", "選んだ文字を斜めにします。Slack には下線を送る書式が無いので、強調は太字と斜体の二つだけです。", "Setzt den markierten Text kursiv; Slack kann unterstrichenen Text nicht senden, Hervorhebung bleibt also fett und kursiv.", "Met le texte sélectionné en italique ; Slack ne sait pas envoyer de texte souligné, l'emphase se limite donc au gras et à l'italique.", "चुने हुए पाठ को तिरछा करता है; Slack रेखांकित पाठ भेज ही नहीं सकता, इसलिए ज़ोर देने के लिए गाढ़ा और तिरछा ही बचते हैं।", "把选中的文字变斜体；Slack 根本发不出下划线格式，所以强调就只有加粗和斜体两种。", "把選取的文字變斜體；Slack 根本發不出底線格式，所以強調就只有加粗和斜體兩種。"],
  'slack-strikethrough': ["고른 글자에 취소선을 긋습니다. 이미 정해진 것을 지우지 않고 뒤집을 때 팀들이 쓰는 표시입니다.", "Strikes through the selected text — the mark teams use to overturn something already agreed without deleting it.", "Tacha el texto seleccionado: la marca que usan los equipos para revocar algo ya acordado sin borrarlo.", "Risca o texto selecionado: a marca que as equipes usam para desfazer algo já combinado sem apagar.", "選んだ文字に取り消し線を引きます。すでに決まったことを消さずに覆すとき、チームが使う印です。", "Streicht den markierten Text durch — das Zeichen, mit dem Teams Beschlossenes widerrufen, ohne es zu löschen.", "Barre le texte sélectionné : la marque qu'emploient les équipes pour révoquer une décision sans l'effacer.", "चुने हुए पाठ पर काट की रेखा खींचता है — तय हो चुकी बात को मिटाए बिना पलटने का वह निशान जो टीमें लगाती हैं।", "给选中的文字加删除线——团队用来推翻已定事项而不删掉它的记号。", "給選取的文字加刪除線——團隊用來推翻已定事項而不刪掉它的記號。"],
  'slack-code': ["고른 글자를 한 줄 코드 서식으로 감쌉니다. 이렇게 감싼 안쪽에서는 별표나 밑줄이 서식으로 읽히지 않아, 경로와 명령을 그대로 보여 줄 수 있습니다.", "Wraps the selection in inline code; inside it asterisks and underscores stop meaning formatting, which is how paths and commands survive unchanged.", "Envuelve la selección en código en línea; dentro, los asteriscos y guiones bajos dejan de ser formato, así rutas y comandos se muestran intactos.", "Envolve a seleção em código em linha; ali dentro asteriscos e sublinhados param de significar formatação, e caminhos e comandos aparecem intactos.", "選んだ文字を一行コードの書式で包みます。この中では星印や下線が書式として読まれないので、経路や命令をそのまま見せられます。", "Umschließt die Auswahl mit Inline-Code; darin verlieren Sternchen und Unterstriche ihre Formatierungsbedeutung, sodass Pfade und Befehle unverändert bleiben.", "Entoure la sélection de code en ligne ; à l'intérieur, astérisques et tirets bas cessent d'être du formatage, ce qui préserve chemins et commandes.", "चयन को एक-पंक्ति code में लपेटता है; उसके भीतर तारे और underscore formatting नहीं माने जाते, इसलिए रास्ते और commands वैसे ही दिखते हैं।", "把选中的内容包成行内代码；在里面星号和下划线不再被当成格式，所以路径和命令能原样显示。", "把選取的內容包成行內程式碼；在裡面星號和底線不再被當成格式，所以路徑和命令能原樣顯示。"],
  'slack-code-block': ["여러 줄 코드 덩어리를 만듭니다. 그 안에서 줄을 바꿀 때는 Shift+Enter여야 하고, 그냥 Enter를 누르면 덩어리째 보내집니다.", "Makes a multi-line code block; inside it you still need Shift+Enter for a new line, because plain Enter sends the whole block.", "Crea un bloque de código de varias líneas; dentro sigues necesitando Shift+Enter para saltar de línea, porque Enter a secas lo envía.", "Cria um bloco de código de várias linhas; ali dentro você ainda precisa de Shift+Enter para mudar de linha, pois Enter sozinho envia tudo.", "複数行のコード塊を作ります。中で行を変えるには Shift+Enter が必要で、そのまま Enter を押すと塊ごと送られます。", "Erzeugt einen mehrzeiligen Codeblock; für eine neue Zeile darin braucht man weiterhin Shift+Enter, denn Enter allein sendet den Block.", "Crée un bloc de code multiligne ; à l'intérieur, il faut toujours Shift+Enter pour aller à la ligne, car Enter seul envoie le bloc.", "कई पंक्तियों का code block बनाता है; उसके भीतर नई पंक्ति के लिए Shift+Enter ही चाहिए, क्योंकि सादा Enter पूरा block भेज देता है।", "创建多行代码块；在里面换行仍要用 Shift+Enter，单按 Enter 会把整块发出去。", "建立多行程式碼區塊；在裡面換行仍要用 Shift+Enter，單按 Enter 會把整塊發出去。"],
  'slack-quote': ["고른 줄을 인용 덩어리로 만듭니다. 남의 말을 옮길 때 쓰는 것이고, 인용 안에서도 굵게나 코드 서식을 함께 쓸 수 있습니다.", "Turns the selected lines into a quote block; it is for carrying someone else's words, and bold or code still work inside it.", "Convierte las líneas seleccionadas en una cita; sirve para trasladar palabras de otros, y dentro siguen funcionando la negrita y el código.", "Transforma as linhas selecionadas em uma citação; serve para trazer as palavras de outra pessoa, e negrito ou código continuam funcionando dentro.", "選んだ行を引用の塊にします。他人の言葉を運ぶための書式で、引用の中でも太字やコードの書式を併せて使えます。", "Verwandelt die markierten Zeilen in ein Zitat; es dient dem Übernehmen fremder Worte, und fett oder Code wirken darin weiter.", "Transforme les lignes sélectionnées en citation ; c'est pour rapporter les mots d'un autre, et gras ou code y fonctionnent encore.", "चुनी पंक्तियों को उद्धरण खंड बना देता है; यह किसी और के शब्द लाने के लिए है, और उसके भीतर गाढ़ा या code भी चलते हैं।", "把选中的行变成引用块；用来搬别人的话，引用里照样能用加粗和代码格式。", "把選取的行變成引用區塊；用來搬別人的話，引用裡照樣能用加粗和程式碼格式。"],
  'slack-link': ["고른 글자에 주소를 매어 링크로 만듭니다. 고른 글자 위에 주소를 그대로 붙여 넣어도 같은 결과가 됩니다.", "Attaches a URL to the selected text to make a link; pasting a URL straight over a selection does the same thing.", "Asocia una dirección al texto seleccionado para crear un enlace; pegar una URL sobre la selección da el mismo resultado.", "Associa um endereço ao texto selecionado para criar um link; colar uma URL sobre a seleção dá no mesmo.", "選んだ文字に URL を結び付けて link にします。選んだ文字の上に URL をそのまま貼っても同じ結果になります。", "Verknüpft die Auswahl mit einer URL zu einem Link; eine URL direkt über die Auswahl einzufügen bewirkt dasselbe.", "Associe une adresse au texte sélectionné pour en faire un lien ; coller une URL par-dessus la sélection donne le même résultat.", "चुने हुए पाठ पर पता जोड़कर link बनाता है; चयन के ऊपर सीधे URL चिपकाने से भी वही होता है।", "给选中的文字挂上网址做成链接；直接把网址粘到选区上，效果一样。", "給選取的文字掛上網址做成連結；直接把網址貼到選取範圍上，效果一樣。"],
  'slack-bulleted-list': ["고른 줄을 점 목록으로 바꿉니다. 목록 안에서 Tab을 누르면 한 단 들어가 하위 항목이 됩니다.", "Turns the selected lines into a bulleted list; pressing Tab inside the list indents an item into a sub-item.", "Convierte las líneas seleccionadas en una lista con viñetas; dentro de la lista, Tab sangra un elemento y lo vuelve subelemento.", "Transforma as linhas selecionadas em lista com marcadores; dentro da lista, Tab recua um item e o torna subitem.", "選んだ行を点付きの一覧に変えます。一覧の中で Tab を押すと一段下がって下位の項目になります。", "Verwandelt die markierten Zeilen in eine Aufzählung; Tab innerhalb der Liste rückt einen Punkt zum Unterpunkt ein.", "Transforme les lignes sélectionnées en liste à puces ; dans la liste, Tab indente un élément en sous-élément.", "चुनी पंक्तियों को बिंदु-सूची बना देता है; सूची के भीतर Tab दबाने पर वह मद एक स्तर भीतर जाकर उप-मद बन जाती है।", "把选中的行变成项目符号列表；在列表里按 Tab 可以缩进一级变成子项。", "把選取的行變成項目符號清單；在清單裡按 Tab 可以縮排一級變成子項。"],
  'slack-numbered-list': ["고른 줄을 번호 목록으로 바꿉니다. 번호는 슬랙이 다시 세므로, 가운데 항목을 지워도 순서가 어긋나지 않습니다.", "Turns the selected lines into a numbered list; Slack renumbers them itself, so deleting an item in the middle never leaves a gap.", "Convierte las líneas seleccionadas en una lista numerada; Slack renumera solo, así que borrar un elemento del medio no deja huecos.", "Transforma as linhas selecionadas em lista numerada; o Slack renumera sozinho, então apagar um item do meio não deixa buraco.", "選んだ行を番号付きの一覧に変えます。番号は Slack が数え直すので、途中の項目を消しても順番が崩れません。", "Verwandelt die markierten Zeilen in eine numerierte Liste; Slack zählt selbst neu, sodass ein gelöschter Punkt keine Lücke lässt.", "Transforme les lignes sélectionnées en liste numérotée ; Slack renumérote lui-même, donc supprimer un élément du milieu ne laisse pas de trou.", "चुनी पंक्तियों को अंकित सूची बना देता है; अंक Slack ख़ुद फिर गिनता है, इसलिए बीच की मद मिटाने पर भी क्रम नहीं टूटता।", "把选中的行变成编号列表；编号由 Slack 自己重排，删掉中间一项也不会断号。", "把選取的行變成編號清單；編號由 Slack 自己重排，刪掉中間一項也不會斷號。"],
  'slack-undo': ["입력창에서 방금 한 편집과 서식을 되돌립니다. 보낸 직후에는 같은 조합이 보낸 메시지를 되가져오는 데 쓰이니, 급할 때 이것을 먼저 눌러 봅니다.", "Undoes the last edit or formatting in the message box, and right after sending the same combination takes the message back, so try it first when you regret one.", "Deshace la última edición o formato en el cuadro de mensaje, y justo después de enviar la misma combinación retira el mensaje, así que púlsalo primero si te arrepientes.", "Desfaz a última edição ou formatação no campo de mensagem, e logo após enviar a mesma combinação retira a mensagem, então tente isso primeiro se se arrepender.", "入力欄で直前に行った編集や書式を戻します。送った直後は同じ組み合わせが送信の取り消しに使われるので、後悔したらまずこれを押します。", "Nimmt die letzte Bearbeitung oder Formatierung im Eingabefeld zurück, und direkt nach dem Senden holt dieselbe Kombination die Nachricht zurück.", "Annule la dernière modification ou mise en forme dans la zone de saisie, et juste après l'envoi la même combinaison retire le message.", "संदेश-बक्से में किया अंतिम संपादन या formatting वापस लेता है, और भेजने के तुरंत बाद वही जोड़ी भेजा संदेश वापस खींच लेती है, इसलिए पछतावा हो तो पहले यही दबाएँ।", "撤销消息框里刚做的编辑或格式；刚发出去的那一刻，同一个组合会把消息撤回，所以后悔了先按它。", "復原訊息框裡剛做的編輯或格式；剛發出去的那一刻，同一個組合會把訊息收回，所以後悔了先按它。"],
};
